/**********************************************************************************
Criar stored procedure [dbo].[CategoriesRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[CategoriesRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[CategoriesRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[CategoriesRead](@Login NVARCHAR(MAX)
                                          ,@Filter NVARCHAR(MAX)
                                          ,@Search NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

        IF @Filter IS NULL
            SET @Filter = '{}'
        ELSE IF ISJSON(@Filter) = 0
            THROW 51000, 'Valor de @Filter não está no formato JSON', 1
        IF @Search IS NULL
            SET @Search = '{}'
        ELSE IF ISJSON(@Search) = 0
            THROW 51000, 'Valor de @Search não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Categories') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END
        IF @IsActionList = 1
            SET @OrderBy = '[T].[Name] ASC, [T].[Id] ASC'
        DECLARE @PickerValue nvarchar(25) = NULL

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @SessionId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS tinyint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') AS nvarchar(25)) AS [Name]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.HtmlInputType') AS nvarchar(10)) AS [HtmlInputType]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.HtmlInputAlign') AS nvarchar(6)) AS [HtmlInputAlign]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskEncrypted') AS bit) AS [AskEncrypted]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskMask') AS bit) AS [AskMask]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskListable') AS bit) AS [AskListable]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskDefault') AS bit) AS [AskDefault]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskMinimum') AS bit) AS [AskMinimum]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskMaximum') AS bit) AS [AskMaximum]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.AskInWords') AS bit) AS [AskInWords]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Categories'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@Filter, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@ComparatorPredicate NVARCHAR(MAX)
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id tinyint = CAST(JSON_VALUE(@Filter, '$.Id') AS tinyint)
               ,@WT_Name nvarchar(25) = CAST(JSON_VALUE(@Filter, '$.Name') AS nvarchar(25))
               ,@WT_AskEncrypted bit = CAST(JSON_VALUE(@Filter, '$.AskEncrypted') AS bit)
               ,@WT_AskMask bit = CAST(JSON_VALUE(@Filter, '$.AskMask') AS bit)
               ,@WT_AskListable bit = CAST(JSON_VALUE(@Filter, '$.AskListable') AS bit)
               ,@WT_AskDefault bit = CAST(JSON_VALUE(@Filter, '$.AskDefault') AS bit)
               ,@WT_AskMinimum bit = CAST(JSON_VALUE(@Filter, '$.AskMinimum') AS bit)
               ,@WT_AskMaximum bit = CAST(JSON_VALUE(@Filter, '$.AskMaximum') AS bit)
               ,@WT_AskInWords bit = CAST(JSON_VALUE(@Filter, '$.AskInWords') AS bit)

        IF @WT_Id IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Id] = @T_Id'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'Name' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Name] IS NULL'
        ELSE IF @WT_Name IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Name] = @T_Name'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'AskEncrypted' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[AskEncrypted] IS NULL'
        ELSE IF @WT_AskEncrypted IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[AskEncrypted] = @T_AskEncrypted'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'AskMask' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[AskMask] IS NULL'
        ELSE IF @WT_AskMask IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[AskMask] = @T_AskMask'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'AskListable' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[AskListable] IS NULL'
        ELSE IF @WT_AskListable IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[AskListable] = @T_AskListable'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'AskDefault' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[AskDefault] IS NULL'
        ELSE IF @WT_AskDefault IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[AskDefault] = @T_AskDefault'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'AskMinimum' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[AskMinimum] IS NULL'
        ELSE IF @WT_AskMinimum IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[AskMinimum] = @T_AskMinimum'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'AskMaximum' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[AskMaximum] IS NULL'
        ELSE IF @WT_AskMaximum IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[AskMaximum] = @T_AskMaximum'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'AskInWords' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[AskInWords] IS NULL'
        ELSE IF @WT_AskInWords IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[AskInWords] = @T_AskInWords'
        END
        IF @IsActionList = 1 BEGIN
            SET @PickerValue = CAST(JSON_VALUE(@Filter, '$.Picker.Value') AS nvarchar(25))
            IF @PickerValue IS NULL
                SET @PickerValue = ''
            SET @Where = @Where + ' AND [T].[Name] LIKE ''%'' + @PickerValue + ''%'''
        END ELSE IF @_ IS NULL BEGIN
            DECLARE @G_Id_comparator TINYINT
                   ,@G_Id_v tinyint
                   ,@G_Id_vals NVARCHAR(MAX)
                   ,@G_Id_v1 tinyint
                   ,@G_Id_v2 tinyint
                   ,@G_Name_comparator TINYINT
                   ,@G_Name_v nvarchar(25)
                   ,@G_Name_vals NVARCHAR(MAX)
                   ,@G_Name_v1 nvarchar(25)
                   ,@G_Name_v2 nvarchar(25)
                   ,@G_AskEncrypted_comparator TINYINT
                   ,@G_AskEncrypted_v bit
                   ,@G_AskEncrypted_vals NVARCHAR(MAX)
                   ,@G_AskEncrypted_v1 bit
                   ,@G_AskEncrypted_v2 bit
                   ,@G_AskMask_comparator TINYINT
                   ,@G_AskMask_v bit
                   ,@G_AskMask_vals NVARCHAR(MAX)
                   ,@G_AskMask_v1 bit
                   ,@G_AskMask_v2 bit
                   ,@G_AskListable_comparator TINYINT
                   ,@G_AskListable_v bit
                   ,@G_AskListable_vals NVARCHAR(MAX)
                   ,@G_AskListable_v1 bit
                   ,@G_AskListable_v2 bit
                   ,@G_AskDefault_comparator TINYINT
                   ,@G_AskDefault_v bit
                   ,@G_AskDefault_vals NVARCHAR(MAX)
                   ,@G_AskDefault_v1 bit
                   ,@G_AskDefault_v2 bit
                   ,@G_AskMinimum_comparator TINYINT
                   ,@G_AskMinimum_v bit
                   ,@G_AskMinimum_vals NVARCHAR(MAX)
                   ,@G_AskMinimum_v1 bit
                   ,@G_AskMinimum_v2 bit
                   ,@G_AskMaximum_comparator TINYINT
                   ,@G_AskMaximum_v bit
                   ,@G_AskMaximum_vals NVARCHAR(MAX)
                   ,@G_AskMaximum_v1 bit
                   ,@G_AskMaximum_v2 bit
                   ,@G_AskInWords_comparator TINYINT
                   ,@G_AskInWords_v bit
                   ,@G_AskInWords_vals NVARCHAR(MAX)
                   ,@G_AskInWords_v1 bit
                   ,@G_AskInWords_v2 bit

            SELECT @G_Id_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Id') IS NOT NULL AND JSON_QUERY(@Filter, '$.Id') IS NULL THEN 3 END
            )
                  ,@G_Id_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.value') AS tinyint),
                TRY_CAST(JSON_VALUE(@Filter, '$.Id') AS tinyint)
            )
                  ,@G_Id_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Id.value'),
                JSON_QUERY(@Filter, '$.Id')
            )
            SELECT @G_Id_v1 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[0]') AS tinyint)
                  ,@G_Id_v2 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[1]') AS tinyint)
            SELECT @G_Name_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Name.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Name') IS NOT NULL AND JSON_QUERY(@Filter, '$.Name') IS NULL THEN 3 END
            )
                  ,@G_Name_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Name.value') AS nvarchar(25)),
                TRY_CAST(JSON_VALUE(@Filter, '$.Name') AS nvarchar(25))
            )
                  ,@G_Name_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Name.value'),
                JSON_QUERY(@Filter, '$.Name')
            )
            SELECT @G_Name_v1 = TRY_CAST(JSON_VALUE(@G_Name_vals, '$[0]') AS nvarchar(25))
                  ,@G_Name_v2 = TRY_CAST(JSON_VALUE(@G_Name_vals, '$[1]') AS nvarchar(25))
            SELECT @G_AskEncrypted_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.AskEncrypted.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.AskEncrypted') IS NOT NULL AND JSON_QUERY(@Filter, '$.AskEncrypted') IS NULL THEN 3 END
            )
                  ,@G_AskEncrypted_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.AskEncrypted.value') AS bit),
                TRY_CAST(JSON_VALUE(@Filter, '$.AskEncrypted') AS bit)
            )
                  ,@G_AskEncrypted_vals = COALESCE(
                JSON_QUERY(@Filter, '$.AskEncrypted.value'),
                JSON_QUERY(@Filter, '$.AskEncrypted')
            )
            SELECT @G_AskEncrypted_v1 = TRY_CAST(JSON_VALUE(@G_AskEncrypted_vals, '$[0]') AS bit)
                  ,@G_AskEncrypted_v2 = TRY_CAST(JSON_VALUE(@G_AskEncrypted_vals, '$[1]') AS bit)
            SELECT @G_AskMask_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.AskMask.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.AskMask') IS NOT NULL AND JSON_QUERY(@Filter, '$.AskMask') IS NULL THEN 3 END
            )
                  ,@G_AskMask_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.AskMask.value') AS bit),
                TRY_CAST(JSON_VALUE(@Filter, '$.AskMask') AS bit)
            )
                  ,@G_AskMask_vals = COALESCE(
                JSON_QUERY(@Filter, '$.AskMask.value'),
                JSON_QUERY(@Filter, '$.AskMask')
            )
            SELECT @G_AskMask_v1 = TRY_CAST(JSON_VALUE(@G_AskMask_vals, '$[0]') AS bit)
                  ,@G_AskMask_v2 = TRY_CAST(JSON_VALUE(@G_AskMask_vals, '$[1]') AS bit)
            SELECT @G_AskListable_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.AskListable.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.AskListable') IS NOT NULL AND JSON_QUERY(@Filter, '$.AskListable') IS NULL THEN 3 END
            )
                  ,@G_AskListable_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.AskListable.value') AS bit),
                TRY_CAST(JSON_VALUE(@Filter, '$.AskListable') AS bit)
            )
                  ,@G_AskListable_vals = COALESCE(
                JSON_QUERY(@Filter, '$.AskListable.value'),
                JSON_QUERY(@Filter, '$.AskListable')
            )
            SELECT @G_AskListable_v1 = TRY_CAST(JSON_VALUE(@G_AskListable_vals, '$[0]') AS bit)
                  ,@G_AskListable_v2 = TRY_CAST(JSON_VALUE(@G_AskListable_vals, '$[1]') AS bit)
            SELECT @G_AskDefault_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.AskDefault.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.AskDefault') IS NOT NULL AND JSON_QUERY(@Filter, '$.AskDefault') IS NULL THEN 3 END
            )
                  ,@G_AskDefault_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.AskDefault.value') AS bit),
                TRY_CAST(JSON_VALUE(@Filter, '$.AskDefault') AS bit)
            )
                  ,@G_AskDefault_vals = COALESCE(
                JSON_QUERY(@Filter, '$.AskDefault.value'),
