                  ,@G_AskMinimum_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.AskMinimum.value') AS bit),
                TRY_CAST(JSON_VALUE(@Filter, '$.AskMinimum') AS bit)
            )
                  ,@G_AskMinimum_vals = COALESCE(
                JSON_QUERY(@Filter, '$.AskMinimum.value'),
