            )
            SELECT @G_AskMinimum_v1 = TRY_CAST(JSON_VALUE(@G_AskMinimum_vals, '$[0]') AS bit)
                  ,@G_AskMinimum_v2 = TRY_CAST(JSON_VALUE(@G_AskMinimum_vals, '$[1]') AS bit)
