            SELECT @G_AskLength_v1 = TRY_CAST(JSON_VALUE(@G_AskLength_vals, '$[0]') AS bit)
                  ,@G_AskLength_v2 = TRY_CAST(JSON_VALUE(@G_AskLength_vals, '$[1]') AS bit)
            SELECT @G_AskDecimals_comparator = COALESCE(
