               OR (@G_AskCodification_comparator = 12 AND @G_AskCodification_v1 IS NOT NULL AND @G_AskCodification_v2 IS NOT NULL)
               OR (@G_AskCodification_comparator = 13)
               OR (@G_AskCodification_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_AskCodification_comparator
        WHEN 1 THEN N'[T].[AskCodification] < @AskCodification'
        WHEN 2 THEN N'[T].[AskCodification] <= @AskCodification'
        WHEN 3 THEN N'[T].[AskCodification] = @AskCodification'
        WHEN 4 THEN N'[T].[AskCodification] <> @AskCodification'
        WHEN 5 THEN N'[T].[AskCodification] >= @AskCodification'
        WHEN 6 THEN N'[T].[AskCodification] > @AskCodification'
        WHEN 7 THEN N'[T].[AskCodification] IN (SELECT CAST([value] AS bit) FROM OPENJSON(@AskCodification_vals))'
        WHEN 8 THEN N'[T].[AskCodification] NOT IN (SELECT CAST([value] AS bit) FROM OPENJSON(@AskCodification_vals))'
        WHEN 9 THEN N'[T].[AskCodification] LIKE @AskCodification'
        WHEN 10 THEN N'[T].[AskCodification] NOT LIKE @AskCodification'
        WHEN 11 THEN N'[T].[AskCodification] BETWEEN @AskCodification_v1 AND @AskCodification_v2'
        WHEN 12 THEN N'[T].[AskCodification] NOT BETWEEN @AskCodification_v1 AND @AskCodification_v2'
        WHEN 13 THEN N'[T].[AskCodification] IS NULL'
        WHEN 14 THEN N'[T].[AskCodification] IS NOT NULL'
    END
