               ,@W_Minimum nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.Minimum') AS nvarchar(max))
               ,@W_Maximum nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.Maximum') AS nvarchar(max))
               ,@W_Codification nvarchar(5) = CAST(JSON_VALUE(@ActualRecord, '$.Codification') AS nvarchar(5))

        SET IDENTITY_INSERT [dbo].[Domains] ON
        INSERT INTO [dbo].[Domains] ([Id]
                                            ,[TypeId]
                                            ,[MaskId]
                                            ,[Name]
                                            ,[Length]
                                            ,[Decimals]
                                            ,[ValidValues]
                                            ,[Default]
                                            ,[Minimum]
                                            ,[Maximum]
                                            ,[Codification]
                                            ,[CreatedAt]
                                            ,[CreatedBy])
                                      VALUES (@W_Id
                                             ,@W_TypeId
                                             ,@W_MaskId
                                             ,@W_Name
                                             ,@W_Length
                                             ,@W_Decimals
                                             ,@W_ValidValues
                                             ,@W_Default
                                             ,@W_Minimum
                                             ,@W_Maximum
                                             ,@W_Codification
                                             ,GETDATE()
                                             ,@UserName)
        SET IDENTITY_INSERT [dbo].[Domains] OFF
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
