/**********************************************************************************
Criar stored procedure [dbo].[DomainsRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[DomainsRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[DomainsRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[DomainsRead](@Login NVARCHAR(MAX)
                                          ,@Filter NVARCHAR(MAX)
                                          ,@Search NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

        IF @Filter IS NULL
            SET @Filter = '{}'
        ELSE IF ISJSON(@Filter) = 0
            THROW 51000, 'Valor de @Filter não está no formato JSON', 1
        IF @Search IS NULL
            SET @Search = '{}'
        ELSE IF ISJSON(@Search) = 0
            THROW 51000, 'Valor de @Search não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Domains') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END
        IF @IsActionList = 1
            SET @OrderBy = '[T].[Name] ASC, [T].[Id] ASC'
        DECLARE @PickerValue nvarchar(25) = NULL

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @SessionId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.TypeId') AS tinyint) AS [TypeId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.MaskId') AS bigint) AS [MaskId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') AS nvarchar(25)) AS [Name]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Length') AS smallint) AS [Length]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Decimals') AS tinyint) AS [Decimals]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ValidValues') AS nvarchar(max)) AS [ValidValues]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Default') AS nvarchar(max)) AS [Default]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Minimum') AS nvarchar(max)) AS [Minimum]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Maximum') AS nvarchar(max)) AS [Maximum]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Codification') AS nvarchar(5)) AS [Codification]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Domains'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@Filter, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@ComparatorPredicate NVARCHAR(MAX)
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id bigint = CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)
               ,@WT_TypeId tinyint = CAST(JSON_VALUE(@Filter, '$.TypeId') AS tinyint)
               ,@WT_MaskId bigint = CAST(JSON_VALUE(@Filter, '$.MaskId') AS bigint)
