        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] bigint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[U].[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                              ,[T].[Id]
                                    FROM [dbo].[Menus] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [T].[Id] = [#].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                              ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @IsActionList = 1 BEGIN
            EXEC sp_executesql @sql
                               ,N'@PickerValue nvarchar(20),@T_Id bigint,@T_SystemId bigint,@T_Caption nvarchar(20)'
                               ,@PickerValue = @PickerValue
                               ,@T_Id = @WT_Id
                               ,@T_SystemId = @WT_SystemId
                               ,@T_Caption = @WT_Caption
        END ELSE IF @_ IS NULL BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_SystemId bigint,@T_Caption nvarchar(20),@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@SystemId bigint,@SystemId_v1 bigint,@SystemId_v2 bigint,@SystemId_vals NVARCHAR(MAX),@Caption nvarchar(20),@Caption_v1 nvarchar(20),@Caption_v2 nvarchar(20),@Caption_vals NVARCHAR(MAX)'
                               ,@T_Id = @WT_Id
                               ,@T_SystemId = @WT_SystemId
                               ,@T_Caption = @WT_Caption
                               ,@Id = @G_Id_v
                               ,@Id_v1 = @G_Id_v1
                               ,@Id_v2 = @G_Id_v2
                               ,@Id_vals = @G_Id_vals
                               ,@SystemId = @G_SystemId_v
                               ,@SystemId_v1 = @G_SystemId_v1
                               ,@SystemId_v2 = @G_SystemId_v2
                               ,@SystemId_vals = @G_SystemId_vals
                               ,@Caption = @G_Caption_v
                               ,@Caption_v1 = @G_Caption_v1
                               ,@Caption_v2 = @G_Caption_v2
                               ,@Caption_vals = @G_Caption_vals
        END ELSE BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_SystemId bigint,@T_Caption nvarchar(20)'
                               ,@T_Id = @WT_Id
                               ,@T_SystemId = @WT_SystemId
                               ,@T_Caption = @WT_Caption
        END

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

