    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'Users'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'update'
            THROW 51000, 'Ação da operação é inválida para Update', 1
        EXEC @TransactionIdAux = [dbo].[UserValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id bigint = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        DECLARE @W_Name nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(25))
               ,@W_Password nvarchar(256) = CAST(JSON_VALUE(@ActualRecord, '$.Password') AS nvarchar(256))
               ,@W_FullName nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.FullName') AS nvarchar(50))
               ,@W_RetryLogins tinyint = CAST(JSON_VALUE(@ActualRecord, '$.RetryLogins') AS tinyint)
               ,@W_IsActive bit = CAST(JSON_VALUE(@ActualRecord, '$.IsActive') AS bit)

        UPDATE [dbo].[Users] SET [Name] = @W_Name
                                          ,[Password] = @W_Password
                                          ,[FullName] = @W_FullName
                                          ,[RetryLogins] = @W_RetryLogins
                                          ,[IsActive] = @W_IsActive
                                          ,[UpdatedAt] = GETDATE()
                                          ,[UpdatedBy] = @UserName
            WHERE [Id] = @W_Id
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[UserDelete]
**********************************************************************************/
IF(SELECT object_id('[dbo].[UserDelete]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[UserDelete] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[UserDelete](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'Users'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'delete'
            THROW 51000, 'Ação da operação é inválida para Delete', 1
        EXEC @TransactionIdAux = [dbo].[UserValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id bigint = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

        DELETE FROM [dbo].[Users] WHERE [Id] = @W_Id

        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[UsersRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[UsersRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[UsersRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[UsersRead](@Login NVARCHAR(MAX)
                                          ,@Filter NVARCHAR(MAX)
                                          ,@Search NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

        IF @Filter IS NULL
            SET @Filter = '{}'
        ELSE IF ISJSON(@Filter) = 0
            THROW 51000, 'Valor de @Filter não está no formato JSON', 1
        IF @Search IS NULL
            SET @Search = '{}'
        ELSE IF ISJSON(@Search) = 0
            THROW 51000, 'Valor de @Search não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Users') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END
        IF @IsActionList = 1
            SET @OrderBy = '[T].[Name] ASC, [T].[Id] ASC'
        DECLARE @PickerValue nvarchar(25) = NULL

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @SessionId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') AS nvarchar(25)) AS [Name]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Password') AS nvarchar(256)) AS [Password]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.FullName') AS nvarchar(50)) AS [FullName]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.RetryLogins') AS tinyint) AS [RetryLogins]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsActive') AS bit) AS [IsActive]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Users'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@Filter, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@ComparatorPredicate NVARCHAR(MAX)
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id bigint = CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)
               ,@WT_Name nvarchar(25) = CAST(JSON_VALUE(@Filter, '$.Name') AS nvarchar(25))
               ,@WT_FullName nvarchar(50) = CAST(JSON_VALUE(@Filter, '$.FullName') AS nvarchar(50))
               ,@WT_IsActive bit = CAST(JSON_VALUE(@Filter, '$.IsActive') AS bit)

        IF @WT_Id IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Id] = @T_Id'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'Name' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Name] IS NULL'
        ELSE IF @WT_Name IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Name] = @T_Name'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'FullName' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[FullName] IS NULL'
        ELSE IF @WT_FullName IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[FullName] = @T_FullName'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'IsActive' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[IsActive] IS NULL'
        ELSE IF @WT_IsActive IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[IsActive] = @T_IsActive'
        END
        IF @IsActionList = 1 BEGIN
            SET @PickerValue = CAST(JSON_VALUE(@Filter, '$.Picker.Value') AS nvarchar(25))
            IF @PickerValue IS NULL
                SET @PickerValue = ''
            SET @Where = @Where + ' AND [T].[Name] LIKE ''%'' + @PickerValue + ''%'''
        END ELSE IF @_ IS NULL BEGIN
            DECLARE @G_Id_comparator TINYINT
                   ,@G_Id_v bigint
                   ,@G_Id_vals NVARCHAR(MAX)
                   ,@G_Id_v1 bigint
                   ,@G_Id_v2 bigint
                   ,@G_Name_comparator TINYINT
                   ,@G_Name_v nvarchar(25)
                   ,@G_Name_vals NVARCHAR(MAX)
                   ,@G_Name_v1 nvarchar(25)
                   ,@G_Name_v2 nvarchar(25)
                   ,@G_FullName_comparator TINYINT
                   ,@G_FullName_v nvarchar(50)
                   ,@G_FullName_vals NVARCHAR(MAX)
                   ,@G_FullName_v1 nvarchar(50)
                   ,@G_FullName_v2 nvarchar(50)
                   ,@G_IsActive_comparator TINYINT
                   ,@G_IsActive_v bit
                   ,@G_IsActive_vals NVARCHAR(MAX)
                   ,@G_IsActive_v1 bit
                   ,@G_IsActive_v2 bit

            SELECT @G_Id_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Id') IS NOT NULL AND JSON_QUERY(@Filter, '$.Id') IS NULL THEN 3 END
            )
                  ,@G_Id_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.value') AS bigint),
                TRY_CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)
            )
                  ,@G_Id_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Id.value'),
                JSON_QUERY(@Filter, '$.Id')
            )
            SELECT @G_Id_v1 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[0]') AS bigint)
                  ,@G_Id_v2 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[1]') AS bigint)
            SELECT @G_Name_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Name.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Name') IS NOT NULL AND JSON_QUERY(@Filter, '$.Name') IS NULL THEN 3 END
            )
                  ,@G_Name_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Name.value') AS nvarchar(25)),
                TRY_CAST(JSON_VALUE(@Filter, '$.Name') AS nvarchar(25))
            )
                  ,@G_Name_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Name.value'),
                JSON_QUERY(@Filter, '$.Name')
            )
            SELECT @G_Name_v1 = TRY_CAST(JSON_VALUE(@G_Name_vals, '$[0]') AS nvarchar(25))
                  ,@G_Name_v2 = TRY_CAST(JSON_VALUE(@G_Name_vals, '$[1]') AS nvarchar(25))
            SELECT @G_FullName_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.FullName.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.FullName') IS NOT NULL AND JSON_QUERY(@Filter, '$.FullName') IS NULL THEN 3 END
            )
                  ,@G_FullName_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.FullName.value') AS nvarchar(50)),
                TRY_CAST(JSON_VALUE(@Filter, '$.FullName') AS nvarchar(50))
            )
                  ,@G_FullName_vals = COALESCE(
                JSON_QUERY(@Filter, '$.FullName.value'),
                JSON_QUERY(@Filter, '$.FullName')
            )
            SELECT @G_FullName_v1 = TRY_CAST(JSON_VALUE(@G_FullName_vals, '$[0]') AS nvarchar(50))
                  ,@G_FullName_v2 = TRY_CAST(JSON_VALUE(@G_FullName_vals, '$[1]') AS nvarchar(50))
            SELECT @G_IsActive_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.IsActive.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.IsActive') IS NOT NULL AND JSON_QUERY(@Filter, '$.IsActive') IS NULL THEN 3 END
            )
                  ,@G_IsActive_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.IsActive.value') AS bit),
                TRY_CAST(JSON_VALUE(@Filter, '$.IsActive') AS bit)
            )
                  ,@G_IsActive_vals = COALESCE(
                JSON_QUERY(@Filter, '$.IsActive.value'),
                JSON_QUERY(@Filter, '$.IsActive')
            )
            SELECT @G_IsActive_v1 = TRY_CAST(JSON_VALUE(@G_IsActive_vals, '$[0]') AS bit)
                  ,@G_IsActive_v2 = TRY_CAST(JSON_VALUE(@G_IsActive_vals, '$[1]') AS bit)

            IF @G_Id_comparator IS NOT NULL BEGIN
                IF (@G_Id_comparator = 1 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 2 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 3 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 4 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 5 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 6 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 7 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 8 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 9 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 10 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 11 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 12 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 13)
               OR (@G_Id_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_Id_comparator
        WHEN 1 THEN N'[T].[Id] < @Id'
        WHEN 2 THEN N'[T].[Id] <= @Id'
        WHEN 3 THEN N'[T].[Id] = @Id'
        WHEN 4 THEN N'[T].[Id] <> @Id'
        WHEN 5 THEN N'[T].[Id] >= @Id'
        WHEN 6 THEN N'[T].[Id] > @Id'
        WHEN 7 THEN N'[T].[Id] IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 8 THEN N'[T].[Id] NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 9 THEN N'[T].[Id] LIKE @Id'
        WHEN 10 THEN N'[T].[Id] NOT LIKE @Id'
        WHEN 11 THEN N'[T].[Id] BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'[T].[Id] NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'[T].[Id] IS NULL'
        WHEN 14 THEN N'[T].[Id] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'Name' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[Name] IS NULL'
            ELSE
            IF @G_Name_comparator IS NOT NULL BEGIN
                IF (@G_Name_comparator = 1 AND @G_Name_v IS NOT NULL)
               OR (@G_Name_comparator = 2 AND @G_Name_v IS NOT NULL)
               OR (@G_Name_comparator = 3 AND @G_Name_v IS NOT NULL)
               OR (@G_Name_comparator = 4 AND @G_Name_v IS NOT NULL)
               OR (@G_Name_comparator = 5 AND @G_Name_v IS NOT NULL)
               OR (@G_Name_comparator = 6 AND @G_Name_v IS NOT NULL)
               OR (@G_Name_comparator = 7 AND @G_Name_vals IS NOT NULL)
               OR (@G_Name_comparator = 8 AND @G_Name_vals IS NOT NULL)
               OR (@G_Name_comparator = 9 AND @G_Name_v IS NOT NULL)
               OR (@G_Name_comparator = 10 AND @G_Name_v IS NOT NULL)
               OR (@G_Name_comparator = 11 AND @G_Name_v1 IS NOT NULL AND @G_Name_v2 IS NOT NULL)
               OR (@G_Name_comparator = 12 AND @G_Name_v1 IS NOT NULL AND @G_Name_v2 IS NOT NULL)
               OR (@G_Name_comparator = 13)
               OR (@G_Name_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_Name_comparator
        WHEN 1 THEN N'[T].[Name] < @Name'
        WHEN 2 THEN N'[T].[Name] <= @Name'
        WHEN 3 THEN N'[T].[Name] = @Name'
        WHEN 4 THEN N'[T].[Name] <> @Name'
        WHEN 5 THEN N'[T].[Name] >= @Name'
        WHEN 6 THEN N'[T].[Name] > @Name'
        WHEN 7 THEN N'[T].[Name] IN (SELECT CAST([value] AS nvarchar(25)) FROM OPENJSON(@Name_vals))'
        WHEN 8 THEN N'[T].[Name] NOT IN (SELECT CAST([value] AS nvarchar(25)) FROM OPENJSON(@Name_vals))'
        WHEN 9 THEN N'[T].[Name] LIKE @Name'
        WHEN 10 THEN N'[T].[Name] NOT LIKE @Name'
        WHEN 11 THEN N'[T].[Name] BETWEEN @Name_v1 AND @Name_v2'
        WHEN 12 THEN N'[T].[Name] NOT BETWEEN @Name_v1 AND @Name_v2'
        WHEN 13 THEN N'[T].[Name] IS NULL'
        WHEN 14 THEN N'[T].[Name] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'FullName' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[FullName] IS NULL'
            ELSE
            IF @G_FullName_comparator IS NOT NULL BEGIN
                IF (@G_FullName_comparator = 1 AND @G_FullName_v IS NOT NULL)
               OR (@G_FullName_comparator = 2 AND @G_FullName_v IS NOT NULL)
               OR (@G_FullName_comparator = 3 AND @G_FullName_v IS NOT NULL)
               OR (@G_FullName_comparator = 4 AND @G_FullName_v IS NOT NULL)
               OR (@G_FullName_comparator = 5 AND @G_FullName_v IS NOT NULL)
               OR (@G_FullName_comparator = 6 AND @G_FullName_v IS NOT NULL)
               OR (@G_FullName_comparator = 7 AND @G_FullName_vals IS NOT NULL)
               OR (@G_FullName_comparator = 8 AND @G_FullName_vals IS NOT NULL)
               OR (@G_FullName_comparator = 9 AND @G_FullName_v IS NOT NULL)
               OR (@G_FullName_comparator = 10 AND @G_FullName_v IS NOT NULL)
               OR (@G_FullName_comparator = 11 AND @G_FullName_v1 IS NOT NULL AND @G_FullName_v2 IS NOT NULL)
               OR (@G_FullName_comparator = 12 AND @G_FullName_v1 IS NOT NULL AND @G_FullName_v2 IS NOT NULL)
               OR (@G_FullName_comparator = 13)
               OR (@G_FullName_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_FullName_comparator
        WHEN 1 THEN N'[T].[FullName] < @FullName'
        WHEN 2 THEN N'[T].[FullName] <= @FullName'
        WHEN 3 THEN N'[T].[FullName] = @FullName'
        WHEN 4 THEN N'[T].[FullName] <> @FullName'
        WHEN 5 THEN N'[T].[FullName] >= @FullName'
        WHEN 6 THEN N'[T].[FullName] > @FullName'
        WHEN 7 THEN N'[T].[FullName] IN (SELECT CAST([value] AS nvarchar(50)) FROM OPENJSON(@FullName_vals))'
        WHEN 8 THEN N'[T].[FullName] NOT IN (SELECT CAST([value] AS nvarchar(50)) FROM OPENJSON(@FullName_vals))'
        WHEN 9 THEN N'[T].[FullName] LIKE @FullName'
        WHEN 10 THEN N'[T].[FullName] NOT LIKE @FullName'
        WHEN 11 THEN N'[T].[FullName] BETWEEN @FullName_v1 AND @FullName_v2'
        WHEN 12 THEN N'[T].[FullName] NOT BETWEEN @FullName_v1 AND @FullName_v2'
        WHEN 13 THEN N'[T].[FullName] IS NULL'
        WHEN 14 THEN N'[T].[FullName] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'IsActive' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[IsActive] IS NULL'
            ELSE
            IF @G_IsActive_comparator IS NOT NULL BEGIN
                IF (@G_IsActive_comparator = 1 AND @G_IsActive_v IS NOT NULL)
               OR (@G_IsActive_comparator = 2 AND @G_IsActive_v IS NOT NULL)
               OR (@G_IsActive_comparator = 3 AND @G_IsActive_v IS NOT NULL)
               OR (@G_IsActive_comparator = 4 AND @G_IsActive_v IS NOT NULL)
               OR (@G_IsActive_comparator = 5 AND @G_IsActive_v IS NOT NULL)
               OR (@G_IsActive_comparator = 6 AND @G_IsActive_v IS NOT NULL)
               OR (@G_IsActive_comparator = 7 AND @G_IsActive_vals IS NOT NULL)
               OR (@G_IsActive_comparator = 8 AND @G_IsActive_vals IS NOT NULL)
               OR (@G_IsActive_comparator = 9 AND @G_IsActive_v IS NOT NULL)
               OR (@G_IsActive_comparator = 10 AND @G_IsActive_v IS NOT NULL)
               OR (@G_IsActive_comparator = 11 AND @G_IsActive_v1 IS NOT NULL AND @G_IsActive_v2 IS NOT NULL)
               OR (@G_IsActive_comparator = 12 AND @G_IsActive_v1 IS NOT NULL AND @G_IsActive_v2 IS NOT NULL)
               OR (@G_IsActive_comparator = 13)
               OR (@G_IsActive_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_IsActive_comparator
        WHEN 1 THEN N'[T].[IsActive] < @IsActive'
        WHEN 2 THEN N'[T].[IsActive] <= @IsActive'
        WHEN 3 THEN N'[T].[IsActive] = @IsActive'
        WHEN 4 THEN N'[T].[IsActive] <> @IsActive'
        WHEN 5 THEN N'[T].[IsActive] >= @IsActive'
        WHEN 6 THEN N'[T].[IsActive] > @IsActive'
        WHEN 7 THEN N'[T].[IsActive] IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsActive_vals))'
        WHEN 8 THEN N'[T].[IsActive] NOT IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsActive_vals))'
        WHEN 9 THEN N'[T].[IsActive] LIKE @IsActive'
        WHEN 10 THEN N'[T].[IsActive] NOT LIKE @IsActive'
        WHEN 11 THEN N'[T].[IsActive] BETWEEN @IsActive_v1 AND @IsActive_v2'
        WHEN 12 THEN N'[T].[IsActive] NOT BETWEEN @IsActive_v1 AND @IsActive_v2'
        WHEN 13 THEN N'[T].[IsActive] IS NULL'
        WHEN 14 THEN N'[T].[IsActive] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
        END ELSE
            SET @Where = @Where + ' AND [T].[Id] IN (' + @_ + ')'

        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] bigint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[U].[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                              ,[T].[Id]
                                    FROM [dbo].[Users] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [T].[Id] = [#].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                              ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @IsActionList = 1 BEGIN
            EXEC sp_executesql @sql
                               ,N'@PickerValue nvarchar(25),@T_Id bigint,@T_Name nvarchar(25),@T_FullName nvarchar(50),@T_IsActive bit'
                               ,@PickerValue = @PickerValue
                               ,@T_Id = @WT_Id
                               ,@T_Name = @WT_Name
                               ,@T_FullName = @WT_FullName
                               ,@T_IsActive = @WT_IsActive
        END ELSE IF @_ IS NULL BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_Name nvarchar(25),@T_FullName nvarchar(50),@T_IsActive bit,@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@Name nvarchar(25),@Name_v1 nvarchar(25),@Name_v2 nvarchar(25),@Name_vals NVARCHAR(MAX),@FullName nvarchar(50),@FullName_v1 nvarchar(50),@FullName_v2 nvarchar(50),@FullName_vals NVARCHAR(MAX),@IsActive bit,@IsActive_v1 bit,@IsActive_v2 bit,@IsActive_vals NVARCHAR(MAX)'
                               ,@T_Id = @WT_Id
                               ,@T_Name = @WT_Name
                               ,@T_FullName = @WT_FullName
                               ,@T_IsActive = @WT_IsActive
                               ,@Id = @G_Id_v
                               ,@Id_v1 = @G_Id_v1
                               ,@Id_v2 = @G_Id_v2
                               ,@Id_vals = @G_Id_vals
                               ,@Name = @G_Name_v
                               ,@Name_v1 = @G_Name_v1
                               ,@Name_v2 = @G_Name_v2
                               ,@Name_vals = @G_Name_vals
                               ,@FullName = @G_FullName_v
                               ,@FullName_v1 = @G_FullName_v1
                               ,@FullName_v2 = @G_FullName_v2
                               ,@FullName_vals = @G_FullName_vals
                               ,@IsActive = @G_IsActive_v
                               ,@IsActive_v1 = @G_IsActive_v1
                               ,@IsActive_v2 = @G_IsActive_v2
                               ,@IsActive_vals = @G_IsActive_vals
        END ELSE BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_Name nvarchar(25),@T_FullName nvarchar(50),@T_IsActive bit'
                               ,@T_Id = @WT_Id
                               ,@T_Name = @WT_Name
                               ,@T_FullName = @WT_FullName
                               ,@T_IsActive = @WT_IsActive
        END

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            DECLARE @SearchRecno BIGINT = NULL
            IF EXISTS(SELECT 1 FROM OPENJSON(@Search)) BEGIN
                DECLARE @Recno BIGINT
                   ,@S_Id_comparator TINYINT
                   ,@S_Id_v bigint
                   ,@S_Id_vals NVARCHAR(MAX)
                   ,@S_Id_v1 bigint
                   ,@S_Id_v2 bigint
                   ,@S_Name_comparator TINYINT
                   ,@S_Name_v nvarchar(25)
                   ,@S_Name_vals NVARCHAR(MAX)
                   ,@S_Name_v1 nvarchar(25)
                   ,@S_Name_v2 nvarchar(25)
                   ,@S_FullName_comparator TINYINT
                   ,@S_FullName_v nvarchar(50)
                   ,@S_FullName_vals NVARCHAR(MAX)
                   ,@S_FullName_v1 nvarchar(50)
                   ,@S_FullName_v2 nvarchar(50)
                   ,@S_IsActive_comparator TINYINT
                   ,@S_IsActive_v bit
                   ,@S_IsActive_vals NVARCHAR(MAX)
                   ,@S_IsActive_v1 bit
                   ,@S_IsActive_v2 bit

                SELECT @S_Id_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Id.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.Id') IS NOT NULL AND JSON_QUERY(@Search, '$.Id') IS NULL THEN 3 END
                )
                      ,@S_Id_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Id.value') AS bigint),
                    TRY_CAST(JSON_VALUE(@Search, '$.Id') AS bigint)
                )
                      ,@S_Id_vals = COALESCE(
                    JSON_QUERY(@Search, '$.Id.value'),
                    JSON_QUERY(@Search, '$.Id')
                )
                SELECT @S_Id_v1 = TRY_CAST(JSON_VALUE(@S_Id_vals, '$[0]') AS bigint)
                      ,@S_Id_v2 = TRY_CAST(JSON_VALUE(@S_Id_vals, '$[1]') AS bigint)
                SELECT @S_Name_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Name.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.Name') IS NOT NULL AND JSON_QUERY(@Search, '$.Name') IS NULL THEN 9 END
                )
                      ,@S_Name_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Name.value') AS nvarchar(25)),
                    TRY_CAST(JSON_VALUE(@Search, '$.Name') AS nvarchar(25))
                )
                      ,@S_Name_vals = COALESCE(
                    JSON_QUERY(@Search, '$.Name.value'),
                    JSON_QUERY(@Search, '$.Name')
                )
                SELECT @S_Name_v1 = TRY_CAST(JSON_VALUE(@S_Name_vals, '$[0]') AS nvarchar(25))
                      ,@S_Name_v2 = TRY_CAST(JSON_VALUE(@S_Name_vals, '$[1]') AS nvarchar(25))
                SELECT @S_FullName_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.FullName.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.FullName') IS NOT NULL AND JSON_QUERY(@Search, '$.FullName') IS NULL THEN 9 END
                )
                      ,@S_FullName_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.FullName.value') AS nvarchar(50)),
                    TRY_CAST(JSON_VALUE(@Search, '$.FullName') AS nvarchar(50))
                )
                      ,@S_FullName_vals = COALESCE(
                    JSON_QUERY(@Search, '$.FullName.value'),
                    JSON_QUERY(@Search, '$.FullName')
                )
                SELECT @S_FullName_v1 = TRY_CAST(JSON_VALUE(@S_FullName_vals, '$[0]') AS nvarchar(50))
                      ,@S_FullName_v2 = TRY_CAST(JSON_VALUE(@S_FullName_vals, '$[1]') AS nvarchar(50))
                SELECT @S_IsActive_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.IsActive.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.IsActive') IS NOT NULL AND JSON_QUERY(@Search, '$.IsActive') IS NULL THEN 3 END
                )
                      ,@S_IsActive_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.IsActive.value') AS bit),
                    TRY_CAST(JSON_VALUE(@Search, '$.IsActive') AS bit)
                )
                      ,@S_IsActive_vals = COALESCE(
                    JSON_QUERY(@Search, '$.IsActive.value'),
                    JSON_QUERY(@Search, '$.IsActive')
                )
                SELECT @S_IsActive_v1 = TRY_CAST(JSON_VALUE(@S_IsActive_vals, '$[0]') AS bit)
                      ,@S_IsActive_v2 = TRY_CAST(JSON_VALUE(@S_IsActive_vals, '$[1]') AS bit)

                SET @Where = ''
                IF @S_Id_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_Id_comparator = 1 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 2 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 3 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 4 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 5 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 6 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 7 AND @S_Id_vals IS NOT NULL)
               OR (@S_Id_comparator = 8 AND @S_Id_vals IS NOT NULL)
               OR (@S_Id_comparator = 9 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 10 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 11 AND @S_Id_v1 IS NOT NULL AND @S_Id_v2 IS NOT NULL)
               OR (@S_Id_comparator = 12 AND @S_Id_v1 IS NOT NULL AND @S_Id_v2 IS NOT NULL)
               OR (@S_Id_comparator = 13)
               OR (@S_Id_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_Id_comparator
        WHEN 1 THEN N'COALESCE([D].[Id], [O].[Id]) < @Id'
        WHEN 2 THEN N'COALESCE([D].[Id], [O].[Id]) <= @Id'
        WHEN 3 THEN N'COALESCE([D].[Id], [O].[Id]) = @Id'
        WHEN 4 THEN N'COALESCE([D].[Id], [O].[Id]) <> @Id'
        WHEN 5 THEN N'COALESCE([D].[Id], [O].[Id]) >= @Id'
        WHEN 6 THEN N'COALESCE([D].[Id], [O].[Id]) > @Id'
        WHEN 7 THEN N'COALESCE([D].[Id], [O].[Id]) IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 8 THEN N'COALESCE([D].[Id], [O].[Id]) NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 9 THEN N'COALESCE([D].[Id], [O].[Id]) LIKE @Id'
        WHEN 10 THEN N'COALESCE([D].[Id], [O].[Id]) NOT LIKE @Id'
        WHEN 11 THEN N'COALESCE([D].[Id], [O].[Id]) BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'COALESCE([D].[Id], [O].[Id]) NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'COALESCE([D].[Id], [O].[Id]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[Id], [O].[Id]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'Name' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[Name], [O].[Name]) IS NULL'
                END ELSE
                IF @S_Name_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_Name_comparator = 1 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 2 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 3 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 4 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 5 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 6 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 7 AND @S_Name_vals IS NOT NULL)
               OR (@S_Name_comparator = 8 AND @S_Name_vals IS NOT NULL)
               OR (@S_Name_comparator = 9 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 10 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 11 AND @S_Name_v1 IS NOT NULL AND @S_Name_v2 IS NOT NULL)
               OR (@S_Name_comparator = 12 AND @S_Name_v1 IS NOT NULL AND @S_Name_v2 IS NOT NULL)
               OR (@S_Name_comparator = 13)
               OR (@S_Name_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_Name_comparator
        WHEN 1 THEN N'COALESCE([D].[Name], [O].[Name]) < @Name'
        WHEN 2 THEN N'COALESCE([D].[Name], [O].[Name]) <= @Name'
        WHEN 3 THEN N'COALESCE([D].[Name], [O].[Name]) = @Name'
        WHEN 4 THEN N'COALESCE([D].[Name], [O].[Name]) <> @Name'
        WHEN 5 THEN N'COALESCE([D].[Name], [O].[Name]) >= @Name'
        WHEN 6 THEN N'COALESCE([D].[Name], [O].[Name]) > @Name'
        WHEN 7 THEN N'COALESCE([D].[Name], [O].[Name]) IN (SELECT CAST([value] AS nvarchar(25)) FROM OPENJSON(@Name_vals))'
        WHEN 8 THEN N'COALESCE([D].[Name], [O].[Name]) NOT IN (SELECT CAST([value] AS nvarchar(25)) FROM OPENJSON(@Name_vals))'
        WHEN 9 THEN N'COALESCE([D].[Name], [O].[Name]) LIKE @Name'
        WHEN 10 THEN N'COALESCE([D].[Name], [O].[Name]) NOT LIKE @Name'
        WHEN 11 THEN N'COALESCE([D].[Name], [O].[Name]) BETWEEN @Name_v1 AND @Name_v2'
        WHEN 12 THEN N'COALESCE([D].[Name], [O].[Name]) NOT BETWEEN @Name_v1 AND @Name_v2'
        WHEN 13 THEN N'COALESCE([D].[Name], [O].[Name]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[Name], [O].[Name]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'FullName' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[FullName], [O].[FullName]) IS NULL'
                END ELSE
                IF @S_FullName_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_FullName_comparator = 1 AND @S_FullName_v IS NOT NULL)
               OR (@S_FullName_comparator = 2 AND @S_FullName_v IS NOT NULL)
               OR (@S_FullName_comparator = 3 AND @S_FullName_v IS NOT NULL)
               OR (@S_FullName_comparator = 4 AND @S_FullName_v IS NOT NULL)
               OR (@S_FullName_comparator = 5 AND @S_FullName_v IS NOT NULL)
               OR (@S_FullName_comparator = 6 AND @S_FullName_v IS NOT NULL)
               OR (@S_FullName_comparator = 7 AND @S_FullName_vals IS NOT NULL)
               OR (@S_FullName_comparator = 8 AND @S_FullName_vals IS NOT NULL)
               OR (@S_FullName_comparator = 9 AND @S_FullName_v IS NOT NULL)
               OR (@S_FullName_comparator = 10 AND @S_FullName_v IS NOT NULL)
               OR (@S_FullName_comparator = 11 AND @S_FullName_v1 IS NOT NULL AND @S_FullName_v2 IS NOT NULL)
               OR (@S_FullName_comparator = 12 AND @S_FullName_v1 IS NOT NULL AND @S_FullName_v2 IS NOT NULL)
               OR (@S_FullName_comparator = 13)
               OR (@S_FullName_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_FullName_comparator
        WHEN 1 THEN N'COALESCE([D].[FullName], [O].[FullName]) < @FullName'
        WHEN 2 THEN N'COALESCE([D].[FullName], [O].[FullName]) <= @FullName'
        WHEN 3 THEN N'COALESCE([D].[FullName], [O].[FullName]) = @FullName'
        WHEN 4 THEN N'COALESCE([D].[FullName], [O].[FullName]) <> @FullName'
        WHEN 5 THEN N'COALESCE([D].[FullName], [O].[FullName]) >= @FullName'
        WHEN 6 THEN N'COALESCE([D].[FullName], [O].[FullName]) > @FullName'
        WHEN 7 THEN N'COALESCE([D].[FullName], [O].[FullName]) IN (SELECT CAST([value] AS nvarchar(50)) FROM OPENJSON(@FullName_vals))'
        WHEN 8 THEN N'COALESCE([D].[FullName], [O].[FullName]) NOT IN (SELECT CAST([value] AS nvarchar(50)) FROM OPENJSON(@FullName_vals))'
        WHEN 9 THEN N'COALESCE([D].[FullName], [O].[FullName]) LIKE @FullName'
        WHEN 10 THEN N'COALESCE([D].[FullName], [O].[FullName]) NOT LIKE @FullName'
        WHEN 11 THEN N'COALESCE([D].[FullName], [O].[FullName]) BETWEEN @FullName_v1 AND @FullName_v2'
        WHEN 12 THEN N'COALESCE([D].[FullName], [O].[FullName]) NOT BETWEEN @FullName_v1 AND @FullName_v2'
        WHEN 13 THEN N'COALESCE([D].[FullName], [O].[FullName]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[FullName], [O].[FullName]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'IsActive' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[IsActive], [O].[IsActive]) IS NULL'
                END ELSE
                IF @S_IsActive_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_IsActive_comparator = 1 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 2 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 3 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 4 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 5 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 6 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 7 AND @S_IsActive_vals IS NOT NULL)
               OR (@S_IsActive_comparator = 8 AND @S_IsActive_vals IS NOT NULL)
               OR (@S_IsActive_comparator = 9 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 10 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 11 AND @S_IsActive_v1 IS NOT NULL AND @S_IsActive_v2 IS NOT NULL)
               OR (@S_IsActive_comparator = 12 AND @S_IsActive_v1 IS NOT NULL AND @S_IsActive_v2 IS NOT NULL)
               OR (@S_IsActive_comparator = 13)
               OR (@S_IsActive_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_IsActive_comparator
        WHEN 1 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) < @IsActive'
        WHEN 2 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) <= @IsActive'
        WHEN 3 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) = @IsActive'
        WHEN 4 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) <> @IsActive'
        WHEN 5 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) >= @IsActive'
        WHEN 6 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) > @IsActive'
        WHEN 7 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsActive_vals))'
        WHEN 8 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) NOT IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsActive_vals))'
        WHEN 9 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) LIKE @IsActive'
        WHEN 10 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) NOT LIKE @IsActive'
        WHEN 11 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) BETWEEN @IsActive_v1 AND @IsActive_v2'
        WHEN 12 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) NOT BETWEEN @IsActive_v1 AND @IsActive_v2'
        WHEN 13 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[Users] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@Name nvarchar(25),@Name_v1 nvarchar(25),@Name_v2 nvarchar(25),@Name_vals NVARCHAR(MAX),@FullName nvarchar(50),@FullName_v1 nvarchar(50),@FullName_v2 nvarchar(50),@FullName_vals NVARCHAR(MAX),@IsActive bit,@IsActive_v1 bit,@IsActive_v2 bit,@IsActive_vals NVARCHAR(MAX), @r BIGINT OUTPUT'
                                       ,@Id = @S_Id_v
                                       ,@Id_v1 = @S_Id_v1
                                       ,@Id_v2 = @S_Id_v2
                                       ,@Id_vals = @S_Id_vals
                                       ,@Name = @S_Name_v
                                       ,@Name_v1 = @S_Name_v1
                                       ,@Name_v2 = @S_Name_v2
                                       ,@Name_vals = @S_Name_vals
                                       ,@FullName = @S_FullName_v
                                       ,@FullName_v1 = @S_FullName_v1
                                       ,@FullName_v2 = @S_FullName_v2
                                       ,@FullName_vals = @S_FullName_vals
                                       ,@IsActive = @S_IsActive_v
                                       ,@IsActive_v1 = @S_IsActive_v1
                                       ,@IsActive_v2 = @S_IsActive_v2
                                       ,@IsActive_vals = @S_IsActive_vals
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS nvarchar(25)) AS [Name]
                    ,CAST(NULL AS nvarchar(256)) AS [Password]
                    ,CAST(NULL AS nvarchar(50)) AS [FullName]
                    ,CAST(NULL AS tinyint) AS [RetryLogins]
                    ,CAST(NULL AS bit) AS [IsActive]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''User'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[Name]
                              ,[T].[Password]
                              ,[T].[FullName]
                              ,[T].[RetryLogins]
                              ,[T].[IsActive]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Users] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''User'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[Name]
                                  ,[O].[Password]
                                  ,[O].[FullName]
                                  ,[O].[RetryLogins]
                                  ,[O].[IsActive]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[Name]
                      ,[Name] AS [ListItemValue]
                      ,[Password]
                      ,[FullName]
                      ,[RetryLogins]
                      ,[IsActive]
                    FROM [#result] FOR JSON PATH) AS [result]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[SystemUserValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemUserValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemUserValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SystemUserValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id bigint

        IF @Action = 'delete' BEGIN
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

        END ELSE BEGIN
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        END
        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS bigint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[SystemsUsers] WHERE [Id] = @W_Id) AND @Action = 'create'
            THROW 51000, 'Chave-primária já existe em SystemsUsers', 1
        ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'SystemsUsers'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND                                           CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create' AND NOT EXISTS(SELECT 1 FROM [dbo].[SystemsUsers] WHERE [Id] = @W_Id)
            THROW 51000, 'Chave-primária não existe em SystemsUsers', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[SystemsUsers]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [SystemId] = JSON_VALUE(@LastRecord, '$.SystemId')
                                  AND [UserId] = JSON_VALUE(@LastRecord, '$.UserId')
                                  AND [Name] = JSON_VALUE(@LastRecord, '$.Name'))
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'SystemsUsers'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.SystemId') = JSON_VALUE(@LastRecord, '$.SystemId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.UserId') = JSON_VALUE(@LastRecord, '$.UserId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') = JSON_VALUE(@LastRecord, '$.Name'))
                THROW 51000, 'Registro de SystemsUsers alterado por outro usuário', 1
        END

        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_SystemId bigint = CAST(JSON_VALUE(@ActualRecord, '$.SystemId') AS bigint)
                   ,@W_UserId bigint = CAST(JSON_VALUE(@ActualRecord, '$.UserId') AS bigint)
                   ,@W_Name nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(50))

            IF @W_SystemId IS NULL
                THROW 51000, 'Valor de SystemId em @ActualRecord é requerido.', 1
            IF @W_SystemId < CAST('1' AS bigint)
                THROW 51000, 'Valor de SystemId em @ActualRecord deve ser maior que ou igual a 1', 1
            IF @W_UserId IS NULL
                THROW 51000, 'Valor de UserId em @ActualRecord é requerido.', 1
            IF @W_UserId < CAST('1' AS bigint)
                THROW 51000, 'Valor de UserId em @ActualRecord deve ser maior que ou igual a 1', 1
            IF @W_Name IS NULL
                THROW 51000, 'Valor de Name em @ActualRecord é requerido.', 1
            IF (@W_SystemId IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM [dbo].[Systems] WHERE [Id] = @W_SystemId)
                THROW 51000, 'Valor de FK em @ActualRecord inexiste em Systems', 1
            IF (@W_UserId IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM [dbo].[Users] WHERE [Id] = @W_UserId)
                THROW 51000, 'Valor de FK em @ActualRecord inexiste em Users', 1
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[SystemUserPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemUserPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemUserPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SystemUserPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
               ,@W_Id bigint

    IF @Action = 'delete' BEGIN
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

    END ELSE BEGIN
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    END
    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'SystemsUsers'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'SystemsUsers', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[SystemUserValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'SystemsUsers'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            SET IDENTITY_INSERT [dbo].[Operations] ON
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'SystemsUsers'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
            SET IDENTITY_INSERT [dbo].[Operations] OFF
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create'
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[SystemUserValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @ActionAux = 'create'
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[SystemUserCreate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemUserCreate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemUserCreate] AS PRINT 1')
