        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] bigint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[U].[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                              ,[T].[Id]
                                    FROM [dbo].[SystemsUsers] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [T].[Id] = [#].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                              ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @IsActionList = 1 BEGIN
            EXEC sp_executesql @sql
                               ,N'@PickerValue nvarchar(50),@T_Id bigint,@T_SystemId bigint,@T_UserId bigint,@T_Name nvarchar(50)'
                               ,@PickerValue = @PickerValue
                               ,@T_Id = @WT_Id
                               ,@T_SystemId = @WT_SystemId
                               ,@T_UserId = @WT_UserId
                               ,@T_Name = @WT_Name
        END ELSE IF @_ IS NULL BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_SystemId bigint,@T_UserId bigint,@T_Name nvarchar(50),@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@SystemId bigint,@SystemId_v1 bigint,@SystemId_v2 bigint,@SystemId_vals NVARCHAR(MAX),@UserId bigint,@UserId_v1 bigint,@UserId_v2 bigint,@UserId_vals NVARCHAR(MAX),@Name nvarchar(50),@Name_v1 nvarchar(50),@Name_v2 nvarchar(50),@Name_vals NVARCHAR(MAX)'
                               ,@T_Id = @WT_Id
                               ,@T_SystemId = @WT_SystemId
                               ,@T_UserId = @WT_UserId
                               ,@T_Name = @WT_Name
                               ,@Id = @G_Id_v
                               ,@Id_v1 = @G_Id_v1
                               ,@Id_v2 = @G_Id_v2
                               ,@Id_vals = @G_Id_vals
                               ,@SystemId = @G_SystemId_v
                               ,@SystemId_v1 = @G_SystemId_v1
                               ,@SystemId_v2 = @G_SystemId_v2
                               ,@SystemId_vals = @G_SystemId_vals
                               ,@UserId = @G_UserId_v
                               ,@UserId_v1 = @G_UserId_v1
                               ,@UserId_v2 = @G_UserId_v2
                               ,@UserId_vals = @G_UserId_vals
                               ,@Name = @G_Name_v
                               ,@Name_v1 = @G_Name_v1
                               ,@Name_v2 = @G_Name_v2
                               ,@Name_vals = @G_Name_vals
        END ELSE BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_SystemId bigint,@T_UserId bigint,@T_Name nvarchar(50)'
                               ,@T_Id = @WT_Id
                               ,@T_SystemId = @WT_SystemId
                               ,@T_UserId = @WT_UserId
                               ,@T_Name = @WT_Name
        END

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            DECLARE @SearchRecno BIGINT = NULL
            IF EXISTS(SELECT 1 FROM OPENJSON(@Search)) BEGIN
