                )
                SELECT @S_Name_v1 = TRY_CAST(JSON_VALUE(@S_Name_vals, '$[0]') AS nvarchar(50))
                      ,@S_Name_v2 = TRY_CAST(JSON_VALUE(@S_Name_vals, '$[1]') AS nvarchar(50))

                SET @Where = ''
                IF @S_Id_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_Id_comparator = 1 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 2 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 3 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 4 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 5 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 6 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 7 AND @S_Id_vals IS NOT NULL)
               OR (@S_Id_comparator = 8 AND @S_Id_vals IS NOT NULL)
               OR (@S_Id_comparator = 9 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 10 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 11 AND @S_Id_v1 IS NOT NULL AND @S_Id_v2 IS NOT NULL)
               OR (@S_Id_comparator = 12 AND @S_Id_v1 IS NOT NULL AND @S_Id_v2 IS NOT NULL)
               OR (@S_Id_comparator = 13)
               OR (@S_Id_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_Id_comparator
        WHEN 1 THEN N'COALESCE([D].[Id], [O].[Id]) < @Id'
        WHEN 2 THEN N'COALESCE([D].[Id], [O].[Id]) <= @Id'
        WHEN 3 THEN N'COALESCE([D].[Id], [O].[Id]) = @Id'
        WHEN 4 THEN N'COALESCE([D].[Id], [O].[Id]) <> @Id'
        WHEN 5 THEN N'COALESCE([D].[Id], [O].[Id]) >= @Id'
        WHEN 6 THEN N'COALESCE([D].[Id], [O].[Id]) > @Id'
        WHEN 7 THEN N'COALESCE([D].[Id], [O].[Id]) IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 8 THEN N'COALESCE([D].[Id], [O].[Id]) NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 9 THEN N'COALESCE([D].[Id], [O].[Id]) LIKE @Id'
        WHEN 10 THEN N'COALESCE([D].[Id], [O].[Id]) NOT LIKE @Id'
        WHEN 11 THEN N'COALESCE([D].[Id], [O].[Id]) BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'COALESCE([D].[Id], [O].[Id]) NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'COALESCE([D].[Id], [O].[Id]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[Id], [O].[Id]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'SystemId' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[SystemId], [O].[SystemId]) IS NULL'
                END ELSE
                IF @S_SystemId_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_SystemId_comparator = 1 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 2 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 3 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 4 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 5 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 6 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 7 AND @S_SystemId_vals IS NOT NULL)
               OR (@S_SystemId_comparator = 8 AND @S_SystemId_vals IS NOT NULL)
               OR (@S_SystemId_comparator = 9 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 10 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 11 AND @S_SystemId_v1 IS NOT NULL AND @S_SystemId_v2 IS NOT NULL)
               OR (@S_SystemId_comparator = 12 AND @S_SystemId_v1 IS NOT NULL AND @S_SystemId_v2 IS NOT NULL)
               OR (@S_SystemId_comparator = 13)
               OR (@S_SystemId_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_SystemId_comparator
        WHEN 1 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) < @SystemId'
        WHEN 2 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) <= @SystemId'
        WHEN 3 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) = @SystemId'
        WHEN 4 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) <> @SystemId'
        WHEN 5 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) >= @SystemId'
        WHEN 6 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) > @SystemId'
        WHEN 7 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@SystemId_vals))'
        WHEN 8 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@SystemId_vals))'
        WHEN 9 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) LIKE @SystemId'
        WHEN 10 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) NOT LIKE @SystemId'
        WHEN 11 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) BETWEEN @SystemId_v1 AND @SystemId_v2'
        WHEN 12 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) NOT BETWEEN @SystemId_v1 AND @SystemId_v2'
        WHEN 13 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'UserId' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[UserId], [O].[UserId]) IS NULL'
                END ELSE
                IF @S_UserId_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_UserId_comparator = 1 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 2 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 3 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 4 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 5 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 6 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 7 AND @S_UserId_vals IS NOT NULL)
               OR (@S_UserId_comparator = 8 AND @S_UserId_vals IS NOT NULL)
               OR (@S_UserId_comparator = 9 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 10 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 11 AND @S_UserId_v1 IS NOT NULL AND @S_UserId_v2 IS NOT NULL)
               OR (@S_UserId_comparator = 12 AND @S_UserId_v1 IS NOT NULL AND @S_UserId_v2 IS NOT NULL)
               OR (@S_UserId_comparator = 13)
               OR (@S_UserId_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_UserId_comparator
        WHEN 1 THEN N'COALESCE([D].[UserId], [O].[UserId]) < @UserId'
        WHEN 2 THEN N'COALESCE([D].[UserId], [O].[UserId]) <= @UserId'
        WHEN 3 THEN N'COALESCE([D].[UserId], [O].[UserId]) = @UserId'
        WHEN 4 THEN N'COALESCE([D].[UserId], [O].[UserId]) <> @UserId'
        WHEN 5 THEN N'COALESCE([D].[UserId], [O].[UserId]) >= @UserId'
        WHEN 6 THEN N'COALESCE([D].[UserId], [O].[UserId]) > @UserId'
        WHEN 7 THEN N'COALESCE([D].[UserId], [O].[UserId]) IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@UserId_vals))'
        WHEN 8 THEN N'COALESCE([D].[UserId], [O].[UserId]) NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@UserId_vals))'
        WHEN 9 THEN N'COALESCE([D].[UserId], [O].[UserId]) LIKE @UserId'
        WHEN 10 THEN N'COALESCE([D].[UserId], [O].[UserId]) NOT LIKE @UserId'
        WHEN 11 THEN N'COALESCE([D].[UserId], [O].[UserId]) BETWEEN @UserId_v1 AND @UserId_v2'
        WHEN 12 THEN N'COALESCE([D].[UserId], [O].[UserId]) NOT BETWEEN @UserId_v1 AND @UserId_v2'
        WHEN 13 THEN N'COALESCE([D].[UserId], [O].[UserId]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[UserId], [O].[UserId]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'Name' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[Name], [O].[Name]) IS NULL'
                END ELSE
                IF @S_Name_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_Name_comparator = 1 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 2 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 3 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 4 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 5 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 6 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 7 AND @S_Name_vals IS NOT NULL)
               OR (@S_Name_comparator = 8 AND @S_Name_vals IS NOT NULL)
               OR (@S_Name_comparator = 9 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 10 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 11 AND @S_Name_v1 IS NOT NULL AND @S_Name_v2 IS NOT NULL)
               OR (@S_Name_comparator = 12 AND @S_Name_v1 IS NOT NULL AND @S_Name_v2 IS NOT NULL)
               OR (@S_Name_comparator = 13)
               OR (@S_Name_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_Name_comparator
        WHEN 1 THEN N'COALESCE([D].[Name], [O].[Name]) < @Name'
        WHEN 2 THEN N'COALESCE([D].[Name], [O].[Name]) <= @Name'
        WHEN 3 THEN N'COALESCE([D].[Name], [O].[Name]) = @Name'
        WHEN 4 THEN N'COALESCE([D].[Name], [O].[Name]) <> @Name'
        WHEN 5 THEN N'COALESCE([D].[Name], [O].[Name]) >= @Name'
        WHEN 6 THEN N'COALESCE([D].[Name], [O].[Name]) > @Name'
        WHEN 7 THEN N'COALESCE([D].[Name], [O].[Name]) IN (SELECT CAST([value] AS nvarchar(50)) FROM OPENJSON(@Name_vals))'
        WHEN 8 THEN N'COALESCE([D].[Name], [O].[Name]) NOT IN (SELECT CAST([value] AS nvarchar(50)) FROM OPENJSON(@Name_vals))'
        WHEN 9 THEN N'COALESCE([D].[Name], [O].[Name]) LIKE @Name'
        WHEN 10 THEN N'COALESCE([D].[Name], [O].[Name]) NOT LIKE @Name'
        WHEN 11 THEN N'COALESCE([D].[Name], [O].[Name]) BETWEEN @Name_v1 AND @Name_v2'
        WHEN 12 THEN N'COALESCE([D].[Name], [O].[Name]) NOT BETWEEN @Name_v1 AND @Name_v2'
        WHEN 13 THEN N'COALESCE([D].[Name], [O].[Name]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[Name], [O].[Name]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[SystemsUsers] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@SystemId bigint,@SystemId_v1 bigint,@SystemId_v2 bigint,@SystemId_vals NVARCHAR(MAX),@UserId bigint,@UserId_v1 bigint,@UserId_v2 bigint,@UserId_vals NVARCHAR(MAX),@Name nvarchar(50),@Name_v1 nvarchar(50),@Name_v2 nvarchar(50),@Name_vals NVARCHAR(MAX), @r BIGINT OUTPUT'
                                       ,@Id = @S_Id_v
                                       ,@Id_v1 = @S_Id_v1
                                       ,@Id_v2 = @S_Id_v2
                                       ,@Id_vals = @S_Id_vals
                                       ,@SystemId = @S_SystemId_v
                                       ,@SystemId_v1 = @S_SystemId_v1
                                       ,@SystemId_v2 = @S_SystemId_v2
                                       ,@SystemId_vals = @S_SystemId_vals
                                       ,@UserId = @S_UserId_v
                                       ,@UserId_v1 = @S_UserId_v1
                                       ,@UserId_v2 = @S_UserId_v2
                                       ,@UserId_vals = @S_UserId_vals
                                       ,@Name = @S_Name_v
                                       ,@Name_v1 = @S_Name_v1
                                       ,@Name_v2 = @S_Name_v2
                                       ,@Name_vals = @S_Name_vals
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS bigint) AS [SystemId]
                    ,CAST(NULL AS bigint) AS [UserId]
                    ,CAST(NULL AS nvarchar(50)) AS [Name]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''SystemUser'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[SystemId]
                              ,[T].[UserId]
                              ,[T].[Name]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[SystemsUsers] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''SystemUser'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[SystemId]
                                  ,[O].[UserId]
                                  ,[O].[Name]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'System' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Description]
              ,[R].[ClientName]
              ,[R].[MaxRetryLogins]
              ,[R].[IsOffAir]
            INTO [#Systems]
            FROM [#result] [T]
                INNER JOIN [dbo].[Systems] [R] ON [R].[Id] = [T].[SystemId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Systems] ON [#Systems]([Id])
        SELECT DISTINCT 'User' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Password]
              ,[R].[FullName]
              ,[R].[RetryLogins]
              ,[R].[IsActive]
            INTO [#Users]
            FROM [#result] [T]
                INNER JOIN [dbo].[Users] [R] ON [R].[Id] = [T].[UserId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Users] ON [#Users]([Id])
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[SystemId]
                      ,[UserId]
                      ,[Name]
                      ,[Name] AS [ListItemValue]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [System].* FROM [#Systems] AS [System] FOR JSON PATH), '[]') AS [System]
              ,ISNULL((SELECT [User].* FROM [#Users] AS [User] FOR JSON PATH), '[]') AS [User]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[ConnectionValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[ConnectionValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[ConnectionValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[ConnectionValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id bigint

        IF @Action = 'delete' BEGIN
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

        END ELSE BEGIN
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        END
        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF EXISTS(SELECT 1 FROM [dbo].[Connections] WHERE [Id] = @W_Id) AND @Action = 'create'
            THROW 51000, 'Chave-primária já existe em Connections', 1
        ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Connections'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND                                           CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create' AND NOT EXISTS(SELECT 1 FROM [dbo].[Connections] WHERE [Id] = @W_Id)
            THROW 51000, 'Chave-primária não existe em Connections', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Connections]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [Environment] = JSON_VALUE(@LastRecord, '$.Environment')
                                  AND [ConnectionString] = JSON_VALUE(@LastRecord, '$.ConnectionString'))
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Connections'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Environment') = JSON_VALUE(@LastRecord, '$.Environment')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ConnectionString') = JSON_VALUE(@LastRecord, '$.ConnectionString'))
                THROW 51000, 'Registro de Connections alterado por outro usuário', 1
        END

        IF @Action = 'delete' BEGIN
            IF EXISTS(SELECT 1 FROM [dbo].[Databases] WHERE [ConnectionId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em Databases', 1
        END
        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_Environment nvarchar(3) = CAST(JSON_VALUE(@ActualRecord, '$.Environment') AS nvarchar(3))
                   ,@W_ConnectionString nvarchar(256) = CAST(JSON_VALUE(@ActualRecord, '$.ConnectionString') AS nvarchar(256))

            IF @W_Environment IS NULL
                THROW 51000, 'Valor de Environment em @ActualRecord é requerido.', 1
            IF @W_ConnectionString IS NULL
                THROW 51000, 'Valor de ConnectionString em @ActualRecord é requerido.', 1
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[ConnectionPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[ConnectionPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[ConnectionPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[ConnectionPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
               ,@W_Id bigint

    IF @Action = 'delete' BEGIN
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

    END ELSE BEGIN
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    END
    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Connections'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Connections', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[ConnectionValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Connections'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            SET IDENTITY_INSERT [dbo].[Operations] ON
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Connections'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
            SET IDENTITY_INSERT [dbo].[Operations] OFF
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create'
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[ConnectionValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @ActionAux = 'create'
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId

    RETURN CAST(@OperationId AS BIGINT)
END
GO

