/**********************************************************************************
Criar stored procedure [dbo].[ConnectionsRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[ConnectionsRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[ConnectionsRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[ConnectionsRead](@Login NVARCHAR(MAX)
                                          ,@Filter NVARCHAR(MAX)
                                          ,@Search NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

        IF @Filter IS NULL
            SET @Filter = '{}'
        ELSE IF ISJSON(@Filter) = 0
            THROW 51000, 'Valor de @Filter não está no formato JSON', 1
        IF @Search IS NULL
            SET @Search = '{}'
        ELSE IF ISJSON(@Search) = 0
            THROW 51000, 'Valor de @Search não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Connections') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @SessionId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Environment') AS nvarchar(3)) AS [Environment]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ConnectionString') AS nvarchar(256)) AS [ConnectionString]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Connections'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@Filter, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@ComparatorPredicate NVARCHAR(MAX)
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id bigint = CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)
               ,@WT_Environment nvarchar(3) = CAST(JSON_VALUE(@Filter, '$.Environment') AS nvarchar(3))
               ,@WT_ConnectionString nvarchar(256) = CAST(JSON_VALUE(@Filter, '$.ConnectionString') AS nvarchar(256))

        IF @WT_Id IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Id] = @T_Id'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'Environment' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Environment] IS NULL'
        ELSE IF @WT_Environment IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Environment] = @T_Environment'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'ConnectionString' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[ConnectionString] IS NULL'
        ELSE IF @WT_ConnectionString IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[ConnectionString] = @T_ConnectionString'
        END
        IF @_ IS NULL BEGIN
            DECLARE @G_Id_comparator TINYINT
                   ,@G_Id_v bigint
                   ,@G_Id_vals NVARCHAR(MAX)
                   ,@G_Id_v1 bigint
                   ,@G_Id_v2 bigint
                   ,@G_Environment_comparator TINYINT
                   ,@G_Environment_v nvarchar(3)
                   ,@G_Environment_vals NVARCHAR(MAX)
                   ,@G_Environment_v1 nvarchar(3)
                   ,@G_Environment_v2 nvarchar(3)
                   ,@G_ConnectionString_comparator TINYINT
                   ,@G_ConnectionString_v nvarchar(256)
                   ,@G_ConnectionString_vals NVARCHAR(MAX)
                   ,@G_ConnectionString_v1 nvarchar(256)
                   ,@G_ConnectionString_v2 nvarchar(256)

            SELECT @G_Id_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Id') IS NOT NULL AND JSON_QUERY(@Filter, '$.Id') IS NULL THEN 3 END
            )
                  ,@G_Id_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.value') AS bigint),
                TRY_CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)
            )
                  ,@G_Id_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Id.value'),
                JSON_QUERY(@Filter, '$.Id')
            )
            SELECT @G_Id_v1 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[0]') AS bigint)
                  ,@G_Id_v2 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[1]') AS bigint)
            SELECT @G_Environment_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Environment.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Environment') IS NOT NULL AND JSON_QUERY(@Filter, '$.Environment') IS NULL THEN 3 END
            )
                  ,@G_Environment_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Environment.value') AS nvarchar(3)),
                TRY_CAST(JSON_VALUE(@Filter, '$.Environment') AS nvarchar(3))
            )
                  ,@G_Environment_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Environment.value'),
                JSON_QUERY(@Filter, '$.Environment')
            )
            SELECT @G_Environment_v1 = TRY_CAST(JSON_VALUE(@G_Environment_vals, '$[0]') AS nvarchar(3))
                  ,@G_Environment_v2 = TRY_CAST(JSON_VALUE(@G_Environment_vals, '$[1]') AS nvarchar(3))
            SELECT @G_ConnectionString_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.ConnectionString.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.ConnectionString') IS NOT NULL AND JSON_QUERY(@Filter, '$.ConnectionString') IS NULL THEN 3 END
            )
                  ,@G_ConnectionString_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.ConnectionString.value') AS nvarchar(256)),
                TRY_CAST(JSON_VALUE(@Filter, '$.ConnectionString') AS nvarchar(256))
            )
                  ,@G_ConnectionString_vals = COALESCE(
                JSON_QUERY(@Filter, '$.ConnectionString.value'),
                JSON_QUERY(@Filter, '$.ConnectionString')
            )
            SELECT @G_ConnectionString_v1 = TRY_CAST(JSON_VALUE(@G_ConnectionString_vals, '$[0]') AS nvarchar(256))
                  ,@G_ConnectionString_v2 = TRY_CAST(JSON_VALUE(@G_ConnectionString_vals, '$[1]') AS nvarchar(256))

            IF @G_Id_comparator IS NOT NULL BEGIN
                IF (@G_Id_comparator = 1 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 2 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 3 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 4 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 5 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 6 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 7 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 8 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 9 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 10 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 11 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 12 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 13)
               OR (@G_Id_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_Id_comparator
        WHEN 1 THEN N'[T].[Id] < @Id'
        WHEN 2 THEN N'[T].[Id] <= @Id'
        WHEN 3 THEN N'[T].[Id] = @Id'
        WHEN 4 THEN N'[T].[Id] <> @Id'
        WHEN 5 THEN N'[T].[Id] >= @Id'
        WHEN 6 THEN N'[T].[Id] > @Id'
        WHEN 7 THEN N'[T].[Id] IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 8 THEN N'[T].[Id] NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 9 THEN N'[T].[Id] LIKE @Id'
        WHEN 10 THEN N'[T].[Id] NOT LIKE @Id'
        WHEN 11 THEN N'[T].[Id] BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'[T].[Id] NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'[T].[Id] IS NULL'
        WHEN 14 THEN N'[T].[Id] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'Environment' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[Environment] IS NULL'
            ELSE
            IF @G_Environment_comparator IS NOT NULL BEGIN
                IF (@G_Environment_comparator = 1 AND @G_Environment_v IS NOT NULL)
               OR (@G_Environment_comparator = 2 AND @G_Environment_v IS NOT NULL)
               OR (@G_Environment_comparator = 3 AND @G_Environment_v IS NOT NULL)
               OR (@G_Environment_comparator = 4 AND @G_Environment_v IS NOT NULL)
               OR (@G_Environment_comparator = 5 AND @G_Environment_v IS NOT NULL)
               OR (@G_Environment_comparator = 6 AND @G_Environment_v IS NOT NULL)
               OR (@G_Environment_comparator = 7 AND @G_Environment_vals IS NOT NULL)
               OR (@G_Environment_comparator = 8 AND @G_Environment_vals IS NOT NULL)
               OR (@G_Environment_comparator = 9 AND @G_Environment_v IS NOT NULL)
               OR (@G_Environment_comparator = 10 AND @G_Environment_v IS NOT NULL)
               OR (@G_Environment_comparator = 11 AND @G_Environment_v1 IS NOT NULL AND @G_Environment_v2 IS NOT NULL)
               OR (@G_Environment_comparator = 12 AND @G_Environment_v1 IS NOT NULL AND @G_Environment_v2 IS NOT NULL)
               OR (@G_Environment_comparator = 13)
               OR (@G_Environment_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_Environment_comparator
        WHEN 1 THEN N'[T].[Environment] < @Environment'
        WHEN 2 THEN N'[T].[Environment] <= @Environment'
        WHEN 3 THEN N'[T].[Environment] = @Environment'
        WHEN 4 THEN N'[T].[Environment] <> @Environment'
        WHEN 5 THEN N'[T].[Environment] >= @Environment'
        WHEN 6 THEN N'[T].[Environment] > @Environment'
        WHEN 7 THEN N'[T].[Environment] IN (SELECT CAST([value] AS nvarchar(3)) FROM OPENJSON(@Environment_vals))'
        WHEN 8 THEN N'[T].[Environment] NOT IN (SELECT CAST([value] AS nvarchar(3)) FROM OPENJSON(@Environment_vals))'
        WHEN 9 THEN N'[T].[Environment] LIKE @Environment'
        WHEN 10 THEN N'[T].[Environment] NOT LIKE @Environment'
        WHEN 11 THEN N'[T].[Environment] BETWEEN @Environment_v1 AND @Environment_v2'
        WHEN 12 THEN N'[T].[Environment] NOT BETWEEN @Environment_v1 AND @Environment_v2'
        WHEN 13 THEN N'[T].[Environment] IS NULL'
        WHEN 14 THEN N'[T].[Environment] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'ConnectionString' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[ConnectionString] IS NULL'
            ELSE
            IF @G_ConnectionString_comparator IS NOT NULL BEGIN
                IF (@G_ConnectionString_comparator = 1 AND @G_ConnectionString_v IS NOT NULL)
               OR (@G_ConnectionString_comparator = 2 AND @G_ConnectionString_v IS NOT NULL)
               OR (@G_ConnectionString_comparator = 3 AND @G_ConnectionString_v IS NOT NULL)
               OR (@G_ConnectionString_comparator = 4 AND @G_ConnectionString_v IS NOT NULL)
               OR (@G_ConnectionString_comparator = 5 AND @G_ConnectionString_v IS NOT NULL)
               OR (@G_ConnectionString_comparator = 6 AND @G_ConnectionString_v IS NOT NULL)
               OR (@G_ConnectionString_comparator = 7 AND @G_ConnectionString_vals IS NOT NULL)
               OR (@G_ConnectionString_comparator = 8 AND @G_ConnectionString_vals IS NOT NULL)
               OR (@G_ConnectionString_comparator = 9 AND @G_ConnectionString_v IS NOT NULL)
               OR (@G_ConnectionString_comparator = 10 AND @G_ConnectionString_v IS NOT NULL)
               OR (@G_ConnectionString_comparator = 11 AND @G_ConnectionString_v1 IS NOT NULL AND @G_ConnectionString_v2 IS NOT NULL)
               OR (@G_ConnectionString_comparator = 12 AND @G_ConnectionString_v1 IS NOT NULL AND @G_ConnectionString_v2 IS NOT NULL)
               OR (@G_ConnectionString_comparator = 13)
               OR (@G_ConnectionString_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_ConnectionString_comparator
        WHEN 1 THEN N'[T].[ConnectionString] < @ConnectionString'
        WHEN 2 THEN N'[T].[ConnectionString] <= @ConnectionString'
        WHEN 3 THEN N'[T].[ConnectionString] = @ConnectionString'
        WHEN 4 THEN N'[T].[ConnectionString] <> @ConnectionString'
        WHEN 5 THEN N'[T].[ConnectionString] >= @ConnectionString'
        WHEN 6 THEN N'[T].[ConnectionString] > @ConnectionString'
        WHEN 7 THEN N'[T].[ConnectionString] IN (SELECT CAST([value] AS nvarchar(256)) FROM OPENJSON(@ConnectionString_vals))'
        WHEN 8 THEN N'[T].[ConnectionString] NOT IN (SELECT CAST([value] AS nvarchar(256)) FROM OPENJSON(@ConnectionString_vals))'
        WHEN 9 THEN N'[T].[ConnectionString] LIKE @ConnectionString'
        WHEN 10 THEN N'[T].[ConnectionString] NOT LIKE @ConnectionString'
        WHEN 11 THEN N'[T].[ConnectionString] BETWEEN @ConnectionString_v1 AND @ConnectionString_v2'
        WHEN 12 THEN N'[T].[ConnectionString] NOT BETWEEN @ConnectionString_v1 AND @ConnectionString_v2'
        WHEN 13 THEN N'[T].[ConnectionString] IS NULL'
        WHEN 14 THEN N'[T].[ConnectionString] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
        END ELSE
            SET @Where = @Where + ' AND [T].[Id] IN (' + @_ + ')'

        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] bigint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[U].[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                              ,[T].[Id]
                                    FROM [dbo].[Connections] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [T].[Id] = [#].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                              ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @_ IS NULL BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_Environment nvarchar(3),@T_ConnectionString nvarchar(256),@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@Environment nvarchar(3),@Environment_v1 nvarchar(3),@Environment_v2 nvarchar(3),@Environment_vals NVARCHAR(MAX),@ConnectionString nvarchar(256),@ConnectionString_v1 nvarchar(256),@ConnectionString_v2 nvarchar(256),@ConnectionString_vals NVARCHAR(MAX)'
                               ,@T_Id = @WT_Id
                               ,@T_Environment = @WT_Environment
                               ,@T_ConnectionString = @WT_ConnectionString
                               ,@Id = @G_Id_v
                               ,@Id_v1 = @G_Id_v1
                               ,@Id_v2 = @G_Id_v2
                               ,@Id_vals = @G_Id_vals
                               ,@Environment = @G_Environment_v
                               ,@Environment_v1 = @G_Environment_v1
                               ,@Environment_v2 = @G_Environment_v2
                               ,@Environment_vals = @G_Environment_vals
                               ,@ConnectionString = @G_ConnectionString_v
                               ,@ConnectionString_v1 = @G_ConnectionString_v1
                               ,@ConnectionString_v2 = @G_ConnectionString_v2
                               ,@ConnectionString_vals = @G_ConnectionString_vals
        END ELSE BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_Environment nvarchar(3),@T_ConnectionString nvarchar(256)'
                               ,@T_Id = @WT_Id
                               ,@T_Environment = @WT_Environment
                               ,@T_ConnectionString = @WT_ConnectionString
        END

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            DECLARE @SearchRecno BIGINT = NULL
            IF EXISTS(SELECT 1 FROM OPENJSON(@Search)) BEGIN
                DECLARE @Recno BIGINT
                   ,@S_Id_comparator TINYINT
                   ,@S_Id_v bigint
                   ,@S_Id_vals NVARCHAR(MAX)
                   ,@S_Id_v1 bigint
                   ,@S_Id_v2 bigint
                   ,@S_Environment_comparator TINYINT
                   ,@S_Environment_v nvarchar(3)
                   ,@S_Environment_vals NVARCHAR(MAX)
                   ,@S_Environment_v1 nvarchar(3)
                   ,@S_Environment_v2 nvarchar(3)
                   ,@S_ConnectionString_comparator TINYINT
                   ,@S_ConnectionString_v nvarchar(256)
                   ,@S_ConnectionString_vals NVARCHAR(MAX)
                   ,@S_ConnectionString_v1 nvarchar(256)
                   ,@S_ConnectionString_v2 nvarchar(256)

                SELECT @S_Id_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Id.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.Id') IS NOT NULL AND JSON_QUERY(@Search, '$.Id') IS NULL THEN 3 END
                )
                      ,@S_Id_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Id.value') AS bigint),
                    TRY_CAST(JSON_VALUE(@Search, '$.Id') AS bigint)
                )
                      ,@S_Id_vals = COALESCE(
                    JSON_QUERY(@Search, '$.Id.value'),
                    JSON_QUERY(@Search, '$.Id')
                )
                SELECT @S_Id_v1 = TRY_CAST(JSON_VALUE(@S_Id_vals, '$[0]') AS bigint)
                      ,@S_Id_v2 = TRY_CAST(JSON_VALUE(@S_Id_vals, '$[1]') AS bigint)
                SELECT @S_Environment_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Environment.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.Environment') IS NOT NULL AND JSON_QUERY(@Search, '$.Environment') IS NULL THEN 9 END
                )
                      ,@S_Environment_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Environment.value') AS nvarchar(3)),
                    TRY_CAST(JSON_VALUE(@Search, '$.Environment') AS nvarchar(3))
                )
                      ,@S_Environment_vals = COALESCE(
                    JSON_QUERY(@Search, '$.Environment.value'),
                    JSON_QUERY(@Search, '$.Environment')
                )
                SELECT @S_Environment_v1 = TRY_CAST(JSON_VALUE(@S_Environment_vals, '$[0]') AS nvarchar(3))
                      ,@S_Environment_v2 = TRY_CAST(JSON_VALUE(@S_Environment_vals, '$[1]') AS nvarchar(3))
                SELECT @S_ConnectionString_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.ConnectionString.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.ConnectionString') IS NOT NULL AND JSON_QUERY(@Search, '$.ConnectionString') IS NULL THEN 9 END
                )
                      ,@S_ConnectionString_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.ConnectionString.value') AS nvarchar(256)),
                    TRY_CAST(JSON_VALUE(@Search, '$.ConnectionString') AS nvarchar(256))
                )
                      ,@S_ConnectionString_vals = COALESCE(
                    JSON_QUERY(@Search, '$.ConnectionString.value'),
                    JSON_QUERY(@Search, '$.ConnectionString')
                )
                SELECT @S_ConnectionString_v1 = TRY_CAST(JSON_VALUE(@S_ConnectionString_vals, '$[0]') AS nvarchar(256))
                      ,@S_ConnectionString_v2 = TRY_CAST(JSON_VALUE(@S_ConnectionString_vals, '$[1]') AS nvarchar(256))

                SET @Where = ''
                IF @S_Id_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_Id_comparator = 1 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 2 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 3 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 4 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 5 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 6 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 7 AND @S_Id_vals IS NOT NULL)
               OR (@S_Id_comparator = 8 AND @S_Id_vals IS NOT NULL)
               OR (@S_Id_comparator = 9 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 10 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 11 AND @S_Id_v1 IS NOT NULL AND @S_Id_v2 IS NOT NULL)
               OR (@S_Id_comparator = 12 AND @S_Id_v1 IS NOT NULL AND @S_Id_v2 IS NOT NULL)
               OR (@S_Id_comparator = 13)
               OR (@S_Id_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_Id_comparator
        WHEN 1 THEN N'COALESCE([D].[Id], [O].[Id]) < @Id'
        WHEN 2 THEN N'COALESCE([D].[Id], [O].[Id]) <= @Id'
        WHEN 3 THEN N'COALESCE([D].[Id], [O].[Id]) = @Id'
        WHEN 4 THEN N'COALESCE([D].[Id], [O].[Id]) <> @Id'
        WHEN 5 THEN N'COALESCE([D].[Id], [O].[Id]) >= @Id'
        WHEN 6 THEN N'COALESCE([D].[Id], [O].[Id]) > @Id'
        WHEN 7 THEN N'COALESCE([D].[Id], [O].[Id]) IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 8 THEN N'COALESCE([D].[Id], [O].[Id]) NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 9 THEN N'COALESCE([D].[Id], [O].[Id]) LIKE @Id'
        WHEN 10 THEN N'COALESCE([D].[Id], [O].[Id]) NOT LIKE @Id'
        WHEN 11 THEN N'COALESCE([D].[Id], [O].[Id]) BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'COALESCE([D].[Id], [O].[Id]) NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'COALESCE([D].[Id], [O].[Id]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[Id], [O].[Id]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'Environment' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[Environment], [O].[Environment]) IS NULL'
                END ELSE
                IF @S_Environment_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_Environment_comparator = 1 AND @S_Environment_v IS NOT NULL)
               OR (@S_Environment_comparator = 2 AND @S_Environment_v IS NOT NULL)
               OR (@S_Environment_comparator = 3 AND @S_Environment_v IS NOT NULL)
               OR (@S_Environment_comparator = 4 AND @S_Environment_v IS NOT NULL)
               OR (@S_Environment_comparator = 5 AND @S_Environment_v IS NOT NULL)
               OR (@S_Environment_comparator = 6 AND @S_Environment_v IS NOT NULL)
               OR (@S_Environment_comparator = 7 AND @S_Environment_vals IS NOT NULL)
               OR (@S_Environment_comparator = 8 AND @S_Environment_vals IS NOT NULL)
               OR (@S_Environment_comparator = 9 AND @S_Environment_v IS NOT NULL)
               OR (@S_Environment_comparator = 10 AND @S_Environment_v IS NOT NULL)
               OR (@S_Environment_comparator = 11 AND @S_Environment_v1 IS NOT NULL AND @S_Environment_v2 IS NOT NULL)
               OR (@S_Environment_comparator = 12 AND @S_Environment_v1 IS NOT NULL AND @S_Environment_v2 IS NOT NULL)
               OR (@S_Environment_comparator = 13)
               OR (@S_Environment_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_Environment_comparator
        WHEN 1 THEN N'COALESCE([D].[Environment], [O].[Environment]) < @Environment'
        WHEN 2 THEN N'COALESCE([D].[Environment], [O].[Environment]) <= @Environment'
        WHEN 3 THEN N'COALESCE([D].[Environment], [O].[Environment]) = @Environment'
        WHEN 4 THEN N'COALESCE([D].[Environment], [O].[Environment]) <> @Environment'
        WHEN 5 THEN N'COALESCE([D].[Environment], [O].[Environment]) >= @Environment'
        WHEN 6 THEN N'COALESCE([D].[Environment], [O].[Environment]) > @Environment'
        WHEN 7 THEN N'COALESCE([D].[Environment], [O].[Environment]) IN (SELECT CAST([value] AS nvarchar(3)) FROM OPENJSON(@Environment_vals))'
        WHEN 8 THEN N'COALESCE([D].[Environment], [O].[Environment]) NOT IN (SELECT CAST([value] AS nvarchar(3)) FROM OPENJSON(@Environment_vals))'
        WHEN 9 THEN N'COALESCE([D].[Environment], [O].[Environment]) LIKE @Environment'
        WHEN 10 THEN N'COALESCE([D].[Environment], [O].[Environment]) NOT LIKE @Environment'
        WHEN 11 THEN N'COALESCE([D].[Environment], [O].[Environment]) BETWEEN @Environment_v1 AND @Environment_v2'
        WHEN 12 THEN N'COALESCE([D].[Environment], [O].[Environment]) NOT BETWEEN @Environment_v1 AND @Environment_v2'
        WHEN 13 THEN N'COALESCE([D].[Environment], [O].[Environment]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[Environment], [O].[Environment]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'ConnectionString' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[ConnectionString], [O].[ConnectionString]) IS NULL'
                END ELSE
                IF @S_ConnectionString_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_ConnectionString_comparator = 1 AND @S_ConnectionString_v IS NOT NULL)
               OR (@S_ConnectionString_comparator = 2 AND @S_ConnectionString_v IS NOT NULL)
               OR (@S_ConnectionString_comparator = 3 AND @S_ConnectionString_v IS NOT NULL)
               OR (@S_ConnectionString_comparator = 4 AND @S_ConnectionString_v IS NOT NULL)
               OR (@S_ConnectionString_comparator = 5 AND @S_ConnectionString_v IS NOT NULL)
               OR (@S_ConnectionString_comparator = 6 AND @S_ConnectionString_v IS NOT NULL)
               OR (@S_ConnectionString_comparator = 7 AND @S_ConnectionString_vals IS NOT NULL)
               OR (@S_ConnectionString_comparator = 8 AND @S_ConnectionString_vals IS NOT NULL)
               OR (@S_ConnectionString_comparator = 9 AND @S_ConnectionString_v IS NOT NULL)
               OR (@S_ConnectionString_comparator = 10 AND @S_ConnectionString_v IS NOT NULL)
               OR (@S_ConnectionString_comparator = 11 AND @S_ConnectionString_v1 IS NOT NULL AND @S_ConnectionString_v2 IS NOT NULL)
               OR (@S_ConnectionString_comparator = 12 AND @S_ConnectionString_v1 IS NOT NULL AND @S_ConnectionString_v2 IS NOT NULL)
               OR (@S_ConnectionString_comparator = 13)
               OR (@S_ConnectionString_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_ConnectionString_comparator
        WHEN 1 THEN N'COALESCE([D].[ConnectionString], [O].[ConnectionString]) < @ConnectionString'
        WHEN 2 THEN N'COALESCE([D].[ConnectionString], [O].[ConnectionString]) <= @ConnectionString'
        WHEN 3 THEN N'COALESCE([D].[ConnectionString], [O].[ConnectionString]) = @ConnectionString'
        WHEN 4 THEN N'COALESCE([D].[ConnectionString], [O].[ConnectionString]) <> @ConnectionString'
        WHEN 5 THEN N'COALESCE([D].[ConnectionString], [O].[ConnectionString]) >= @ConnectionString'
        WHEN 6 THEN N'COALESCE([D].[ConnectionString], [O].[ConnectionString]) > @ConnectionString'
        WHEN 7 THEN N'COALESCE([D].[ConnectionString], [O].[ConnectionString]) IN (SELECT CAST([value] AS nvarchar(256)) FROM OPENJSON(@ConnectionString_vals))'
        WHEN 8 THEN N'COALESCE([D].[ConnectionString], [O].[ConnectionString]) NOT IN (SELECT CAST([value] AS nvarchar(256)) FROM OPENJSON(@ConnectionString_vals))'
        WHEN 9 THEN N'COALESCE([D].[ConnectionString], [O].[ConnectionString]) LIKE @ConnectionString'
        WHEN 10 THEN N'COALESCE([D].[ConnectionString], [O].[ConnectionString]) NOT LIKE @ConnectionString'
        WHEN 11 THEN N'COALESCE([D].[ConnectionString], [O].[ConnectionString]) BETWEEN @ConnectionString_v1 AND @ConnectionString_v2'
        WHEN 12 THEN N'COALESCE([D].[ConnectionString], [O].[ConnectionString]) NOT BETWEEN @ConnectionString_v1 AND @ConnectionString_v2'
        WHEN 13 THEN N'COALESCE([D].[ConnectionString], [O].[ConnectionString]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[ConnectionString], [O].[ConnectionString]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[Connections] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@Environment nvarchar(3),@Environment_v1 nvarchar(3),@Environment_v2 nvarchar(3),@Environment_vals NVARCHAR(MAX),@ConnectionString nvarchar(256),@ConnectionString_v1 nvarchar(256),@ConnectionString_v2 nvarchar(256),@ConnectionString_vals NVARCHAR(MAX), @r BIGINT OUTPUT'
                                       ,@Id = @S_Id_v
                                       ,@Id_v1 = @S_Id_v1
                                       ,@Id_v2 = @S_Id_v2
                                       ,@Id_vals = @S_Id_vals
                                       ,@Environment = @S_Environment_v
                                       ,@Environment_v1 = @S_Environment_v1
                                       ,@Environment_v2 = @S_Environment_v2
                                       ,@Environment_vals = @S_Environment_vals
                                       ,@ConnectionString = @S_ConnectionString_v
                                       ,@ConnectionString_v1 = @S_ConnectionString_v1
                                       ,@ConnectionString_v2 = @S_ConnectionString_v2
                                       ,@ConnectionString_vals = @S_ConnectionString_vals
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS nvarchar(3)) AS [Environment]
                    ,CAST(NULL AS nvarchar(256)) AS [ConnectionString]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''Connection'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[Environment]
                              ,[T].[ConnectionString]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Connections] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Connection'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[Environment]
                                  ,[O].[ConnectionString]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[Environment]
                      ,[ConnectionString]
                    FROM [#result] FOR JSON PATH) AS [result]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[DatabaseValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[DatabaseValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[DatabaseValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[DatabaseValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id bigint

        IF @Action = 'delete' BEGIN
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

        END ELSE BEGIN
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        END
        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS bigint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[Databases] WHERE [Id] = @W_Id) AND @Action = 'create'
            THROW 51000, 'Chave-primária já existe em Databases', 1
        ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Databases'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND                                           CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create' AND NOT EXISTS(SELECT 1 FROM [dbo].[Databases] WHERE [Id] = @W_Id)
            THROW 51000, 'Chave-primária não existe em Databases', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Databases]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [ConnectionId] = JSON_VALUE(@LastRecord, '$.ConnectionId')
                                  AND [Name] = JSON_VALUE(@LastRecord, '$.Name')
                                  AND [Alias] = JSON_VALUE(@LastRecord, '$.Alias')
                                  AND [Description] = JSON_VALUE(@LastRecord, '$.Description')
                                  AND [dbo].[IS_EQUAL]([Folder], JSON_VALUE(@LastRecord, '$.Folder'), 'nvarchar') = 1
                                  AND [IsLegacy] = JSON_VALUE(@LastRecord, '$.IsLegacy')
                                  AND [CurrentOperationId] = JSON_VALUE(@LastRecord, '$.CurrentOperationId'))
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Databases'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ConnectionId') = JSON_VALUE(@LastRecord, '$.ConnectionId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') = JSON_VALUE(@LastRecord, '$.Name')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Alias') = JSON_VALUE(@LastRecord, '$.Alias')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Description') = JSON_VALUE(@LastRecord, '$.Description')
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Folder'), JSON_VALUE(@LastRecord, '$.Folder'), 'nvarchar') = 1
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsLegacy') = JSON_VALUE(@LastRecord, '$.IsLegacy')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.CurrentOperationId') = JSON_VALUE(@LastRecord, '$.CurrentOperationId'))
                THROW 51000, 'Registro de Databases alterado por outro usuário', 1
        END

        IF @Action = 'delete' BEGIN
            IF EXISTS(SELECT 1 FROM [dbo].[SystemsDatabases] WHERE [DatabaseId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em SystemsDatabases', 1
            IF EXISTS(SELECT 1 FROM [dbo].[DatabasesTables] WHERE [DatabaseId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em DatabasesTables', 1
        END
        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_ConnectionId bigint = CAST(JSON_VALUE(@ActualRecord, '$.ConnectionId') AS bigint)
                   ,@W_Name nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(25))
                   ,@W_Alias nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.Alias') AS nvarchar(25))
                   ,@W_Description nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Description') AS nvarchar(50))
                   ,@W_Folder nvarchar(256) = CAST(JSON_VALUE(@ActualRecord, '$.Folder') AS nvarchar(256))
                   ,@W_IsLegacy bit = CAST(JSON_VALUE(@ActualRecord, '$.IsLegacy') AS bit)
                   ,@W_CurrentOperationId bigint = CAST(JSON_VALUE(@ActualRecord, '$.CurrentOperationId') AS bigint)

            IF @W_ConnectionId IS NULL
                THROW 51000, 'Valor de ConnectionId em @ActualRecord é requerido.', 1
            IF @W_ConnectionId < CAST('1' AS bigint)
                THROW 51000, 'Valor de ConnectionId em @ActualRecord deve ser maior que ou igual a 1', 1
            IF @W_Name IS NULL
                THROW 51000, 'Valor de Name em @ActualRecord é requerido.', 1
            IF @W_Alias IS NULL
                THROW 51000, 'Valor de Alias em @ActualRecord é requerido.', 1
            IF @W_Description IS NULL
                THROW 51000, 'Valor de Description em @ActualRecord é requerido.', 1
            IF @W_IsLegacy IS NULL
                THROW 51000, 'Valor de IsLegacy em @ActualRecord é requerido.', 1
            IF @W_CurrentOperationId IS NULL
                THROW 51000, 'Valor de CurrentOperationId em @ActualRecord é requerido.', 1
            IF @W_CurrentOperationId < CAST('0' AS bigint)
                THROW 51000, 'Valor de CurrentOperationId em @ActualRecord deve ser maior que ou igual a 0', 1
            IF (@W_ConnectionId IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM [dbo].[Connections] WHERE [Id] = @W_ConnectionId)
                THROW 51000, 'Valor de FK em @ActualRecord inexiste em Connections', 1
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[DatabasePersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[DatabasePersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[DatabasePersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[DatabasePersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
               ,@W_Id bigint

    IF @Action = 'delete' BEGIN
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

    END ELSE BEGIN
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    END
    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Databases'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Databases', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[DatabaseValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Databases'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            SET IDENTITY_INSERT [dbo].[Operations] ON
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Databases'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
            SET IDENTITY_INSERT [dbo].[Operations] OFF
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create'
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[DatabaseValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @ActionAux = 'create'
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId

    RETURN CAST(@OperationId AS BIGINT)
END
GO

