        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] bigint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[U].[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                              ,[T].[Id]
                                    FROM [dbo].[Databases] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [T].[Id] = [#].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                              ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @IsActionList = 1 BEGIN
            EXEC sp_executesql @sql
                               ,N'@PickerValue nvarchar(25),@T_Id bigint,@T_ConnectionId bigint,@T_Name nvarchar(25),@T_Alias nvarchar(25)'
                               ,@PickerValue = @PickerValue
                               ,@T_Id = @WT_Id
                               ,@T_ConnectionId = @WT_ConnectionId
                               ,@T_Name = @WT_Name
                               ,@T_Alias = @WT_Alias
        END ELSE IF @_ IS NULL BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_ConnectionId bigint,@T_Name nvarchar(25),@T_Alias nvarchar(25),@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@ConnectionId bigint,@ConnectionId_v1 bigint,@ConnectionId_v2 bigint,@ConnectionId_vals NVARCHAR(MAX),@Name nvarchar(25),@Name_v1 nvarchar(25),@Name_v2 nvarchar(25),@Name_vals NVARCHAR(MAX),@Alias nvarchar(25),@Alias_v1 nvarchar(25),@Alias_v2 nvarchar(25),@Alias_vals NVARCHAR(MAX)'
                               ,@T_Id = @WT_Id
                               ,@T_ConnectionId = @WT_ConnectionId
                               ,@T_Name = @WT_Name
                               ,@T_Alias = @WT_Alias
                               ,@Id = @G_Id_v
                               ,@Id_v1 = @G_Id_v1
                               ,@Id_v2 = @G_Id_v2
                               ,@Id_vals = @G_Id_vals
                               ,@ConnectionId = @G_ConnectionId_v
                               ,@ConnectionId_v1 = @G_ConnectionId_v1
                               ,@ConnectionId_v2 = @G_ConnectionId_v2
                               ,@ConnectionId_vals = @G_ConnectionId_vals
                               ,@Name = @G_Name_v
                               ,@Name_v1 = @G_Name_v1
                               ,@Name_v2 = @G_Name_v2
                               ,@Name_vals = @G_Name_vals
                               ,@Alias = @G_Alias_v
                               ,@Alias_v1 = @G_Alias_v1
                               ,@Alias_v2 = @G_Alias_v2
                               ,@Alias_vals = @G_Alias_vals
        END ELSE BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_ConnectionId bigint,@T_Name nvarchar(25),@T_Alias nvarchar(25)'
                               ,@T_Id = @WT_Id
