        WHEN 11 THEN N'COALESCE([D].[Id], [O].[Id]) BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'COALESCE([D].[Id], [O].[Id]) NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'COALESCE([D].[Id], [O].[Id]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[Id], [O].[Id]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'ConnectionId' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[ConnectionId], [O].[ConnectionId]) IS NULL'
                END ELSE
                IF @S_ConnectionId_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_ConnectionId_comparator = 1 AND @S_ConnectionId_v IS NOT NULL)
               OR (@S_ConnectionId_comparator = 2 AND @S_ConnectionId_v IS NOT NULL)
               OR (@S_ConnectionId_comparator = 3 AND @S_ConnectionId_v IS NOT NULL)
               OR (@S_ConnectionId_comparator = 4 AND @S_ConnectionId_v IS NOT NULL)
               OR (@S_ConnectionId_comparator = 5 AND @S_ConnectionId_v IS NOT NULL)
               OR (@S_ConnectionId_comparator = 6 AND @S_ConnectionId_v IS NOT NULL)
               OR (@S_ConnectionId_comparator = 7 AND @S_ConnectionId_vals IS NOT NULL)
               OR (@S_ConnectionId_comparator = 8 AND @S_ConnectionId_vals IS NOT NULL)
               OR (@S_ConnectionId_comparator = 9 AND @S_ConnectionId_v IS NOT NULL)
               OR (@S_ConnectionId_comparator = 10 AND @S_ConnectionId_v IS NOT NULL)
               OR (@S_ConnectionId_comparator = 11 AND @S_ConnectionId_v1 IS NOT NULL AND @S_ConnectionId_v2 IS NOT NULL)
               OR (@S_ConnectionId_comparator = 12 AND @S_ConnectionId_v1 IS NOT NULL AND @S_ConnectionId_v2 IS NOT NULL)
               OR (@S_ConnectionId_comparator = 13)
               OR (@S_ConnectionId_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_ConnectionId_comparator
        WHEN 1 THEN N'COALESCE([D].[ConnectionId], [O].[ConnectionId]) < @ConnectionId'
        WHEN 2 THEN N'COALESCE([D].[ConnectionId], [O].[ConnectionId]) <= @ConnectionId'
        WHEN 3 THEN N'COALESCE([D].[ConnectionId], [O].[ConnectionId]) = @ConnectionId'
        WHEN 4 THEN N'COALESCE([D].[ConnectionId], [O].[ConnectionId]) <> @ConnectionId'
        WHEN 5 THEN N'COALESCE([D].[ConnectionId], [O].[ConnectionId]) >= @ConnectionId'
        WHEN 6 THEN N'COALESCE([D].[ConnectionId], [O].[ConnectionId]) > @ConnectionId'
        WHEN 7 THEN N'COALESCE([D].[ConnectionId], [O].[ConnectionId]) IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@ConnectionId_vals))'
        WHEN 8 THEN N'COALESCE([D].[ConnectionId], [O].[ConnectionId]) NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@ConnectionId_vals))'
        WHEN 9 THEN N'COALESCE([D].[ConnectionId], [O].[ConnectionId]) LIKE @ConnectionId'
        WHEN 10 THEN N'COALESCE([D].[ConnectionId], [O].[ConnectionId]) NOT LIKE @ConnectionId'
        WHEN 11 THEN N'COALESCE([D].[ConnectionId], [O].[ConnectionId]) BETWEEN @ConnectionId_v1 AND @ConnectionId_v2'
        WHEN 12 THEN N'COALESCE([D].[ConnectionId], [O].[ConnectionId]) NOT BETWEEN @ConnectionId_v1 AND @ConnectionId_v2'
        WHEN 13 THEN N'COALESCE([D].[ConnectionId], [O].[ConnectionId]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[ConnectionId], [O].[ConnectionId]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'Name' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[Name], [O].[Name]) IS NULL'
                END ELSE
                IF @S_Name_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_Name_comparator = 1 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 2 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 3 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 4 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 5 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 6 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 7 AND @S_Name_vals IS NOT NULL)
               OR (@S_Name_comparator = 8 AND @S_Name_vals IS NOT NULL)
               OR (@S_Name_comparator = 9 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 10 AND @S_Name_v IS NOT NULL)
               OR (@S_Name_comparator = 11 AND @S_Name_v1 IS NOT NULL AND @S_Name_v2 IS NOT NULL)
               OR (@S_Name_comparator = 12 AND @S_Name_v1 IS NOT NULL AND @S_Name_v2 IS NOT NULL)
               OR (@S_Name_comparator = 13)
               OR (@S_Name_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_Name_comparator
        WHEN 1 THEN N'COALESCE([D].[Name], [O].[Name]) < @Name'
        WHEN 2 THEN N'COALESCE([D].[Name], [O].[Name]) <= @Name'
        WHEN 3 THEN N'COALESCE([D].[Name], [O].[Name]) = @Name'
        WHEN 4 THEN N'COALESCE([D].[Name], [O].[Name]) <> @Name'
        WHEN 5 THEN N'COALESCE([D].[Name], [O].[Name]) >= @Name'
        WHEN 6 THEN N'COALESCE([D].[Name], [O].[Name]) > @Name'
        WHEN 7 THEN N'COALESCE([D].[Name], [O].[Name]) IN (SELECT CAST([value] AS nvarchar(25)) FROM OPENJSON(@Name_vals))'
        WHEN 8 THEN N'COALESCE([D].[Name], [O].[Name]) NOT IN (SELECT CAST([value] AS nvarchar(25)) FROM OPENJSON(@Name_vals))'
        WHEN 9 THEN N'COALESCE([D].[Name], [O].[Name]) LIKE @Name'
        WHEN 10 THEN N'COALESCE([D].[Name], [O].[Name]) NOT LIKE @Name'
        WHEN 11 THEN N'COALESCE([D].[Name], [O].[Name]) BETWEEN @Name_v1 AND @Name_v2'
        WHEN 12 THEN N'COALESCE([D].[Name], [O].[Name]) NOT BETWEEN @Name_v1 AND @Name_v2'
        WHEN 13 THEN N'COALESCE([D].[Name], [O].[Name]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[Name], [O].[Name]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'Alias' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[Alias], [O].[Alias]) IS NULL'
                END ELSE
                IF @S_Alias_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_Alias_comparator = 1 AND @S_Alias_v IS NOT NULL)
               OR (@S_Alias_comparator = 2 AND @S_Alias_v IS NOT NULL)
               OR (@S_Alias_comparator = 3 AND @S_Alias_v IS NOT NULL)
               OR (@S_Alias_comparator = 4 AND @S_Alias_v IS NOT NULL)
               OR (@S_Alias_comparator = 5 AND @S_Alias_v IS NOT NULL)
               OR (@S_Alias_comparator = 6 AND @S_Alias_v IS NOT NULL)
               OR (@S_Alias_comparator = 7 AND @S_Alias_vals IS NOT NULL)
               OR (@S_Alias_comparator = 8 AND @S_Alias_vals IS NOT NULL)
               OR (@S_Alias_comparator = 9 AND @S_Alias_v IS NOT NULL)
               OR (@S_Alias_comparator = 10 AND @S_Alias_v IS NOT NULL)
               OR (@S_Alias_comparator = 11 AND @S_Alias_v1 IS NOT NULL AND @S_Alias_v2 IS NOT NULL)
               OR (@S_Alias_comparator = 12 AND @S_Alias_v1 IS NOT NULL AND @S_Alias_v2 IS NOT NULL)
               OR (@S_Alias_comparator = 13)
               OR (@S_Alias_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_Alias_comparator
        WHEN 1 THEN N'COALESCE([D].[Alias], [O].[Alias]) < @Alias'
        WHEN 2 THEN N'COALESCE([D].[Alias], [O].[Alias]) <= @Alias'
        WHEN 3 THEN N'COALESCE([D].[Alias], [O].[Alias]) = @Alias'
        WHEN 4 THEN N'COALESCE([D].[Alias], [O].[Alias]) <> @Alias'
        WHEN 5 THEN N'COALESCE([D].[Alias], [O].[Alias]) >= @Alias'
        WHEN 6 THEN N'COALESCE([D].[Alias], [O].[Alias]) > @Alias'
        WHEN 7 THEN N'COALESCE([D].[Alias], [O].[Alias]) IN (SELECT CAST([value] AS nvarchar(25)) FROM OPENJSON(@Alias_vals))'
        WHEN 8 THEN N'COALESCE([D].[Alias], [O].[Alias]) NOT IN (SELECT CAST([value] AS nvarchar(25)) FROM OPENJSON(@Alias_vals))'
        WHEN 9 THEN N'COALESCE([D].[Alias], [O].[Alias]) LIKE @Alias'
        WHEN 10 THEN N'COALESCE([D].[Alias], [O].[Alias]) NOT LIKE @Alias'
        WHEN 11 THEN N'COALESCE([D].[Alias], [O].[Alias]) BETWEEN @Alias_v1 AND @Alias_v2'
        WHEN 12 THEN N'COALESCE([D].[Alias], [O].[Alias]) NOT BETWEEN @Alias_v1 AND @Alias_v2'
        WHEN 13 THEN N'COALESCE([D].[Alias], [O].[Alias]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[Alias], [O].[Alias]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[Databases] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@ConnectionId bigint,@ConnectionId_v1 bigint,@ConnectionId_v2 bigint,@ConnectionId_vals NVARCHAR(MAX),@Name nvarchar(25),@Name_v1 nvarchar(25),@Name_v2 nvarchar(25),@Name_vals NVARCHAR(MAX),@Alias nvarchar(25),@Alias_v1 nvarchar(25),@Alias_v2 nvarchar(25),@Alias_vals NVARCHAR(MAX), @r BIGINT OUTPUT'
                                       ,@Id = @S_Id_v
                                       ,@Id_v1 = @S_Id_v1
                                       ,@Id_v2 = @S_Id_v2
                                       ,@Id_vals = @S_Id_vals
                                       ,@ConnectionId = @S_ConnectionId_v
                                       ,@ConnectionId_v1 = @S_ConnectionId_v1
                                       ,@ConnectionId_v2 = @S_ConnectionId_v2
                                       ,@ConnectionId_vals = @S_ConnectionId_vals
                                       ,@Name = @S_Name_v
                                       ,@Name_v1 = @S_Name_v1
                                       ,@Name_v2 = @S_Name_v2
                                       ,@Name_vals = @S_Name_vals
                                       ,@Alias = @S_Alias_v
                                       ,@Alias_v1 = @S_Alias_v1
                                       ,@Alias_v2 = @S_Alias_v2
                                       ,@Alias_vals = @S_Alias_vals
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS bigint) AS [ConnectionId]
                    ,CAST(NULL AS nvarchar(25)) AS [Name]
                    ,CAST(NULL AS nvarchar(25)) AS [Alias]
                    ,CAST(NULL AS nvarchar(50)) AS [Description]
                    ,CAST(NULL AS nvarchar(256)) AS [Folder]
                    ,CAST(NULL AS bit) AS [IsLegacy]
                    ,CAST(NULL AS bigint) AS [CurrentOperationId]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''Database'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[ConnectionId]
                              ,[T].[Name]
                              ,[T].[Alias]
                              ,[T].[Description]
                              ,[T].[Folder]
                              ,[T].[IsLegacy]
                              ,[T].[CurrentOperationId]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Databases] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Database'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[ConnectionId]
                                  ,[O].[Name]
                                  ,[O].[Alias]
                                  ,[O].[Description]
                                  ,[O].[Folder]
                                  ,[O].[IsLegacy]
                                  ,[O].[CurrentOperationId]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'Connection' AS [Kind]
              ,[R].[Id]
              ,[R].[Environment]
              ,[R].[ConnectionString]
            INTO [#Connections]
            FROM [#result] [T]
                INNER JOIN [dbo].[Connections] [R] ON [R].[Id] = [T].[ConnectionId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Connections] ON [#Connections]([Id])
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[ConnectionId]
                      ,[Name]
                      ,[Name] AS [ListItemValue]
                      ,[Alias]
                      ,[Description]
                      ,[Folder]
                      ,[IsLegacy]
                      ,[CurrentOperationId]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [Connection].* FROM [#Connections] AS [Connection] FOR JSON PATH), '[]') AS [Connection]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[SystemDatabaseValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemDatabaseValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemDatabaseValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SystemDatabaseValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id bigint

        IF @Action = 'delete' BEGIN
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

        END ELSE BEGIN
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        END
        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS bigint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[SystemsDatabases] WHERE [Id] = @W_Id) AND @Action = 'create'
            THROW 51000, 'Chave-primária já existe em SystemsDatabases', 1
        ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'SystemsDatabases'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND                                           CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create' AND NOT EXISTS(SELECT 1 FROM [dbo].[SystemsDatabases] WHERE [Id] = @W_Id)
            THROW 51000, 'Chave-primária não existe em SystemsDatabases', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[SystemsDatabases]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [SystemId] = JSON_VALUE(@LastRecord, '$.SystemId')
                                  AND [DatabaseId] = JSON_VALUE(@LastRecord, '$.DatabaseId')
                                  AND [Name] = JSON_VALUE(@LastRecord, '$.Name'))
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'SystemsDatabases'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.SystemId') = JSON_VALUE(@LastRecord, '$.SystemId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.DatabaseId') = JSON_VALUE(@LastRecord, '$.DatabaseId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') = JSON_VALUE(@LastRecord, '$.Name'))
                THROW 51000, 'Registro de SystemsDatabases alterado por outro usuário', 1
        END

        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_SystemId bigint = CAST(JSON_VALUE(@ActualRecord, '$.SystemId') AS bigint)
                   ,@W_DatabaseId bigint = CAST(JSON_VALUE(@ActualRecord, '$.DatabaseId') AS bigint)
                   ,@W_Name nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(50))

            IF @W_SystemId IS NULL
                THROW 51000, 'Valor de SystemId em @ActualRecord é requerido.', 1
            IF @W_SystemId < CAST('1' AS bigint)
                THROW 51000, 'Valor de SystemId em @ActualRecord deve ser maior que ou igual a 1', 1
            IF @W_DatabaseId IS NULL
                THROW 51000, 'Valor de DatabaseId em @ActualRecord é requerido.', 1
            IF @W_DatabaseId < CAST('1' AS bigint)
                THROW 51000, 'Valor de DatabaseId em @ActualRecord deve ser maior que ou igual a 1', 1
            IF @W_Name IS NULL
                THROW 51000, 'Valor de Name em @ActualRecord é requerido.', 1
            IF (@W_SystemId IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM [dbo].[Systems] WHERE [Id] = @W_SystemId)
                THROW 51000, 'Valor de FK em @ActualRecord inexiste em Systems', 1
            IF (@W_DatabaseId IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM [dbo].[Databases] WHERE [Id] = @W_DatabaseId)
                THROW 51000, 'Valor de FK em @ActualRecord inexiste em Databases', 1
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[SystemDatabasePersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemDatabasePersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemDatabasePersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SystemDatabasePersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
               ,@W_Id bigint

    IF @Action = 'delete' BEGIN
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

    END ELSE BEGIN
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    END
    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'SystemsDatabases'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'SystemsDatabases', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[SystemDatabaseValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'SystemsDatabases'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            SET IDENTITY_INSERT [dbo].[Operations] ON
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'SystemsDatabases'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
            SET IDENTITY_INSERT [dbo].[Operations] OFF
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create'
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[SystemDatabaseValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @ActionAux = 'create'
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[SystemDatabaseCreate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemDatabaseCreate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemDatabaseCreate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SystemDatabaseCreate](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'SystemsDatabases'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'create'
            THROW 51000, 'Ação da operação é inválida para Create', 1
        EXEC @TransactionIdAux = [dbo].[SystemDatabaseValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id bigint = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        DECLARE @W_SystemId bigint = CAST(JSON_VALUE(@ActualRecord, '$.SystemId') AS bigint)
               ,@W_DatabaseId bigint = CAST(JSON_VALUE(@ActualRecord, '$.DatabaseId') AS bigint)
               ,@W_Name nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(50))

        SET IDENTITY_INSERT [dbo].[SystemsDatabases] ON
        INSERT INTO [dbo].[SystemsDatabases] ([Id]
                                            ,[SystemId]
                                            ,[DatabaseId]
                                            ,[Name]
                                            ,[CreatedAt]
                                            ,[CreatedBy])
                                      VALUES (@W_Id
                                             ,@W_SystemId
                                             ,@W_DatabaseId
                                             ,@W_Name
                                             ,GETDATE()
                                             ,@UserName)
        SET IDENTITY_INSERT [dbo].[SystemsDatabases] OFF
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

