/**********************************************************************************
Criar stored procedure [dbo].[SystemsDatabasesRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SystemsDatabasesRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SystemsDatabasesRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SystemsDatabasesRead](@Login NVARCHAR(MAX)
                                          ,@Filter NVARCHAR(MAX)
                                          ,@Search NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

        IF @Filter IS NULL
            SET @Filter = '{}'
        ELSE IF ISJSON(@Filter) = 0
            THROW 51000, 'Valor de @Filter não está no formato JSON', 1
        IF @Search IS NULL
            SET @Search = '{}'
        ELSE IF ISJSON(@Search) = 0
            THROW 51000, 'Valor de @Search não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'SystemsDatabases') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END
        IF @IsActionList = 1
            SET @OrderBy = '[T].[Name] ASC, [T].[Id] ASC'
        DECLARE @PickerValue nvarchar(50) = NULL

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @SessionId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.SystemId') AS bigint) AS [SystemId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.DatabaseId') AS bigint) AS [DatabaseId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') AS nvarchar(50)) AS [Name]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'SystemsDatabases'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@Filter, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@ComparatorPredicate NVARCHAR(MAX)
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id bigint = CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)
               ,@WT_SystemId bigint = CAST(JSON_VALUE(@Filter, '$.SystemId') AS bigint)
               ,@WT_DatabaseId bigint = CAST(JSON_VALUE(@Filter, '$.DatabaseId') AS bigint)
               ,@WT_Name nvarchar(50) = CAST(JSON_VALUE(@Filter, '$.Name') AS nvarchar(50))

        IF @WT_Id IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Id] = @T_Id'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'SystemId' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[SystemId] IS NULL'
        ELSE IF @WT_SystemId IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[SystemId] = @T_SystemId'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'DatabaseId' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[DatabaseId] IS NULL'
        ELSE IF @WT_DatabaseId IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[DatabaseId] = @T_DatabaseId'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'Name' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Name] IS NULL'
        ELSE IF @WT_Name IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Name] = @T_Name'
        END
        IF @IsActionList = 1 BEGIN
            SET @PickerValue = CAST(JSON_VALUE(@Filter, '$.Picker.Value') AS nvarchar(50))
            IF @PickerValue IS NULL
                SET @PickerValue = ''
            SET @Where = @Where + ' AND [T].[Name] LIKE ''%'' + @PickerValue + ''%'''
        END ELSE IF @_ IS NULL BEGIN
            DECLARE @G_Id_comparator TINYINT
                   ,@G_Id_v bigint
                   ,@G_Id_vals NVARCHAR(MAX)
                   ,@G_Id_v1 bigint
                   ,@G_Id_v2 bigint
                   ,@G_SystemId_comparator TINYINT
                   ,@G_SystemId_v bigint
                   ,@G_SystemId_vals NVARCHAR(MAX)
                   ,@G_SystemId_v1 bigint
                   ,@G_SystemId_v2 bigint
                   ,@G_DatabaseId_comparator TINYINT
                   ,@G_DatabaseId_v bigint
                   ,@G_DatabaseId_vals NVARCHAR(MAX)
                   ,@G_DatabaseId_v1 bigint
                   ,@G_DatabaseId_v2 bigint
                   ,@G_Name_comparator TINYINT
                   ,@G_Name_v nvarchar(50)
                   ,@G_Name_vals NVARCHAR(MAX)
                   ,@G_Name_v1 nvarchar(50)
                   ,@G_Name_v2 nvarchar(50)

            SELECT @G_Id_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Id') IS NOT NULL AND JSON_QUERY(@Filter, '$.Id') IS NULL THEN 3 END
            )
                  ,@G_Id_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.value') AS bigint),
                TRY_CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)
            )
                  ,@G_Id_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Id.value'),
                JSON_QUERY(@Filter, '$.Id')
            )
            SELECT @G_Id_v1 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[0]') AS bigint)
                  ,@G_Id_v2 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[1]') AS bigint)
            SELECT @G_SystemId_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.SystemId.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.SystemId') IS NOT NULL AND JSON_QUERY(@Filter, '$.SystemId') IS NULL THEN 3 END
            )
                  ,@G_SystemId_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.SystemId.value') AS bigint),
                TRY_CAST(JSON_VALUE(@Filter, '$.SystemId') AS bigint)
            )
                  ,@G_SystemId_vals = COALESCE(
                JSON_QUERY(@Filter, '$.SystemId.value'),
                JSON_QUERY(@Filter, '$.SystemId')
            )
            SELECT @G_SystemId_v1 = TRY_CAST(JSON_VALUE(@G_SystemId_vals, '$[0]') AS bigint)
                  ,@G_SystemId_v2 = TRY_CAST(JSON_VALUE(@G_SystemId_vals, '$[1]') AS bigint)
            SELECT @G_DatabaseId_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.DatabaseId.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.DatabaseId') IS NOT NULL AND JSON_QUERY(@Filter, '$.DatabaseId') IS NULL THEN 3 END
            )
                  ,@G_DatabaseId_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.DatabaseId.value') AS bigint),
                TRY_CAST(JSON_VALUE(@Filter, '$.DatabaseId') AS bigint)
            )
                  ,@G_DatabaseId_vals = COALESCE(
                JSON_QUERY(@Filter, '$.DatabaseId.value'),
                JSON_QUERY(@Filter, '$.DatabaseId')
            )
            SELECT @G_DatabaseId_v1 = TRY_CAST(JSON_VALUE(@G_DatabaseId_vals, '$[0]') AS bigint)
                  ,@G_DatabaseId_v2 = TRY_CAST(JSON_VALUE(@G_DatabaseId_vals, '$[1]') AS bigint)
            SELECT @G_Name_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Name.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Name') IS NOT NULL AND JSON_QUERY(@Filter, '$.Name') IS NULL THEN 3 END
            )
                  ,@G_Name_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Name.value') AS nvarchar(50)),
                TRY_CAST(JSON_VALUE(@Filter, '$.Name') AS nvarchar(50))
            )
                  ,@G_Name_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Name.value'),
                JSON_QUERY(@Filter, '$.Name')
            )
            SELECT @G_Name_v1 = TRY_CAST(JSON_VALUE(@G_Name_vals, '$[0]') AS nvarchar(50))
                  ,@G_Name_v2 = TRY_CAST(JSON_VALUE(@G_Name_vals, '$[1]') AS nvarchar(50))

            IF @G_Id_comparator IS NOT NULL BEGIN
                IF (@G_Id_comparator = 1 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 2 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 3 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 4 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 5 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 6 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 7 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 8 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 9 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 10 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 11 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 12 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 13)
               OR (@G_Id_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_Id_comparator
        WHEN 1 THEN N'[T].[Id] < @Id'
        WHEN 2 THEN N'[T].[Id] <= @Id'
        WHEN 3 THEN N'[T].[Id] = @Id'
        WHEN 4 THEN N'[T].[Id] <> @Id'
        WHEN 5 THEN N'[T].[Id] >= @Id'
        WHEN 6 THEN N'[T].[Id] > @Id'
        WHEN 7 THEN N'[T].[Id] IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 8 THEN N'[T].[Id] NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 9 THEN N'[T].[Id] LIKE @Id'
        WHEN 10 THEN N'[T].[Id] NOT LIKE @Id'
        WHEN 11 THEN N'[T].[Id] BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'[T].[Id] NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'[T].[Id] IS NULL'
        WHEN 14 THEN N'[T].[Id] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'SystemId' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[SystemId] IS NULL'
            ELSE
            IF @G_SystemId_comparator IS NOT NULL BEGIN
                IF (@G_SystemId_comparator = 1 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 2 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 3 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 4 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 5 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 6 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 7 AND @G_SystemId_vals IS NOT NULL)
               OR (@G_SystemId_comparator = 8 AND @G_SystemId_vals IS NOT NULL)
               OR (@G_SystemId_comparator = 9 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 10 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 11 AND @G_SystemId_v1 IS NOT NULL AND @G_SystemId_v2 IS NOT NULL)
               OR (@G_SystemId_comparator = 12 AND @G_SystemId_v1 IS NOT NULL AND @G_SystemId_v2 IS NOT NULL)
               OR (@G_SystemId_comparator = 13)
               OR (@G_SystemId_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_SystemId_comparator
        WHEN 1 THEN N'[T].[SystemId] < @SystemId'
        WHEN 2 THEN N'[T].[SystemId] <= @SystemId'
        WHEN 3 THEN N'[T].[SystemId] = @SystemId'
        WHEN 4 THEN N'[T].[SystemId] <> @SystemId'
        WHEN 5 THEN N'[T].[SystemId] >= @SystemId'
        WHEN 6 THEN N'[T].[SystemId] > @SystemId'
        WHEN 7 THEN N'[T].[SystemId] IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@SystemId_vals))'
        WHEN 8 THEN N'[T].[SystemId] NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@SystemId_vals))'
        WHEN 9 THEN N'[T].[SystemId] LIKE @SystemId'
        WHEN 10 THEN N'[T].[SystemId] NOT LIKE @SystemId'
        WHEN 11 THEN N'[T].[SystemId] BETWEEN @SystemId_v1 AND @SystemId_v2'
