/**********************************************************************************
Criar stored procedure [dbo].[ColumnsRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[ColumnsRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[ColumnsRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[ColumnsRead](@Login NVARCHAR(MAX)
                                          ,@Filter NVARCHAR(MAX)
                                          ,@Search NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

        IF @Filter IS NULL
            SET @Filter = '{}'
        ELSE IF ISJSON(@Filter) = 0
            THROW 51000, 'Valor de @Filter não está no formato JSON', 1
        IF @Search IS NULL
            SET @Search = '{}'
        ELSE IF ISJSON(@Search) = 0
            THROW 51000, 'Valor de @Search não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Columns') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @SessionId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.TableId') AS bigint) AS [TableId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Sequence') AS smallint) AS [Sequence]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.DomainId') AS bigint) AS [DomainId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name') AS nvarchar(25)) AS [Name]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Alias') AS nvarchar(25)) AS [Alias]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Description') AS nvarchar(50)) AS [Description]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Title') AS nvarchar(25)) AS [Title]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Caption') AS nvarchar(25)) AS [Caption]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Default') AS nvarchar(max)) AS [Default]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Minimum') AS nvarchar(max)) AS [Minimum]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Maximum') AS nvarchar(max)) AS [Maximum]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsPrimarykey') AS bit) AS [IsPrimarykey]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsAutoIncrement') AS bit) AS [IsAutoIncrement]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsRequired') AS bit) AS [IsRequired]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsListable') AS bit) AS [IsListable]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsFilterable') AS bit) AS [IsFilterable]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsEditable') AS bit) AS [IsEditable]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsGridable') AS bit) AS [IsGridable]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsEncrypted') AS bit) AS [IsEncrypted]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsInWords') AS bit) AS [IsInWords]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsVirtual') AS bit) AS [IsVirtual]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Columns'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@Filter, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@ComparatorPredicate NVARCHAR(MAX)
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id bigint = CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)
               ,@WT_TableId bigint = CAST(JSON_VALUE(@Filter, '$.TableId') AS bigint)
               ,@WT_DomainId bigint = CAST(JSON_VALUE(@Filter, '$.DomainId') AS bigint)
               ,@WT_Name nvarchar(25) = CAST(JSON_VALUE(@Filter, '$.Name') AS nvarchar(25))
               ,@WT_Alias nvarchar(25) = CAST(JSON_VALUE(@Filter, '$.Alias') AS nvarchar(25))
               ,@WT_IsAutoIncrement bit = CAST(JSON_VALUE(@Filter, '$.IsAutoIncrement') AS bit)
               ,@WT_IsRequired bit = CAST(JSON_VALUE(@Filter, '$.IsRequired') AS bit)
               ,@WT_IsListable bit = CAST(JSON_VALUE(@Filter, '$.IsListable') AS bit)
               ,@WT_IsFilterable bit = CAST(JSON_VALUE(@Filter, '$.IsFilterable') AS bit)
               ,@WT_IsEditable bit = CAST(JSON_VALUE(@Filter, '$.IsEditable') AS bit)
               ,@WT_IsGridable bit = CAST(JSON_VALUE(@Filter, '$.IsGridable') AS bit)
               ,@WT_IsEncrypted bit = CAST(JSON_VALUE(@Filter, '$.IsEncrypted') AS bit)
               ,@WT_IsInWords bit = CAST(JSON_VALUE(@Filter, '$.IsInWords') AS bit)
               ,@WT_IsVirtual bit = CAST(JSON_VALUE(@Filter, '$.IsVirtual') AS bit)

        IF @WT_Id IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Id] = @T_Id'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'TableId' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[TableId] IS NULL'
        ELSE IF @WT_TableId IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[TableId] = @T_TableId'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'DomainId' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[DomainId] IS NULL'
        ELSE IF @WT_DomainId IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[DomainId] = @T_DomainId'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'Name' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Name] IS NULL'
        ELSE IF @WT_Name IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Name] = @T_Name'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'Alias' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Alias] IS NULL'
        ELSE IF @WT_Alias IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Alias] = @T_Alias'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'IsAutoIncrement' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[IsAutoIncrement] IS NULL'
        ELSE IF @WT_IsAutoIncrement IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[IsAutoIncrement] = @T_IsAutoIncrement'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'IsRequired' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[IsRequired] IS NULL'
        ELSE IF @WT_IsRequired IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[IsRequired] = @T_IsRequired'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'IsListable' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[IsListable] IS NULL'
        ELSE IF @WT_IsListable IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[IsListable] = @T_IsListable'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'IsFilterable' AND [type] = 0)
