               OR (@G_IsInWords_comparator = 4 AND @G_IsInWords_v IS NOT NULL)
               OR (@G_IsInWords_comparator = 5 AND @G_IsInWords_v IS NOT NULL)
               OR (@G_IsInWords_comparator = 6 AND @G_IsInWords_v IS NOT NULL)
               OR (@G_IsInWords_comparator = 7 AND @G_IsInWords_vals IS NOT NULL)
               OR (@G_IsInWords_comparator = 8 AND @G_IsInWords_vals IS NOT NULL)
               OR (@G_IsInWords_comparator = 9 AND @G_IsInWords_v IS NOT NULL)
               OR (@G_IsInWords_comparator = 10 AND @G_IsInWords_v IS NOT NULL)
               OR (@G_IsInWords_comparator = 11 AND @G_IsInWords_v1 IS NOT NULL AND @G_IsInWords_v2 IS NOT NULL)
               OR (@G_IsInWords_comparator = 12 AND @G_IsInWords_v1 IS NOT NULL AND @G_IsInWords_v2 IS NOT NULL)
               OR (@G_IsInWords_comparator = 13)
               OR (@G_IsInWords_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_IsInWords_comparator
        WHEN 1 THEN N'[T].[IsInWords] < @IsInWords'
        WHEN 2 THEN N'[T].[IsInWords] <= @IsInWords'
        WHEN 3 THEN N'[T].[IsInWords] = @IsInWords'
        WHEN 4 THEN N'[T].[IsInWords] <> @IsInWords'
        WHEN 5 THEN N'[T].[IsInWords] >= @IsInWords'
        WHEN 6 THEN N'[T].[IsInWords] > @IsInWords'
        WHEN 7 THEN N'[T].[IsInWords] IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsInWords_vals))'
        WHEN 8 THEN N'[T].[IsInWords] NOT IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsInWords_vals))'
        WHEN 9 THEN N'[T].[IsInWords] LIKE @IsInWords'
        WHEN 10 THEN N'[T].[IsInWords] NOT LIKE @IsInWords'
        WHEN 11 THEN N'[T].[IsInWords] BETWEEN @IsInWords_v1 AND @IsInWords_v2'
        WHEN 12 THEN N'[T].[IsInWords] NOT BETWEEN @IsInWords_v1 AND @IsInWords_v2'
        WHEN 13 THEN N'[T].[IsInWords] IS NULL'
        WHEN 14 THEN N'[T].[IsInWords] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'IsVirtual' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[IsVirtual] IS NULL'
            ELSE
            IF @G_IsVirtual_comparator IS NOT NULL BEGIN
                IF (@G_IsVirtual_comparator = 1 AND @G_IsVirtual_v IS NOT NULL)
               OR (@G_IsVirtual_comparator = 2 AND @G_IsVirtual_v IS NOT NULL)
               OR (@G_IsVirtual_comparator = 3 AND @G_IsVirtual_v IS NOT NULL)
               OR (@G_IsVirtual_comparator = 4 AND @G_IsVirtual_v IS NOT NULL)
               OR (@G_IsVirtual_comparator = 5 AND @G_IsVirtual_v IS NOT NULL)
               OR (@G_IsVirtual_comparator = 6 AND @G_IsVirtual_v IS NOT NULL)
               OR (@G_IsVirtual_comparator = 7 AND @G_IsVirtual_vals IS NOT NULL)
               OR (@G_IsVirtual_comparator = 8 AND @G_IsVirtual_vals IS NOT NULL)
               OR (@G_IsVirtual_comparator = 9 AND @G_IsVirtual_v IS NOT NULL)
               OR (@G_IsVirtual_comparator = 10 AND @G_IsVirtual_v IS NOT NULL)
               OR (@G_IsVirtual_comparator = 11 AND @G_IsVirtual_v1 IS NOT NULL AND @G_IsVirtual_v2 IS NOT NULL)
               OR (@G_IsVirtual_comparator = 12 AND @G_IsVirtual_v1 IS NOT NULL AND @G_IsVirtual_v2 IS NOT NULL)
               OR (@G_IsVirtual_comparator = 13)
               OR (@G_IsVirtual_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_IsVirtual_comparator
        WHEN 1 THEN N'[T].[IsVirtual] < @IsVirtual'
        WHEN 2 THEN N'[T].[IsVirtual] <= @IsVirtual'
        WHEN 3 THEN N'[T].[IsVirtual] = @IsVirtual'
        WHEN 4 THEN N'[T].[IsVirtual] <> @IsVirtual'
        WHEN 5 THEN N'[T].[IsVirtual] >= @IsVirtual'
        WHEN 6 THEN N'[T].[IsVirtual] > @IsVirtual'
        WHEN 7 THEN N'[T].[IsVirtual] IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsVirtual_vals))'
        WHEN 8 THEN N'[T].[IsVirtual] NOT IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsVirtual_vals))'
        WHEN 9 THEN N'[T].[IsVirtual] LIKE @IsVirtual'
        WHEN 10 THEN N'[T].[IsVirtual] NOT LIKE @IsVirtual'
        WHEN 11 THEN N'[T].[IsVirtual] BETWEEN @IsVirtual_v1 AND @IsVirtual_v2'
        WHEN 12 THEN N'[T].[IsVirtual] NOT BETWEEN @IsVirtual_v1 AND @IsVirtual_v2'
        WHEN 13 THEN N'[T].[IsVirtual] IS NULL'
        WHEN 14 THEN N'[T].[IsVirtual] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
        END ELSE
            SET @Where = @Where + ' AND [T].[Id] IN (' + @_ + ')'

        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] bigint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[U].[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                              ,[T].[Id]
                                    FROM [dbo].[Columns] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [T].[Id] = [#].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                              ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @_ IS NULL BEGIN
