        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] bigint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[U].[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                              ,[T].[Id]
                                    FROM [dbo].[Indexes] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [T].[Id] = [#].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                              ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @IsActionList = 1 BEGIN
            EXEC sp_executesql @sql
                               ,N'@PickerValue nvarchar(50),@T_Id bigint,@T_TableId bigint,@T_Name nvarchar(50),@T_IsUnique bit'
                               ,@PickerValue = @PickerValue
                               ,@T_Id = @WT_Id
                               ,@T_TableId = @WT_TableId
                               ,@T_Name = @WT_Name
                               ,@T_IsUnique = @WT_IsUnique
        END ELSE IF @_ IS NULL BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_TableId bigint,@T_Name nvarchar(50),@T_IsUnique bit,@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@TableId bigint,@TableId_v1 bigint,@TableId_v2 bigint,@TableId_vals NVARCHAR(MAX),@Name nvarchar(50),@Name_v1 nvarchar(50),@Name_v2 nvarchar(50),@Name_vals NVARCHAR(MAX),@IsUnique bit,@IsUnique_v1 bit,@IsUnique_v2 bit,@IsUnique_vals NVARCHAR(MAX)'
                               ,@T_Id = @WT_Id
                               ,@T_TableId = @WT_TableId
                               ,@T_Name = @WT_Name
                               ,@T_IsUnique = @WT_IsUnique
                               ,@Id = @G_Id_v
                               ,@Id_v1 = @G_Id_v1
                               ,@Id_v2 = @G_Id_v2
                               ,@Id_vals = @G_Id_vals
                               ,@TableId = @G_TableId_v
                               ,@TableId_v1 = @G_TableId_v1
                               ,@TableId_v2 = @G_TableId_v2
                               ,@TableId_vals = @G_TableId_vals
                               ,@Name = @G_Name_v
                               ,@Name_v1 = @G_Name_v1
                               ,@Name_v2 = @G_Name_v2
                               ,@Name_vals = @G_Name_vals
                               ,@IsUnique = @G_IsUnique_v
                               ,@IsUnique_v1 = @G_IsUnique_v1
                               ,@IsUnique_v2 = @G_IsUnique_v2
                               ,@IsUnique_vals = @G_IsUnique_vals
        END ELSE BEGIN
