                                          ,@Filter NVARCHAR(MAX)
                                          ,@Search NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

        IF @Filter IS NULL
            SET @Filter = '{}'
        ELSE IF ISJSON(@Filter) = 0
            THROW 51000, 'Valor de @Filter não está no formato JSON', 1
        IF @Search IS NULL
            SET @Search = '{}'
        ELSE IF ISJSON(@Search) = 0
            THROW 51000, 'Valor de @Search não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Indexkeys') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @SessionId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IndexId') AS bigint) AS [IndexId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Sequence') AS smallint) AS [Sequence]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ColumnId') AS bigint) AS [ColumnId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsDescending') AS bit) AS [IsDescending]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Indexkeys'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@Filter, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@ComparatorPredicate NVARCHAR(MAX)
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id bigint = CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)
               ,@WT_IndexId bigint = CAST(JSON_VALUE(@Filter, '$.IndexId') AS bigint)
               ,@WT_ColumnId bigint = CAST(JSON_VALUE(@Filter, '$.ColumnId') AS bigint)
               ,@WT_IsDescending bit = CAST(JSON_VALUE(@Filter, '$.IsDescending') AS bit)

        IF @WT_Id IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Id] = @T_Id'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'IndexId' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[IndexId] IS NULL'
        ELSE IF @WT_IndexId IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[IndexId] = @T_IndexId'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'ColumnId' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[ColumnId] IS NULL'
        ELSE IF @WT_ColumnId IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[ColumnId] = @T_ColumnId'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'IsDescending' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[IsDescending] IS NULL'
        ELSE IF @WT_IsDescending IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[IsDescending] = @T_IsDescending'
        END
        IF @_ IS NULL BEGIN
            DECLARE @G_Id_comparator TINYINT
                   ,@G_Id_v bigint
                   ,@G_Id_vals NVARCHAR(MAX)
                   ,@G_Id_v1 bigint
                   ,@G_Id_v2 bigint
                   ,@G_IndexId_comparator TINYINT
                   ,@G_IndexId_v bigint
                   ,@G_IndexId_vals NVARCHAR(MAX)
                   ,@G_IndexId_v1 bigint
                   ,@G_IndexId_v2 bigint
                   ,@G_ColumnId_comparator TINYINT
                   ,@G_ColumnId_v bigint
                   ,@G_ColumnId_vals NVARCHAR(MAX)
                   ,@G_ColumnId_v1 bigint
                   ,@G_ColumnId_v2 bigint
                   ,@G_IsDescending_comparator TINYINT
                   ,@G_IsDescending_v bit
                   ,@G_IsDescending_vals NVARCHAR(MAX)
                   ,@G_IsDescending_v1 bit
                   ,@G_IsDescending_v2 bit

            SELECT @G_Id_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Id') IS NOT NULL AND JSON_QUERY(@Filter, '$.Id') IS NULL THEN 3 END
            )
                  ,@G_Id_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.value') AS bigint),
                TRY_CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)
            )
                  ,@G_Id_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Id.value'),
                JSON_QUERY(@Filter, '$.Id')
            )
            SELECT @G_Id_v1 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[0]') AS bigint)
                  ,@G_Id_v2 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[1]') AS bigint)
            SELECT @G_IndexId_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.IndexId.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.IndexId') IS NOT NULL AND JSON_QUERY(@Filter, '$.IndexId') IS NULL THEN 3 END
            )
                  ,@G_IndexId_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.IndexId.value') AS bigint),
                TRY_CAST(JSON_VALUE(@Filter, '$.IndexId') AS bigint)
            )
                  ,@G_IndexId_vals = COALESCE(
                JSON_QUERY(@Filter, '$.IndexId.value'),
                JSON_QUERY(@Filter, '$.IndexId')
            )
            SELECT @G_IndexId_v1 = TRY_CAST(JSON_VALUE(@G_IndexId_vals, '$[0]') AS bigint)
                  ,@G_IndexId_v2 = TRY_CAST(JSON_VALUE(@G_IndexId_vals, '$[1]') AS bigint)
            SELECT @G_ColumnId_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.ColumnId.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.ColumnId') IS NOT NULL AND JSON_QUERY(@Filter, '$.ColumnId') IS NULL THEN 3 END
            )
                  ,@G_ColumnId_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.ColumnId.value') AS bigint),
                TRY_CAST(JSON_VALUE(@Filter, '$.ColumnId') AS bigint)
            )
                  ,@G_ColumnId_vals = COALESCE(
                JSON_QUERY(@Filter, '$.ColumnId.value'),
                JSON_QUERY(@Filter, '$.ColumnId')
            )
            SELECT @G_ColumnId_v1 = TRY_CAST(JSON_VALUE(@G_ColumnId_vals, '$[0]') AS bigint)
                  ,@G_ColumnId_v2 = TRY_CAST(JSON_VALUE(@G_ColumnId_vals, '$[1]') AS bigint)
            SELECT @G_IsDescending_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.IsDescending.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.IsDescending') IS NOT NULL AND JSON_QUERY(@Filter, '$.IsDescending') IS NULL THEN 3 END
            )
                  ,@G_IsDescending_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.IsDescending.value') AS bit),
                TRY_CAST(JSON_VALUE(@Filter, '$.IsDescending') AS bit)
            )
                  ,@G_IsDescending_vals = COALESCE(
                JSON_QUERY(@Filter, '$.IsDescending.value'),
                JSON_QUERY(@Filter, '$.IsDescending')
            )
            SELECT @G_IsDescending_v1 = TRY_CAST(JSON_VALUE(@G_IsDescending_vals, '$[0]') AS bit)
                  ,@G_IsDescending_v2 = TRY_CAST(JSON_VALUE(@G_IsDescending_vals, '$[1]') AS bit)

            IF @G_Id_comparator IS NOT NULL BEGIN
                IF (@G_Id_comparator = 1 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 2 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 3 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 4 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 5 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 6 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 7 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 8 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 9 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 10 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 11 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 12 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 13)
               OR (@G_Id_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_Id_comparator
        WHEN 1 THEN N'[T].[Id] < @Id'
        WHEN 2 THEN N'[T].[Id] <= @Id'
        WHEN 3 THEN N'[T].[Id] = @Id'
        WHEN 4 THEN N'[T].[Id] <> @Id'
        WHEN 5 THEN N'[T].[Id] >= @Id'
        WHEN 6 THEN N'[T].[Id] > @Id'
        WHEN 7 THEN N'[T].[Id] IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 8 THEN N'[T].[Id] NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 9 THEN N'[T].[Id] LIKE @Id'
        WHEN 10 THEN N'[T].[Id] NOT LIKE @Id'
        WHEN 11 THEN N'[T].[Id] BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'[T].[Id] NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'[T].[Id] IS NULL'
        WHEN 14 THEN N'[T].[Id] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'IndexId' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[IndexId] IS NULL'
            ELSE
            IF @G_IndexId_comparator IS NOT NULL BEGIN
                IF (@G_IndexId_comparator = 1 AND @G_IndexId_v IS NOT NULL)
               OR (@G_IndexId_comparator = 2 AND @G_IndexId_v IS NOT NULL)
               OR (@G_IndexId_comparator = 3 AND @G_IndexId_v IS NOT NULL)
               OR (@G_IndexId_comparator = 4 AND @G_IndexId_v IS NOT NULL)
               OR (@G_IndexId_comparator = 5 AND @G_IndexId_v IS NOT NULL)
               OR (@G_IndexId_comparator = 6 AND @G_IndexId_v IS NOT NULL)
               OR (@G_IndexId_comparator = 7 AND @G_IndexId_vals IS NOT NULL)
               OR (@G_IndexId_comparator = 8 AND @G_IndexId_vals IS NOT NULL)
               OR (@G_IndexId_comparator = 9 AND @G_IndexId_v IS NOT NULL)
               OR (@G_IndexId_comparator = 10 AND @G_IndexId_v IS NOT NULL)
               OR (@G_IndexId_comparator = 11 AND @G_IndexId_v1 IS NOT NULL AND @G_IndexId_v2 IS NOT NULL)
               OR (@G_IndexId_comparator = 12 AND @G_IndexId_v1 IS NOT NULL AND @G_IndexId_v2 IS NOT NULL)
               OR (@G_IndexId_comparator = 13)
               OR (@G_IndexId_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_IndexId_comparator
        WHEN 1 THEN N'[T].[IndexId] < @IndexId'
        WHEN 2 THEN N'[T].[IndexId] <= @IndexId'
        WHEN 3 THEN N'[T].[IndexId] = @IndexId'
        WHEN 4 THEN N'[T].[IndexId] <> @IndexId'
        WHEN 5 THEN N'[T].[IndexId] >= @IndexId'
        WHEN 6 THEN N'[T].[IndexId] > @IndexId'
        WHEN 7 THEN N'[T].[IndexId] IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@IndexId_vals))'
        WHEN 8 THEN N'[T].[IndexId] NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@IndexId_vals))'
        WHEN 9 THEN N'[T].[IndexId] LIKE @IndexId'
        WHEN 10 THEN N'[T].[IndexId] NOT LIKE @IndexId'
        WHEN 11 THEN N'[T].[IndexId] BETWEEN @IndexId_v1 AND @IndexId_v2'
        WHEN 12 THEN N'[T].[IndexId] NOT BETWEEN @IndexId_v1 AND @IndexId_v2'
        WHEN 13 THEN N'[T].[IndexId] IS NULL'
        WHEN 14 THEN N'[T].[IndexId] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'ColumnId' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[ColumnId] IS NULL'
            ELSE
            IF @G_ColumnId_comparator IS NOT NULL BEGIN
                IF (@G_ColumnId_comparator = 1 AND @G_ColumnId_v IS NOT NULL)
               OR (@G_ColumnId_comparator = 2 AND @G_ColumnId_v IS NOT NULL)
               OR (@G_ColumnId_comparator = 3 AND @G_ColumnId_v IS NOT NULL)
               OR (@G_ColumnId_comparator = 4 AND @G_ColumnId_v IS NOT NULL)
               OR (@G_ColumnId_comparator = 5 AND @G_ColumnId_v IS NOT NULL)
               OR (@G_ColumnId_comparator = 6 AND @G_ColumnId_v IS NOT NULL)
               OR (@G_ColumnId_comparator = 7 AND @G_ColumnId_vals IS NOT NULL)
               OR (@G_ColumnId_comparator = 8 AND @G_ColumnId_vals IS NOT NULL)
               OR (@G_ColumnId_comparator = 9 AND @G_ColumnId_v IS NOT NULL)
               OR (@G_ColumnId_comparator = 10 AND @G_ColumnId_v IS NOT NULL)
               OR (@G_ColumnId_comparator = 11 AND @G_ColumnId_v1 IS NOT NULL AND @G_ColumnId_v2 IS NOT NULL)
               OR (@G_ColumnId_comparator = 12 AND @G_ColumnId_v1 IS NOT NULL AND @G_ColumnId_v2 IS NOT NULL)
               OR (@G_ColumnId_comparator = 13)
               OR (@G_ColumnId_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_ColumnId_comparator
        WHEN 1 THEN N'[T].[ColumnId] < @ColumnId'
        WHEN 2 THEN N'[T].[ColumnId] <= @ColumnId'
        WHEN 3 THEN N'[T].[ColumnId] = @ColumnId'
        WHEN 4 THEN N'[T].[ColumnId] <> @ColumnId'
        WHEN 5 THEN N'[T].[ColumnId] >= @ColumnId'
        WHEN 6 THEN N'[T].[ColumnId] > @ColumnId'
        WHEN 7 THEN N'[T].[ColumnId] IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@ColumnId_vals))'
        WHEN 8 THEN N'[T].[ColumnId] NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@ColumnId_vals))'
        WHEN 9 THEN N'[T].[ColumnId] LIKE @ColumnId'
        WHEN 10 THEN N'[T].[ColumnId] NOT LIKE @ColumnId'
        WHEN 11 THEN N'[T].[ColumnId] BETWEEN @ColumnId_v1 AND @ColumnId_v2'
        WHEN 12 THEN N'[T].[ColumnId] NOT BETWEEN @ColumnId_v1 AND @ColumnId_v2'
        WHEN 13 THEN N'[T].[ColumnId] IS NULL'
        WHEN 14 THEN N'[T].[ColumnId] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'IsDescending' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[IsDescending] IS NULL'
            ELSE
            IF @G_IsDescending_comparator IS NOT NULL BEGIN
                IF (@G_IsDescending_comparator = 1 AND @G_IsDescending_v IS NOT NULL)
               OR (@G_IsDescending_comparator = 2 AND @G_IsDescending_v IS NOT NULL)
               OR (@G_IsDescending_comparator = 3 AND @G_IsDescending_v IS NOT NULL)
               OR (@G_IsDescending_comparator = 4 AND @G_IsDescending_v IS NOT NULL)
               OR (@G_IsDescending_comparator = 5 AND @G_IsDescending_v IS NOT NULL)
               OR (@G_IsDescending_comparator = 6 AND @G_IsDescending_v IS NOT NULL)
               OR (@G_IsDescending_comparator = 7 AND @G_IsDescending_vals IS NOT NULL)
               OR (@G_IsDescending_comparator = 8 AND @G_IsDescending_vals IS NOT NULL)
               OR (@G_IsDescending_comparator = 9 AND @G_IsDescending_v IS NOT NULL)
               OR (@G_IsDescending_comparator = 10 AND @G_IsDescending_v IS NOT NULL)
               OR (@G_IsDescending_comparator = 11 AND @G_IsDescending_v1 IS NOT NULL AND @G_IsDescending_v2 IS NOT NULL)
               OR (@G_IsDescending_comparator = 12 AND @G_IsDescending_v1 IS NOT NULL AND @G_IsDescending_v2 IS NOT NULL)
               OR (@G_IsDescending_comparator = 13)
               OR (@G_IsDescending_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_IsDescending_comparator
        WHEN 1 THEN N'[T].[IsDescending] < @IsDescending'
        WHEN 2 THEN N'[T].[IsDescending] <= @IsDescending'
        WHEN 3 THEN N'[T].[IsDescending] = @IsDescending'
        WHEN 4 THEN N'[T].[IsDescending] <> @IsDescending'
        WHEN 5 THEN N'[T].[IsDescending] >= @IsDescending'
        WHEN 6 THEN N'[T].[IsDescending] > @IsDescending'
        WHEN 7 THEN N'[T].[IsDescending] IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsDescending_vals))'
        WHEN 8 THEN N'[T].[IsDescending] NOT IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsDescending_vals))'
        WHEN 9 THEN N'[T].[IsDescending] LIKE @IsDescending'
        WHEN 10 THEN N'[T].[IsDescending] NOT LIKE @IsDescending'
        WHEN 11 THEN N'[T].[IsDescending] BETWEEN @IsDescending_v1 AND @IsDescending_v2'
        WHEN 12 THEN N'[T].[IsDescending] NOT BETWEEN @IsDescending_v1 AND @IsDescending_v2'
        WHEN 13 THEN N'[T].[IsDescending] IS NULL'
        WHEN 14 THEN N'[T].[IsDescending] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
        END ELSE
            SET @Where = @Where + ' AND [T].[Id] IN (' + @_ + ')'

        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] bigint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[U].[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                              ,[T].[Id]
                                    FROM [dbo].[Indexkeys] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [T].[Id] = [#].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                              ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @_ IS NULL BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_IndexId bigint,@T_ColumnId bigint,@T_IsDescending bit,@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@IndexId bigint,@IndexId_v1 bigint,@IndexId_v2 bigint,@IndexId_vals NVARCHAR(MAX),@ColumnId bigint,@ColumnId_v1 bigint,@ColumnId_v2 bigint,@ColumnId_vals NVARCHAR(MAX),@IsDescending bit,@IsDescending_v1 bit,@IsDescending_v2 bit,@IsDescending_vals NVARCHAR(MAX)'
                               ,@T_Id = @WT_Id
                               ,@T_IndexId = @WT_IndexId
                               ,@T_ColumnId = @WT_ColumnId
                               ,@T_IsDescending = @WT_IsDescending
                               ,@Id = @G_Id_v
                               ,@Id_v1 = @G_Id_v1
                               ,@Id_v2 = @G_Id_v2
                               ,@Id_vals = @G_Id_vals
                               ,@IndexId = @G_IndexId_v
                               ,@IndexId_v1 = @G_IndexId_v1
                               ,@IndexId_v2 = @G_IndexId_v2
                               ,@IndexId_vals = @G_IndexId_vals
                               ,@ColumnId = @G_ColumnId_v
                               ,@ColumnId_v1 = @G_ColumnId_v1
                               ,@ColumnId_v2 = @G_ColumnId_v2
                               ,@ColumnId_vals = @G_ColumnId_vals
                               ,@IsDescending = @G_IsDescending_v
                               ,@IsDescending_v1 = @G_IsDescending_v1
                               ,@IsDescending_v2 = @G_IsDescending_v2
                               ,@IsDescending_vals = @G_IsDescending_vals
        END ELSE BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_IndexId bigint,@T_ColumnId bigint,@T_IsDescending bit'
                               ,@T_Id = @WT_Id
                               ,@T_IndexId = @WT_IndexId
                               ,@T_ColumnId = @WT_ColumnId
                               ,@T_IsDescending = @WT_IsDescending
        END

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            DECLARE @SearchRecno BIGINT = NULL
            IF EXISTS(SELECT 1 FROM OPENJSON(@Search)) BEGIN
                DECLARE @Recno BIGINT
                   ,@S_Id_comparator TINYINT
                   ,@S_Id_v bigint
                   ,@S_Id_vals NVARCHAR(MAX)
                   ,@S_Id_v1 bigint
                   ,@S_Id_v2 bigint
                   ,@S_IndexId_comparator TINYINT
                   ,@S_IndexId_v bigint
                   ,@S_IndexId_vals NVARCHAR(MAX)
                   ,@S_IndexId_v1 bigint
                   ,@S_IndexId_v2 bigint
                   ,@S_ColumnId_comparator TINYINT
                   ,@S_ColumnId_v bigint
                   ,@S_ColumnId_vals NVARCHAR(MAX)
                   ,@S_ColumnId_v1 bigint
                   ,@S_ColumnId_v2 bigint
                   ,@S_IsDescending_comparator TINYINT
                   ,@S_IsDescending_v bit
                   ,@S_IsDescending_vals NVARCHAR(MAX)
                   ,@S_IsDescending_v1 bit
                   ,@S_IsDescending_v2 bit

                SELECT @S_Id_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Id.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.Id') IS NOT NULL AND JSON_QUERY(@Search, '$.Id') IS NULL THEN 3 END
                )
                      ,@S_Id_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Id.value') AS bigint),
