               OR (@S_IndexId_comparator = 13)
               OR (@S_IndexId_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_IndexId_comparator
        WHEN 1 THEN N'COALESCE([D].[IndexId], [O].[IndexId]) < @IndexId'
        WHEN 2 THEN N'COALESCE([D].[IndexId], [O].[IndexId]) <= @IndexId'
        WHEN 3 THEN N'COALESCE([D].[IndexId], [O].[IndexId]) = @IndexId'
        WHEN 4 THEN N'COALESCE([D].[IndexId], [O].[IndexId]) <> @IndexId'
