        WHEN 7 THEN N'COALESCE([D].[IndexId], [O].[IndexId]) IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@IndexId_vals))'
        WHEN 8 THEN N'COALESCE([D].[IndexId], [O].[IndexId]) NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@IndexId_vals))'
        WHEN 9 THEN N'COALESCE([D].[IndexId], [O].[IndexId]) LIKE @IndexId'
