        WHEN 11 THEN N'COALESCE([D].[IndexId], [O].[IndexId]) BETWEEN @IndexId_v1 AND @IndexId_v2'
        WHEN 12 THEN N'COALESCE([D].[IndexId], [O].[IndexId]) NOT BETWEEN @IndexId_v1 AND @IndexId_v2'
        WHEN 13 THEN N'COALESCE([D].[IndexId], [O].[IndexId]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[IndexId], [O].[IndexId]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'ColumnId' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[ColumnId], [O].[ColumnId]) IS NULL'
                END ELSE
                IF @S_ColumnId_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_ColumnId_comparator = 1 AND @S_ColumnId_v IS NOT NULL)
               OR (@S_ColumnId_comparator = 2 AND @S_ColumnId_v IS NOT NULL)
               OR (@S_ColumnId_comparator = 3 AND @S_ColumnId_v IS NOT NULL)
               OR (@S_ColumnId_comparator = 4 AND @S_ColumnId_v IS NOT NULL)
               OR (@S_ColumnId_comparator = 5 AND @S_ColumnId_v IS NOT NULL)
               OR (@S_ColumnId_comparator = 6 AND @S_ColumnId_v IS NOT NULL)
               OR (@S_ColumnId_comparator = 7 AND @S_ColumnId_vals IS NOT NULL)
               OR (@S_ColumnId_comparator = 8 AND @S_ColumnId_vals IS NOT NULL)
               OR (@S_ColumnId_comparator = 9 AND @S_ColumnId_v IS NOT NULL)
               OR (@S_ColumnId_comparator = 10 AND @S_ColumnId_v IS NOT NULL)
               OR (@S_ColumnId_comparator = 11 AND @S_ColumnId_v1 IS NOT NULL AND @S_ColumnId_v2 IS NOT NULL)
               OR (@S_ColumnId_comparator = 12 AND @S_ColumnId_v1 IS NOT NULL AND @S_ColumnId_v2 IS NOT NULL)
               OR (@S_ColumnId_comparator = 13)
               OR (@S_ColumnId_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_ColumnId_comparator
        WHEN 1 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) < @ColumnId'
        WHEN 2 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) <= @ColumnId'
        WHEN 3 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) = @ColumnId'
        WHEN 4 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) <> @ColumnId'
        WHEN 5 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) >= @ColumnId'
        WHEN 6 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) > @ColumnId'
        WHEN 7 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@ColumnId_vals))'
        WHEN 8 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@ColumnId_vals))'
        WHEN 9 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) LIKE @ColumnId'
        WHEN 10 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) NOT LIKE @ColumnId'
        WHEN 11 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) BETWEEN @ColumnId_v1 AND @ColumnId_v2'
        WHEN 12 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) NOT BETWEEN @ColumnId_v1 AND @ColumnId_v2'
        WHEN 13 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'IsDescending' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[IsDescending], [O].[IsDescending]) IS NULL'
                END ELSE
                IF @S_IsDescending_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_IsDescending_comparator = 1 AND @S_IsDescending_v IS NOT NULL)
               OR (@S_IsDescending_comparator = 2 AND @S_IsDescending_v IS NOT NULL)
               OR (@S_IsDescending_comparator = 3 AND @S_IsDescending_v IS NOT NULL)
               OR (@S_IsDescending_comparator = 4 AND @S_IsDescending_v IS NOT NULL)
               OR (@S_IsDescending_comparator = 5 AND @S_IsDescending_v IS NOT NULL)
               OR (@S_IsDescending_comparator = 6 AND @S_IsDescending_v IS NOT NULL)
               OR (@S_IsDescending_comparator = 7 AND @S_IsDescending_vals IS NOT NULL)
               OR (@S_IsDescending_comparator = 8 AND @S_IsDescending_vals IS NOT NULL)
               OR (@S_IsDescending_comparator = 9 AND @S_IsDescending_v IS NOT NULL)
               OR (@S_IsDescending_comparator = 10 AND @S_IsDescending_v IS NOT NULL)
               OR (@S_IsDescending_comparator = 11 AND @S_IsDescending_v1 IS NOT NULL AND @S_IsDescending_v2 IS NOT NULL)
               OR (@S_IsDescending_comparator = 12 AND @S_IsDescending_v1 IS NOT NULL AND @S_IsDescending_v2 IS NOT NULL)
               OR (@S_IsDescending_comparator = 13)
               OR (@S_IsDescending_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_IsDescending_comparator
        WHEN 1 THEN N'COALESCE([D].[IsDescending], [O].[IsDescending]) < @IsDescending'
        WHEN 2 THEN N'COALESCE([D].[IsDescending], [O].[IsDescending]) <= @IsDescending'
        WHEN 3 THEN N'COALESCE([D].[IsDescending], [O].[IsDescending]) = @IsDescending'
        WHEN 4 THEN N'COALESCE([D].[IsDescending], [O].[IsDescending]) <> @IsDescending'
        WHEN 5 THEN N'COALESCE([D].[IsDescending], [O].[IsDescending]) >= @IsDescending'
        WHEN 6 THEN N'COALESCE([D].[IsDescending], [O].[IsDescending]) > @IsDescending'
        WHEN 7 THEN N'COALESCE([D].[IsDescending], [O].[IsDescending]) IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsDescending_vals))'
        WHEN 8 THEN N'COALESCE([D].[IsDescending], [O].[IsDescending]) NOT IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsDescending_vals))'
        WHEN 9 THEN N'COALESCE([D].[IsDescending], [O].[IsDescending]) LIKE @IsDescending'
        WHEN 10 THEN N'COALESCE([D].[IsDescending], [O].[IsDescending]) NOT LIKE @IsDescending'
        WHEN 11 THEN N'COALESCE([D].[IsDescending], [O].[IsDescending]) BETWEEN @IsDescending_v1 AND @IsDescending_v2'
        WHEN 12 THEN N'COALESCE([D].[IsDescending], [O].[IsDescending]) NOT BETWEEN @IsDescending_v1 AND @IsDescending_v2'
        WHEN 13 THEN N'COALESCE([D].[IsDescending], [O].[IsDescending]) IS NULL'
