                END
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[Indexkeys] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@IndexId bigint,@IndexId_v1 bigint,@IndexId_v2 bigint,@IndexId_vals NVARCHAR(MAX),@ColumnId bigint,@ColumnId_v1 bigint,@ColumnId_v2 bigint,@ColumnId_vals NVARCHAR(MAX),@IsDescending bit,@IsDescending_v1 bit,@IsDescending_v2 bit,@IsDescending_vals NVARCHAR(MAX), @r BIGINT OUTPUT'
                                       ,@Id = @S_Id_v
                                       ,@Id_v1 = @S_Id_v1
                                       ,@Id_v2 = @S_Id_v2
                                       ,@Id_vals = @S_Id_vals
                                       ,@IndexId = @S_IndexId_v
                                       ,@IndexId_v1 = @S_IndexId_v1
                                       ,@IndexId_v2 = @S_IndexId_v2
                                       ,@IndexId_vals = @S_IndexId_vals
                                       ,@ColumnId = @S_ColumnId_v
                                       ,@ColumnId_v1 = @S_ColumnId_v1
                                       ,@ColumnId_v2 = @S_ColumnId_v2
                                       ,@ColumnId_vals = @S_ColumnId_vals
                                       ,@IsDescending = @S_IsDescending_v
                                       ,@IsDescending_v1 = @S_IsDescending_v1
                                       ,@IsDescending_v2 = @S_IsDescending_v2
                                       ,@IsDescending_vals = @S_IsDescending_vals
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS bigint) AS [IndexId]
                    ,CAST(NULL AS smallint) AS [Sequence]
                    ,CAST(NULL AS bigint) AS [ColumnId]
                    ,CAST(NULL AS bit) AS [IsDescending]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''Indexkey'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[IndexId]
                              ,[T].[Sequence]
                              ,[T].[ColumnId]
                              ,[T].[IsDescending]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Indexkeys] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Indexkey'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[IndexId]
                                  ,[O].[Sequence]
                                  ,[O].[ColumnId]
                                  ,[O].[IsDescending]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'Index' AS [Kind]
              ,[R].[Id]
              ,[R].[TableId]
              ,[R].[Name]
              ,[R].[IsUnique]
            INTO [#Indexes]
            FROM [#result] [T]
                INNER JOIN [dbo].[Indexes] [R] ON [R].[Id] = [T].[IndexId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Indexes] ON [#Indexes]([Id])
        SELECT DISTINCT 'Table' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Alias]
              ,[R].[Description]
              ,[R].[CurrentId]
            INTO [#Tables]
            FROM [#Indexes] [T]
                INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[TableId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Tables] ON [#Tables]([Id])
        SELECT DISTINCT 'Column' AS [Kind]
              ,[R].[Id]
              ,[R].[TableId]
              ,[R].[Sequence]
              ,[R].[DomainId]
              ,[R].[Name]
              ,[R].[Alias]
              ,[R].[Description]
              ,[R].[Title]
              ,[R].[Caption]
              ,[R].[Default]
              ,[R].[Minimum]
              ,[R].[Maximum]
              ,[R].[IsPrimarykey]
              ,[R].[IsAutoIncrement]
              ,[R].[IsRequired]
              ,[R].[IsListable]
              ,[R].[IsFilterable]
              ,[R].[IsEditable]
              ,[R].[IsGridable]
              ,[R].[IsEncrypted]
              ,[R].[IsInWords]
              ,[R].[IsVirtual]
            INTO [#Columns]
            FROM [#result] [T]
                INNER JOIN [dbo].[Columns] [R] ON [R].[Id] = [T].[ColumnId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Columns] ON [#Columns]([Id])
        INSERT INTO [#Tables]
            SELECT DISTINCT 'Table' AS [Kind]
                  ,[R].[Id]
                  ,[R].[Name]
                  ,[R].[Alias]
                  ,[R].[Description]
                  ,[R].[CurrentId]
                FROM [#Columns] [T]
                    INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[TableId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Tables] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        SELECT DISTINCT 'Domain' AS [Kind]
              ,[R].[Id]
              ,[R].[TypeId]
              ,[R].[MaskId]
              ,[R].[Name]
              ,[R].[Length]
              ,[R].[Decimals]
              ,[R].[ValidValues]
              ,[R].[Default]
              ,[R].[Minimum]
              ,[R].[Maximum]
              ,[R].[Codification]
            INTO [#Domains]
            FROM [#Columns] [T]
                INNER JOIN [dbo].[Domains] [R] ON [R].[Id] = [T].[DomainId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Domains] ON [#Domains]([Id])
        SELECT DISTINCT 'Type' AS [Kind]
              ,[R].[Id]
              ,[R].[CategoryId]
              ,[R].[Name]
              ,[R].[MaxLength]
              ,[R].[Minimum]
              ,[R].[Maximum]
              ,[R].[AskLength]
              ,[R].[AskDecimals]
              ,[R].[AskPrimarykey]
              ,[R].[AskAutoincrement]
              ,[R].[AskFilterable]
              ,[R].[AskGridable]
              ,[R].[AskCodification]
              ,[R].[IsLikeable]
              ,[R].[IsActive]
            INTO [#Types]
            FROM [#Domains] [T]
                INNER JOIN [dbo].[Types] [R] ON [R].[Id] = [T].[TypeId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Types] ON [#Types]([Id])
        SELECT DISTINCT 'Category' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[HtmlInputType]
              ,[R].[HtmlInputAlign]
              ,[R].[AskEncrypted]
              ,[R].[AskMask]
              ,[R].[AskListable]
              ,[R].[AskDefault]
              ,[R].[AskMinimum]
              ,[R].[AskMaximum]
              ,[R].[AskInWords]
            INTO [#Categories]
            FROM [#Types] [T]
                INNER JOIN [dbo].[Categories] [R] ON [R].[Id] = [T].[CategoryId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Categories] ON [#Categories]([Id])
        SELECT DISTINCT 'Mask' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Mask]
            INTO [#Masks]
            FROM [#Domains] [T]
                INNER JOIN [dbo].[Masks] [R] ON [R].[Id] = [T].[MaskId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Masks] ON [#Masks]([Id])
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[IndexId]
                      ,[Sequence]
                      ,[ColumnId]
                      ,[IsDescending]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [Index].* FROM [#Indexes] AS [Index] FOR JSON PATH), '[]') AS [Index]
              ,ISNULL((SELECT [Table].* FROM [#Tables] AS [Table] FOR JSON PATH), '[]') AS [Table]
              ,ISNULL((SELECT [Column].* FROM [#Columns] AS [Column] FOR JSON PATH), '[]') AS [Column]
              ,ISNULL((SELECT [Domain].* FROM [#Domains] AS [Domain] FOR JSON PATH), '[]') AS [Domain]
              ,ISNULL((SELECT [Type].* FROM [#Types] AS [Type] FOR JSON PATH), '[]') AS [Type]
              ,ISNULL((SELECT [Category].* FROM [#Categories] AS [Category] FOR JSON PATH), '[]') AS [Category]
              ,ISNULL((SELECT [Mask].* FROM [#Masks] AS [Mask] FOR JSON PATH), '[]') AS [Mask]
        SET @ReturnValue = @RowCount

    RETURN 0
END
