                                          ,[ClientRsaPublicKey] = @W_ClientRsaPublicKey
                                          ,[PublicKey] = @W_PublicKey
                                          ,[IsLogged] = @W_IsLogged
                                          ,[UpdatedAt] = GETDATE()
                                          ,[UpdatedBy] = @UserName
            WHERE [Id] = @W_Id
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
