ALTER PROCEDURE [dbo].[SessionDelete](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'Sessions'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'delete'
            THROW 51000, 'Ação da operação é inválida para Delete', 1
        EXEC @TransactionIdAux = [dbo].[SessionValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id bigint = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

        DELETE FROM [dbo].[Sessions] WHERE [Id] = @W_Id

        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[SessionsRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[SessionsRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[SessionsRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[SessionsRead](@Login NVARCHAR(MAX)
                                          ,@Filter NVARCHAR(MAX)
                                          ,@Search NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

        IF @Filter IS NULL
            SET @Filter = '{}'
        ELSE IF ISJSON(@Filter) = 0
            THROW 51000, 'Valor de @Filter não está no formato JSON', 1
        IF @Search IS NULL
            SET @Search = '{}'
        ELSE IF ISJSON(@Search) = 0
            THROW 51000, 'Valor de @Search não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Sessions') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @SessionId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.SystemId') AS bigint) AS [SystemId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.UserId') AS bigint) AS [UserId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ClientRsaPublicKey') AS nvarchar(512)) AS [ClientRsaPublicKey]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.PublicKey') AS nvarchar(256)) AS [PublicKey]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsLogged') AS bit) AS [IsLogged]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Sessions'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@Filter, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@ComparatorPredicate NVARCHAR(MAX)
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id bigint = CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)
               ,@WT_SystemId bigint = CAST(JSON_VALUE(@Filter, '$.SystemId') AS bigint)
               ,@WT_UserId bigint = CAST(JSON_VALUE(@Filter, '$.UserId') AS bigint)
               ,@WT_IsLogged bit = CAST(JSON_VALUE(@Filter, '$.IsLogged') AS bit)

        IF @WT_Id IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Id] = @T_Id'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'SystemId' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[SystemId] IS NULL'
        ELSE IF @WT_SystemId IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[SystemId] = @T_SystemId'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'UserId' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[UserId] IS NULL'
        ELSE IF @WT_UserId IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[UserId] = @T_UserId'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'IsLogged' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[IsLogged] IS NULL'
        ELSE IF @WT_IsLogged IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[IsLogged] = @T_IsLogged'
        END
        IF @_ IS NULL BEGIN
            DECLARE @G_Id_comparator TINYINT
                   ,@G_Id_v bigint
                   ,@G_Id_vals NVARCHAR(MAX)
                   ,@G_Id_v1 bigint
                   ,@G_Id_v2 bigint
                   ,@G_SystemId_comparator TINYINT
                   ,@G_SystemId_v bigint
                   ,@G_SystemId_vals NVARCHAR(MAX)
                   ,@G_SystemId_v1 bigint
                   ,@G_SystemId_v2 bigint
                   ,@G_UserId_comparator TINYINT
                   ,@G_UserId_v bigint
                   ,@G_UserId_vals NVARCHAR(MAX)
                   ,@G_UserId_v1 bigint
                   ,@G_UserId_v2 bigint
                   ,@G_IsLogged_comparator TINYINT
                   ,@G_IsLogged_v bit
                   ,@G_IsLogged_vals NVARCHAR(MAX)
                   ,@G_IsLogged_v1 bit
                   ,@G_IsLogged_v2 bit

            SELECT @G_Id_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Id') IS NOT NULL AND JSON_QUERY(@Filter, '$.Id') IS NULL THEN 3 END
            )
                  ,@G_Id_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.value') AS bigint),
                TRY_CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)
            )
                  ,@G_Id_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Id.value'),
                JSON_QUERY(@Filter, '$.Id')
            )
            SELECT @G_Id_v1 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[0]') AS bigint)
                  ,@G_Id_v2 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[1]') AS bigint)
            SELECT @G_SystemId_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.SystemId.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.SystemId') IS NOT NULL AND JSON_QUERY(@Filter, '$.SystemId') IS NULL THEN 3 END
            )
                  ,@G_SystemId_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.SystemId.value') AS bigint),
                TRY_CAST(JSON_VALUE(@Filter, '$.SystemId') AS bigint)
            )
                  ,@G_SystemId_vals = COALESCE(
                JSON_QUERY(@Filter, '$.SystemId.value'),
                JSON_QUERY(@Filter, '$.SystemId')
            )
            SELECT @G_SystemId_v1 = TRY_CAST(JSON_VALUE(@G_SystemId_vals, '$[0]') AS bigint)
                  ,@G_SystemId_v2 = TRY_CAST(JSON_VALUE(@G_SystemId_vals, '$[1]') AS bigint)
            SELECT @G_UserId_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.UserId.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.UserId') IS NOT NULL AND JSON_QUERY(@Filter, '$.UserId') IS NULL THEN 3 END
            )
                  ,@G_UserId_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.UserId.value') AS bigint),
                TRY_CAST(JSON_VALUE(@Filter, '$.UserId') AS bigint)
            )
                  ,@G_UserId_vals = COALESCE(
                JSON_QUERY(@Filter, '$.UserId.value'),
                JSON_QUERY(@Filter, '$.UserId')
            )
            SELECT @G_UserId_v1 = TRY_CAST(JSON_VALUE(@G_UserId_vals, '$[0]') AS bigint)
                  ,@G_UserId_v2 = TRY_CAST(JSON_VALUE(@G_UserId_vals, '$[1]') AS bigint)
            SELECT @G_IsLogged_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.IsLogged.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.IsLogged') IS NOT NULL AND JSON_QUERY(@Filter, '$.IsLogged') IS NULL THEN 3 END
            )
                  ,@G_IsLogged_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.IsLogged.value') AS bit),
                TRY_CAST(JSON_VALUE(@Filter, '$.IsLogged') AS bit)
            )
                  ,@G_IsLogged_vals = COALESCE(
                JSON_QUERY(@Filter, '$.IsLogged.value'),
                JSON_QUERY(@Filter, '$.IsLogged')
            )
            SELECT @G_IsLogged_v1 = TRY_CAST(JSON_VALUE(@G_IsLogged_vals, '$[0]') AS bit)
                  ,@G_IsLogged_v2 = TRY_CAST(JSON_VALUE(@G_IsLogged_vals, '$[1]') AS bit)

            IF @G_Id_comparator IS NOT NULL BEGIN
                IF (@G_Id_comparator = 1 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 2 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 3 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 4 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 5 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 6 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 7 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 8 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 9 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 10 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 11 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 12 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 13)
               OR (@G_Id_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_Id_comparator
        WHEN 1 THEN N'[T].[Id] < @Id'
        WHEN 2 THEN N'[T].[Id] <= @Id'
        WHEN 3 THEN N'[T].[Id] = @Id'
        WHEN 4 THEN N'[T].[Id] <> @Id'
        WHEN 5 THEN N'[T].[Id] >= @Id'
        WHEN 6 THEN N'[T].[Id] > @Id'
        WHEN 7 THEN N'[T].[Id] IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 8 THEN N'[T].[Id] NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 9 THEN N'[T].[Id] LIKE @Id'
        WHEN 10 THEN N'[T].[Id] NOT LIKE @Id'
        WHEN 11 THEN N'[T].[Id] BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'[T].[Id] NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'[T].[Id] IS NULL'
        WHEN 14 THEN N'[T].[Id] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'SystemId' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[SystemId] IS NULL'
            ELSE
            IF @G_SystemId_comparator IS NOT NULL BEGIN
                IF (@G_SystemId_comparator = 1 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 2 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 3 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 4 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 5 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 6 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 7 AND @G_SystemId_vals IS NOT NULL)
               OR (@G_SystemId_comparator = 8 AND @G_SystemId_vals IS NOT NULL)
               OR (@G_SystemId_comparator = 9 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 10 AND @G_SystemId_v IS NOT NULL)
               OR (@G_SystemId_comparator = 11 AND @G_SystemId_v1 IS NOT NULL AND @G_SystemId_v2 IS NOT NULL)
               OR (@G_SystemId_comparator = 12 AND @G_SystemId_v1 IS NOT NULL AND @G_SystemId_v2 IS NOT NULL)
               OR (@G_SystemId_comparator = 13)
               OR (@G_SystemId_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_SystemId_comparator
        WHEN 1 THEN N'[T].[SystemId] < @SystemId'
        WHEN 2 THEN N'[T].[SystemId] <= @SystemId'
        WHEN 3 THEN N'[T].[SystemId] = @SystemId'
        WHEN 4 THEN N'[T].[SystemId] <> @SystemId'
        WHEN 5 THEN N'[T].[SystemId] >= @SystemId'
        WHEN 6 THEN N'[T].[SystemId] > @SystemId'
        WHEN 7 THEN N'[T].[SystemId] IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@SystemId_vals))'
        WHEN 8 THEN N'[T].[SystemId] NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@SystemId_vals))'
        WHEN 9 THEN N'[T].[SystemId] LIKE @SystemId'
        WHEN 10 THEN N'[T].[SystemId] NOT LIKE @SystemId'
        WHEN 11 THEN N'[T].[SystemId] BETWEEN @SystemId_v1 AND @SystemId_v2'
        WHEN 12 THEN N'[T].[SystemId] NOT BETWEEN @SystemId_v1 AND @SystemId_v2'
        WHEN 13 THEN N'[T].[SystemId] IS NULL'
        WHEN 14 THEN N'[T].[SystemId] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'UserId' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[UserId] IS NULL'
            ELSE
            IF @G_UserId_comparator IS NOT NULL BEGIN
                IF (@G_UserId_comparator = 1 AND @G_UserId_v IS NOT NULL)
               OR (@G_UserId_comparator = 2 AND @G_UserId_v IS NOT NULL)
               OR (@G_UserId_comparator = 3 AND @G_UserId_v IS NOT NULL)
               OR (@G_UserId_comparator = 4 AND @G_UserId_v IS NOT NULL)
               OR (@G_UserId_comparator = 5 AND @G_UserId_v IS NOT NULL)
               OR (@G_UserId_comparator = 6 AND @G_UserId_v IS NOT NULL)
               OR (@G_UserId_comparator = 7 AND @G_UserId_vals IS NOT NULL)
               OR (@G_UserId_comparator = 8 AND @G_UserId_vals IS NOT NULL)
               OR (@G_UserId_comparator = 9 AND @G_UserId_v IS NOT NULL)
               OR (@G_UserId_comparator = 10 AND @G_UserId_v IS NOT NULL)
               OR (@G_UserId_comparator = 11 AND @G_UserId_v1 IS NOT NULL AND @G_UserId_v2 IS NOT NULL)
               OR (@G_UserId_comparator = 12 AND @G_UserId_v1 IS NOT NULL AND @G_UserId_v2 IS NOT NULL)
               OR (@G_UserId_comparator = 13)
               OR (@G_UserId_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_UserId_comparator
        WHEN 1 THEN N'[T].[UserId] < @UserId'
        WHEN 2 THEN N'[T].[UserId] <= @UserId'
        WHEN 3 THEN N'[T].[UserId] = @UserId'
        WHEN 4 THEN N'[T].[UserId] <> @UserId'
        WHEN 5 THEN N'[T].[UserId] >= @UserId'
        WHEN 6 THEN N'[T].[UserId] > @UserId'
        WHEN 7 THEN N'[T].[UserId] IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@UserId_vals))'
        WHEN 8 THEN N'[T].[UserId] NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@UserId_vals))'
        WHEN 9 THEN N'[T].[UserId] LIKE @UserId'
        WHEN 10 THEN N'[T].[UserId] NOT LIKE @UserId'
        WHEN 11 THEN N'[T].[UserId] BETWEEN @UserId_v1 AND @UserId_v2'
        WHEN 12 THEN N'[T].[UserId] NOT BETWEEN @UserId_v1 AND @UserId_v2'
        WHEN 13 THEN N'[T].[UserId] IS NULL'
        WHEN 14 THEN N'[T].[UserId] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'IsLogged' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[IsLogged] IS NULL'
            ELSE
            IF @G_IsLogged_comparator IS NOT NULL BEGIN
                IF (@G_IsLogged_comparator = 1 AND @G_IsLogged_v IS NOT NULL)
               OR (@G_IsLogged_comparator = 2 AND @G_IsLogged_v IS NOT NULL)
               OR (@G_IsLogged_comparator = 3 AND @G_IsLogged_v IS NOT NULL)
               OR (@G_IsLogged_comparator = 4 AND @G_IsLogged_v IS NOT NULL)
               OR (@G_IsLogged_comparator = 5 AND @G_IsLogged_v IS NOT NULL)
               OR (@G_IsLogged_comparator = 6 AND @G_IsLogged_v IS NOT NULL)
               OR (@G_IsLogged_comparator = 7 AND @G_IsLogged_vals IS NOT NULL)
               OR (@G_IsLogged_comparator = 8 AND @G_IsLogged_vals IS NOT NULL)
               OR (@G_IsLogged_comparator = 9 AND @G_IsLogged_v IS NOT NULL)
               OR (@G_IsLogged_comparator = 10 AND @G_IsLogged_v IS NOT NULL)
               OR (@G_IsLogged_comparator = 11 AND @G_IsLogged_v1 IS NOT NULL AND @G_IsLogged_v2 IS NOT NULL)
               OR (@G_IsLogged_comparator = 12 AND @G_IsLogged_v1 IS NOT NULL AND @G_IsLogged_v2 IS NOT NULL)
               OR (@G_IsLogged_comparator = 13)
               OR (@G_IsLogged_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_IsLogged_comparator
        WHEN 1 THEN N'[T].[IsLogged] < @IsLogged'
        WHEN 2 THEN N'[T].[IsLogged] <= @IsLogged'
        WHEN 3 THEN N'[T].[IsLogged] = @IsLogged'
        WHEN 4 THEN N'[T].[IsLogged] <> @IsLogged'
        WHEN 5 THEN N'[T].[IsLogged] >= @IsLogged'
        WHEN 6 THEN N'[T].[IsLogged] > @IsLogged'
        WHEN 7 THEN N'[T].[IsLogged] IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsLogged_vals))'
        WHEN 8 THEN N'[T].[IsLogged] NOT IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsLogged_vals))'
        WHEN 9 THEN N'[T].[IsLogged] LIKE @IsLogged'
        WHEN 10 THEN N'[T].[IsLogged] NOT LIKE @IsLogged'
        WHEN 11 THEN N'[T].[IsLogged] BETWEEN @IsLogged_v1 AND @IsLogged_v2'
        WHEN 12 THEN N'[T].[IsLogged] NOT BETWEEN @IsLogged_v1 AND @IsLogged_v2'
        WHEN 13 THEN N'[T].[IsLogged] IS NULL'
        WHEN 14 THEN N'[T].[IsLogged] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
        END ELSE
            SET @Where = @Where + ' AND [T].[Id] IN (' + @_ + ')'

        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] bigint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[U].[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                              ,[T].[Id]
                                    FROM [dbo].[Sessions] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [T].[Id] = [#].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                              ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @_ IS NULL BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_SystemId bigint,@T_UserId bigint,@T_IsLogged bit,@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@SystemId bigint,@SystemId_v1 bigint,@SystemId_v2 bigint,@SystemId_vals NVARCHAR(MAX),@UserId bigint,@UserId_v1 bigint,@UserId_v2 bigint,@UserId_vals NVARCHAR(MAX),@IsLogged bit,@IsLogged_v1 bit,@IsLogged_v2 bit,@IsLogged_vals NVARCHAR(MAX)'
                               ,@T_Id = @WT_Id
                               ,@T_SystemId = @WT_SystemId
                               ,@T_UserId = @WT_UserId
                               ,@T_IsLogged = @WT_IsLogged
                               ,@Id = @G_Id_v
                               ,@Id_v1 = @G_Id_v1
                               ,@Id_v2 = @G_Id_v2
                               ,@Id_vals = @G_Id_vals
                               ,@SystemId = @G_SystemId_v
                               ,@SystemId_v1 = @G_SystemId_v1
                               ,@SystemId_v2 = @G_SystemId_v2
                               ,@SystemId_vals = @G_SystemId_vals
                               ,@UserId = @G_UserId_v
                               ,@UserId_v1 = @G_UserId_v1
                               ,@UserId_v2 = @G_UserId_v2
                               ,@UserId_vals = @G_UserId_vals
                               ,@IsLogged = @G_IsLogged_v
                               ,@IsLogged_v1 = @G_IsLogged_v1
                               ,@IsLogged_v2 = @G_IsLogged_v2
                               ,@IsLogged_vals = @G_IsLogged_vals
        END ELSE BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_SystemId bigint,@T_UserId bigint,@T_IsLogged bit'
                               ,@T_Id = @WT_Id
                               ,@T_SystemId = @WT_SystemId
                               ,@T_UserId = @WT_UserId
                               ,@T_IsLogged = @WT_IsLogged
        END

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            DECLARE @SearchRecno BIGINT = NULL
            IF EXISTS(SELECT 1 FROM OPENJSON(@Search)) BEGIN
                DECLARE @Recno BIGINT
                   ,@S_Id_comparator TINYINT
                   ,@S_Id_v bigint
                   ,@S_Id_vals NVARCHAR(MAX)
                   ,@S_Id_v1 bigint
                   ,@S_Id_v2 bigint
                   ,@S_SystemId_comparator TINYINT
                   ,@S_SystemId_v bigint
                   ,@S_SystemId_vals NVARCHAR(MAX)
                   ,@S_SystemId_v1 bigint
                   ,@S_SystemId_v2 bigint
                   ,@S_UserId_comparator TINYINT
                   ,@S_UserId_v bigint
                   ,@S_UserId_vals NVARCHAR(MAX)
                   ,@S_UserId_v1 bigint
                   ,@S_UserId_v2 bigint
                   ,@S_IsLogged_comparator TINYINT
                   ,@S_IsLogged_v bit
                   ,@S_IsLogged_vals NVARCHAR(MAX)
                   ,@S_IsLogged_v1 bit
                   ,@S_IsLogged_v2 bit

                SELECT @S_Id_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Id.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.Id') IS NOT NULL AND JSON_QUERY(@Search, '$.Id') IS NULL THEN 3 END
                )
                      ,@S_Id_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Id.value') AS bigint),
                    TRY_CAST(JSON_VALUE(@Search, '$.Id') AS bigint)
                )
                      ,@S_Id_vals = COALESCE(
                    JSON_QUERY(@Search, '$.Id.value'),
                    JSON_QUERY(@Search, '$.Id')
                )
                SELECT @S_Id_v1 = TRY_CAST(JSON_VALUE(@S_Id_vals, '$[0]') AS bigint)
                      ,@S_Id_v2 = TRY_CAST(JSON_VALUE(@S_Id_vals, '$[1]') AS bigint)
                SELECT @S_SystemId_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.SystemId.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.SystemId') IS NOT NULL AND JSON_QUERY(@Search, '$.SystemId') IS NULL THEN 3 END
                )
                      ,@S_SystemId_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.SystemId.value') AS bigint),
                    TRY_CAST(JSON_VALUE(@Search, '$.SystemId') AS bigint)
                )
                      ,@S_SystemId_vals = COALESCE(
                    JSON_QUERY(@Search, '$.SystemId.value'),
                    JSON_QUERY(@Search, '$.SystemId')
                )
                SELECT @S_SystemId_v1 = TRY_CAST(JSON_VALUE(@S_SystemId_vals, '$[0]') AS bigint)
                      ,@S_SystemId_v2 = TRY_CAST(JSON_VALUE(@S_SystemId_vals, '$[1]') AS bigint)
                SELECT @S_UserId_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.UserId.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.UserId') IS NOT NULL AND JSON_QUERY(@Search, '$.UserId') IS NULL THEN 3 END
                )
                      ,@S_UserId_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.UserId.value') AS bigint),
                    TRY_CAST(JSON_VALUE(@Search, '$.UserId') AS bigint)
                )
                      ,@S_UserId_vals = COALESCE(
                    JSON_QUERY(@Search, '$.UserId.value'),
                    JSON_QUERY(@Search, '$.UserId')
                )
                SELECT @S_UserId_v1 = TRY_CAST(JSON_VALUE(@S_UserId_vals, '$[0]') AS bigint)
                      ,@S_UserId_v2 = TRY_CAST(JSON_VALUE(@S_UserId_vals, '$[1]') AS bigint)
                SELECT @S_IsLogged_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.IsLogged.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.IsLogged') IS NOT NULL AND JSON_QUERY(@Search, '$.IsLogged') IS NULL THEN 3 END
                )
                      ,@S_IsLogged_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.IsLogged.value') AS bit),
                    TRY_CAST(JSON_VALUE(@Search, '$.IsLogged') AS bit)
                )
                      ,@S_IsLogged_vals = COALESCE(
                    JSON_QUERY(@Search, '$.IsLogged.value'),
                    JSON_QUERY(@Search, '$.IsLogged')
                )
                SELECT @S_IsLogged_v1 = TRY_CAST(JSON_VALUE(@S_IsLogged_vals, '$[0]') AS bit)
                      ,@S_IsLogged_v2 = TRY_CAST(JSON_VALUE(@S_IsLogged_vals, '$[1]') AS bit)

                SET @Where = ''
                IF @S_Id_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_Id_comparator = 1 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 2 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 3 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 4 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 5 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 6 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 7 AND @S_Id_vals IS NOT NULL)
               OR (@S_Id_comparator = 8 AND @S_Id_vals IS NOT NULL)
               OR (@S_Id_comparator = 9 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 10 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 11 AND @S_Id_v1 IS NOT NULL AND @S_Id_v2 IS NOT NULL)
               OR (@S_Id_comparator = 12 AND @S_Id_v1 IS NOT NULL AND @S_Id_v2 IS NOT NULL)
               OR (@S_Id_comparator = 13)
               OR (@S_Id_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_Id_comparator
        WHEN 1 THEN N'COALESCE([D].[Id], [O].[Id]) < @Id'
        WHEN 2 THEN N'COALESCE([D].[Id], [O].[Id]) <= @Id'
        WHEN 3 THEN N'COALESCE([D].[Id], [O].[Id]) = @Id'
        WHEN 4 THEN N'COALESCE([D].[Id], [O].[Id]) <> @Id'
        WHEN 5 THEN N'COALESCE([D].[Id], [O].[Id]) >= @Id'
        WHEN 6 THEN N'COALESCE([D].[Id], [O].[Id]) > @Id'
        WHEN 7 THEN N'COALESCE([D].[Id], [O].[Id]) IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 8 THEN N'COALESCE([D].[Id], [O].[Id]) NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 9 THEN N'COALESCE([D].[Id], [O].[Id]) LIKE @Id'
        WHEN 10 THEN N'COALESCE([D].[Id], [O].[Id]) NOT LIKE @Id'
        WHEN 11 THEN N'COALESCE([D].[Id], [O].[Id]) BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'COALESCE([D].[Id], [O].[Id]) NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'COALESCE([D].[Id], [O].[Id]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[Id], [O].[Id]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'SystemId' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[SystemId], [O].[SystemId]) IS NULL'
                END ELSE
                IF @S_SystemId_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_SystemId_comparator = 1 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 2 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 3 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 4 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 5 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 6 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 7 AND @S_SystemId_vals IS NOT NULL)
               OR (@S_SystemId_comparator = 8 AND @S_SystemId_vals IS NOT NULL)
               OR (@S_SystemId_comparator = 9 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 10 AND @S_SystemId_v IS NOT NULL)
               OR (@S_SystemId_comparator = 11 AND @S_SystemId_v1 IS NOT NULL AND @S_SystemId_v2 IS NOT NULL)
               OR (@S_SystemId_comparator = 12 AND @S_SystemId_v1 IS NOT NULL AND @S_SystemId_v2 IS NOT NULL)
               OR (@S_SystemId_comparator = 13)
               OR (@S_SystemId_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_SystemId_comparator
        WHEN 1 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) < @SystemId'
        WHEN 2 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) <= @SystemId'
        WHEN 3 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) = @SystemId'
        WHEN 4 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) <> @SystemId'
        WHEN 5 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) >= @SystemId'
        WHEN 6 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) > @SystemId'
        WHEN 7 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@SystemId_vals))'
        WHEN 8 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@SystemId_vals))'
        WHEN 9 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) LIKE @SystemId'
        WHEN 10 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) NOT LIKE @SystemId'
        WHEN 11 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) BETWEEN @SystemId_v1 AND @SystemId_v2'
        WHEN 12 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) NOT BETWEEN @SystemId_v1 AND @SystemId_v2'
        WHEN 13 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[SystemId], [O].[SystemId]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'UserId' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[UserId], [O].[UserId]) IS NULL'
                END ELSE
                IF @S_UserId_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_UserId_comparator = 1 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 2 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 3 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 4 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 5 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 6 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 7 AND @S_UserId_vals IS NOT NULL)
               OR (@S_UserId_comparator = 8 AND @S_UserId_vals IS NOT NULL)
               OR (@S_UserId_comparator = 9 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 10 AND @S_UserId_v IS NOT NULL)
               OR (@S_UserId_comparator = 11 AND @S_UserId_v1 IS NOT NULL AND @S_UserId_v2 IS NOT NULL)
               OR (@S_UserId_comparator = 12 AND @S_UserId_v1 IS NOT NULL AND @S_UserId_v2 IS NOT NULL)
               OR (@S_UserId_comparator = 13)
               OR (@S_UserId_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_UserId_comparator
        WHEN 1 THEN N'COALESCE([D].[UserId], [O].[UserId]) < @UserId'
        WHEN 2 THEN N'COALESCE([D].[UserId], [O].[UserId]) <= @UserId'
        WHEN 3 THEN N'COALESCE([D].[UserId], [O].[UserId]) = @UserId'
        WHEN 4 THEN N'COALESCE([D].[UserId], [O].[UserId]) <> @UserId'
        WHEN 5 THEN N'COALESCE([D].[UserId], [O].[UserId]) >= @UserId'
        WHEN 6 THEN N'COALESCE([D].[UserId], [O].[UserId]) > @UserId'
        WHEN 7 THEN N'COALESCE([D].[UserId], [O].[UserId]) IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@UserId_vals))'
        WHEN 8 THEN N'COALESCE([D].[UserId], [O].[UserId]) NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@UserId_vals))'
        WHEN 9 THEN N'COALESCE([D].[UserId], [O].[UserId]) LIKE @UserId'
        WHEN 10 THEN N'COALESCE([D].[UserId], [O].[UserId]) NOT LIKE @UserId'
        WHEN 11 THEN N'COALESCE([D].[UserId], [O].[UserId]) BETWEEN @UserId_v1 AND @UserId_v2'
        WHEN 12 THEN N'COALESCE([D].[UserId], [O].[UserId]) NOT BETWEEN @UserId_v1 AND @UserId_v2'
        WHEN 13 THEN N'COALESCE([D].[UserId], [O].[UserId]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[UserId], [O].[UserId]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'IsLogged' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[IsLogged], [O].[IsLogged]) IS NULL'
                END ELSE
                IF @S_IsLogged_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_IsLogged_comparator = 1 AND @S_IsLogged_v IS NOT NULL)
               OR (@S_IsLogged_comparator = 2 AND @S_IsLogged_v IS NOT NULL)
               OR (@S_IsLogged_comparator = 3 AND @S_IsLogged_v IS NOT NULL)
               OR (@S_IsLogged_comparator = 4 AND @S_IsLogged_v IS NOT NULL)
               OR (@S_IsLogged_comparator = 5 AND @S_IsLogged_v IS NOT NULL)
               OR (@S_IsLogged_comparator = 6 AND @S_IsLogged_v IS NOT NULL)
               OR (@S_IsLogged_comparator = 7 AND @S_IsLogged_vals IS NOT NULL)
               OR (@S_IsLogged_comparator = 8 AND @S_IsLogged_vals IS NOT NULL)
               OR (@S_IsLogged_comparator = 9 AND @S_IsLogged_v IS NOT NULL)
               OR (@S_IsLogged_comparator = 10 AND @S_IsLogged_v IS NOT NULL)
               OR (@S_IsLogged_comparator = 11 AND @S_IsLogged_v1 IS NOT NULL AND @S_IsLogged_v2 IS NOT NULL)
               OR (@S_IsLogged_comparator = 12 AND @S_IsLogged_v1 IS NOT NULL AND @S_IsLogged_v2 IS NOT NULL)
               OR (@S_IsLogged_comparator = 13)
               OR (@S_IsLogged_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_IsLogged_comparator
        WHEN 1 THEN N'COALESCE([D].[IsLogged], [O].[IsLogged]) < @IsLogged'
        WHEN 2 THEN N'COALESCE([D].[IsLogged], [O].[IsLogged]) <= @IsLogged'
        WHEN 3 THEN N'COALESCE([D].[IsLogged], [O].[IsLogged]) = @IsLogged'
        WHEN 4 THEN N'COALESCE([D].[IsLogged], [O].[IsLogged]) <> @IsLogged'
        WHEN 5 THEN N'COALESCE([D].[IsLogged], [O].[IsLogged]) >= @IsLogged'
        WHEN 6 THEN N'COALESCE([D].[IsLogged], [O].[IsLogged]) > @IsLogged'
        WHEN 7 THEN N'COALESCE([D].[IsLogged], [O].[IsLogged]) IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsLogged_vals))'
        WHEN 8 THEN N'COALESCE([D].[IsLogged], [O].[IsLogged]) NOT IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsLogged_vals))'
        WHEN 9 THEN N'COALESCE([D].[IsLogged], [O].[IsLogged]) LIKE @IsLogged'
        WHEN 10 THEN N'COALESCE([D].[IsLogged], [O].[IsLogged]) NOT LIKE @IsLogged'
        WHEN 11 THEN N'COALESCE([D].[IsLogged], [O].[IsLogged]) BETWEEN @IsLogged_v1 AND @IsLogged_v2'
        WHEN 12 THEN N'COALESCE([D].[IsLogged], [O].[IsLogged]) NOT BETWEEN @IsLogged_v1 AND @IsLogged_v2'
        WHEN 13 THEN N'COALESCE([D].[IsLogged], [O].[IsLogged]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[IsLogged], [O].[IsLogged]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[Sessions] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@SystemId bigint,@SystemId_v1 bigint,@SystemId_v2 bigint,@SystemId_vals NVARCHAR(MAX),@UserId bigint,@UserId_v1 bigint,@UserId_v2 bigint,@UserId_vals NVARCHAR(MAX),@IsLogged bit,@IsLogged_v1 bit,@IsLogged_v2 bit,@IsLogged_vals NVARCHAR(MAX), @r BIGINT OUTPUT'
                                       ,@Id = @S_Id_v
                                       ,@Id_v1 = @S_Id_v1
                                       ,@Id_v2 = @S_Id_v2
                                       ,@Id_vals = @S_Id_vals
                                       ,@SystemId = @S_SystemId_v
                                       ,@SystemId_v1 = @S_SystemId_v1
                                       ,@SystemId_v2 = @S_SystemId_v2
                                       ,@SystemId_vals = @S_SystemId_vals
                                       ,@UserId = @S_UserId_v
                                       ,@UserId_v1 = @S_UserId_v1
                                       ,@UserId_v2 = @S_UserId_v2
                                       ,@UserId_vals = @S_UserId_vals
                                       ,@IsLogged = @S_IsLogged_v
                                       ,@IsLogged_v1 = @S_IsLogged_v1
                                       ,@IsLogged_v2 = @S_IsLogged_v2
                                       ,@IsLogged_vals = @S_IsLogged_vals
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS bigint) AS [SystemId]
                    ,CAST(NULL AS bigint) AS [UserId]
                    ,CAST(NULL AS nvarchar(512)) AS [ClientRsaPublicKey]
                    ,CAST(NULL AS nvarchar(256)) AS [PublicKey]
                    ,CAST(NULL AS bit) AS [IsLogged]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''Session'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[SystemId]
                              ,[T].[UserId]
                              ,[T].[ClientRsaPublicKey]
                              ,[T].[PublicKey]
                              ,[T].[IsLogged]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Sessions] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Session'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[SystemId]
                                  ,[O].[UserId]
                                  ,[O].[ClientRsaPublicKey]
                                  ,[O].[PublicKey]
                                  ,[O].[IsLogged]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'System' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Description]
              ,[R].[ClientName]
              ,[R].[MaxRetryLogins]
              ,[R].[IsOffAir]
            INTO [#Systems]
            FROM [#result] [T]
                INNER JOIN [dbo].[Systems] [R] ON [R].[Id] = [T].[SystemId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Systems] ON [#Systems]([Id])
        SELECT DISTINCT 'User' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Password]
              ,[R].[FullName]
              ,[R].[RetryLogins]
              ,[R].[IsActive]
            INTO [#Users]
            FROM [#result] [T]
                INNER JOIN [dbo].[Users] [R] ON [R].[Id] = [T].[UserId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Users] ON [#Users]([Id])
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[SystemId]
                      ,[UserId]
                      ,[ClientRsaPublicKey]
                      ,[PublicKey]
                      ,[IsLogged]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [System].* FROM [#Systems] AS [System] FOR JSON PATH), '[]') AS [System]
              ,ISNULL((SELECT [User].* FROM [#Users] AS [User] FOR JSON PATH), '[]') AS [User]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[TransactionValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TransactionValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[TransactionValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[TransactionValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id bigint

        IF @Action = 'delete' BEGIN
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

        END ELSE BEGIN
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        END
        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS bigint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @W_Id) AND @Action = 'create'
            THROW 51000, 'Chave-primária já existe em Transactions', 1
        ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Transactions'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND                                           CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create' AND NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @W_Id)
            THROW 51000, 'Chave-primária não existe em Transactions', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Transactions]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [SessionId] = JSON_VALUE(@LastRecord, '$.SessionId')
                                  AND [dbo].[IS_EQUAL]([IsConfirmed], JSON_VALUE(@LastRecord, '$.IsConfirmed'), 'bit') = 1)
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Transactions'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.SessionId') = JSON_VALUE(@LastRecord, '$.SessionId')
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsConfirmed'), JSON_VALUE(@LastRecord, '$.IsConfirmed'), 'bit') = 1)
                THROW 51000, 'Registro de Transactions alterado por outro usuário', 1
        END

        IF @Action = 'delete' BEGIN
            IF EXISTS(SELECT 1 FROM [dbo].[Operations] WHERE [TransactionId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em Operations', 1
        END
        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_SessionId bigint = CAST(JSON_VALUE(@ActualRecord, '$.SessionId') AS bigint)
                   ,@W_IsConfirmed bit = CAST(JSON_VALUE(@ActualRecord, '$.IsConfirmed') AS bit)

            IF @W_SessionId IS NULL
                THROW 51000, 'Valor de SessionId em @ActualRecord é requerido.', 1
            IF @W_SessionId < CAST('1' AS bigint)
                THROW 51000, 'Valor de SessionId em @ActualRecord deve ser maior que ou igual a 1', 1
            IF (@W_SessionId IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM [dbo].[Sessions] WHERE [Id] = @W_SessionId)
                THROW 51000, 'Valor de FK em @ActualRecord inexiste em Sessions', 1
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[TransactionPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TransactionPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[TransactionPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[TransactionPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
               ,@W_Id bigint

    IF @Action = 'delete' BEGIN
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

    END ELSE BEGIN
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    END
    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Transactions'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Transactions', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[TransactionValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Transactions'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            SET IDENTITY_INSERT [dbo].[Operations] ON
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Transactions'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
            SET IDENTITY_INSERT [dbo].[Operations] OFF
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create'
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[TransactionValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @ActionAux = 'create'
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[TransactionsRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[TransactionsRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[TransactionsRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[TransactionsRead](@Login NVARCHAR(MAX)
                                          ,@Filter NVARCHAR(MAX)
                                          ,@Search NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

        IF @Filter IS NULL
            SET @Filter = '{}'
        ELSE IF ISJSON(@Filter) = 0
            THROW 51000, 'Valor de @Filter não está no formato JSON', 1
        IF @Search IS NULL
            SET @Search = '{}'
        ELSE IF ISJSON(@Search) = 0
            THROW 51000, 'Valor de @Search não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Transactions') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @SessionId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.SessionId') AS bigint) AS [SessionId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsConfirmed') AS bit) AS [IsConfirmed]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Transactions'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@Filter, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@ComparatorPredicate NVARCHAR(MAX)
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id bigint = CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)

        IF @WT_Id IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Id] = @T_Id'
        END
        IF @_ IS NULL BEGIN
            DECLARE @G_Id_comparator TINYINT
                   ,@G_Id_v bigint
                   ,@G_Id_vals NVARCHAR(MAX)
                   ,@G_Id_v1 bigint
                   ,@G_Id_v2 bigint

            SELECT @G_Id_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Id') IS NOT NULL AND JSON_QUERY(@Filter, '$.Id') IS NULL THEN 3 END
            )
                  ,@G_Id_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.value') AS bigint),
                TRY_CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)
            )
                  ,@G_Id_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Id.value'),
                JSON_QUERY(@Filter, '$.Id')
            )
            SELECT @G_Id_v1 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[0]') AS bigint)
                  ,@G_Id_v2 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[1]') AS bigint)

            IF @G_Id_comparator IS NOT NULL BEGIN
                IF (@G_Id_comparator = 1 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 2 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 3 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 4 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 5 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 6 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 7 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 8 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 9 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 10 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 11 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 12 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 13)
               OR (@G_Id_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_Id_comparator
        WHEN 1 THEN N'[T].[Id] < @Id'
        WHEN 2 THEN N'[T].[Id] <= @Id'
        WHEN 3 THEN N'[T].[Id] = @Id'
        WHEN 4 THEN N'[T].[Id] <> @Id'
        WHEN 5 THEN N'[T].[Id] >= @Id'
        WHEN 6 THEN N'[T].[Id] > @Id'
        WHEN 7 THEN N'[T].[Id] IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 8 THEN N'[T].[Id] NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 9 THEN N'[T].[Id] LIKE @Id'
        WHEN 10 THEN N'[T].[Id] NOT LIKE @Id'
        WHEN 11 THEN N'[T].[Id] BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'[T].[Id] NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'[T].[Id] IS NULL'
        WHEN 14 THEN N'[T].[Id] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
        END ELSE
            SET @Where = @Where + ' AND [T].[Id] IN (' + @_ + ')'

        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] bigint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[U].[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                              ,[T].[Id]
                                    FROM [dbo].[Transactions] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [T].[Id] = [#].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                              ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @_ IS NULL BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX)'
                               ,@T_Id = @WT_Id
                               ,@Id = @G_Id_v
                               ,@Id_v1 = @G_Id_v1
                               ,@Id_v2 = @G_Id_v2
                               ,@Id_vals = @G_Id_vals
        END ELSE BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint'
                               ,@T_Id = @WT_Id
        END

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            DECLARE @SearchRecno BIGINT = NULL
            IF EXISTS(SELECT 1 FROM OPENJSON(@Search)) BEGIN
                DECLARE @Recno BIGINT
                   ,@S_Id_comparator TINYINT
                   ,@S_Id_v bigint
                   ,@S_Id_vals NVARCHAR(MAX)
                   ,@S_Id_v1 bigint
                   ,@S_Id_v2 bigint

                SELECT @S_Id_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Id.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.Id') IS NOT NULL AND JSON_QUERY(@Search, '$.Id') IS NULL THEN 3 END
                )
                      ,@S_Id_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Id.value') AS bigint),
                    TRY_CAST(JSON_VALUE(@Search, '$.Id') AS bigint)
                )
                      ,@S_Id_vals = COALESCE(
                    JSON_QUERY(@Search, '$.Id.value'),
                    JSON_QUERY(@Search, '$.Id')
                )
                SELECT @S_Id_v1 = TRY_CAST(JSON_VALUE(@S_Id_vals, '$[0]') AS bigint)
                      ,@S_Id_v2 = TRY_CAST(JSON_VALUE(@S_Id_vals, '$[1]') AS bigint)

                SET @Where = ''
                IF @S_Id_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_Id_comparator = 1 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 2 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 3 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 4 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 5 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 6 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 7 AND @S_Id_vals IS NOT NULL)
               OR (@S_Id_comparator = 8 AND @S_Id_vals IS NOT NULL)
               OR (@S_Id_comparator = 9 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 10 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 11 AND @S_Id_v1 IS NOT NULL AND @S_Id_v2 IS NOT NULL)
               OR (@S_Id_comparator = 12 AND @S_Id_v1 IS NOT NULL AND @S_Id_v2 IS NOT NULL)
               OR (@S_Id_comparator = 13)
               OR (@S_Id_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_Id_comparator
        WHEN 1 THEN N'COALESCE([D].[Id], [O].[Id]) < @Id'
        WHEN 2 THEN N'COALESCE([D].[Id], [O].[Id]) <= @Id'
        WHEN 3 THEN N'COALESCE([D].[Id], [O].[Id]) = @Id'
        WHEN 4 THEN N'COALESCE([D].[Id], [O].[Id]) <> @Id'
        WHEN 5 THEN N'COALESCE([D].[Id], [O].[Id]) >= @Id'
        WHEN 6 THEN N'COALESCE([D].[Id], [O].[Id]) > @Id'
        WHEN 7 THEN N'COALESCE([D].[Id], [O].[Id]) IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 8 THEN N'COALESCE([D].[Id], [O].[Id]) NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 9 THEN N'COALESCE([D].[Id], [O].[Id]) LIKE @Id'
        WHEN 10 THEN N'COALESCE([D].[Id], [O].[Id]) NOT LIKE @Id'
        WHEN 11 THEN N'COALESCE([D].[Id], [O].[Id]) BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'COALESCE([D].[Id], [O].[Id]) NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'COALESCE([D].[Id], [O].[Id]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[Id], [O].[Id]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[Transactions] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX), @r BIGINT OUTPUT'
                                       ,@Id = @S_Id_v
                                       ,@Id_v1 = @S_Id_v1
                                       ,@Id_v2 = @S_Id_v2
                                       ,@Id_vals = @S_Id_vals
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS bigint) AS [SessionId]
                    ,CAST(NULL AS bit) AS [IsConfirmed]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''Transaction'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[SessionId]
                              ,[T].[IsConfirmed]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Transactions] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Transaction'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[SessionId]
                                  ,[O].[IsConfirmed]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'Session' AS [Kind]
              ,[R].[Id]
              ,[R].[SystemId]
              ,[R].[UserId]
              ,[R].[ClientRsaPublicKey]
              ,[R].[PublicKey]
              ,[R].[IsLogged]
            INTO [#Sessions]
            FROM [#result] [T]
                INNER JOIN [dbo].[Sessions] [R] ON [R].[Id] = [T].[SessionId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Sessions] ON [#Sessions]([Id])
        SELECT DISTINCT 'System' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Description]
              ,[R].[ClientName]
              ,[R].[MaxRetryLogins]
              ,[R].[IsOffAir]
            INTO [#Systems]
            FROM [#Sessions] [T]
                INNER JOIN [dbo].[Systems] [R] ON [R].[Id] = [T].[SystemId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Systems] ON [#Systems]([Id])
        SELECT DISTINCT 'User' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Password]
              ,[R].[FullName]
              ,[R].[RetryLogins]
              ,[R].[IsActive]
            INTO [#Users]
            FROM [#Sessions] [T]
                INNER JOIN [dbo].[Users] [R] ON [R].[Id] = [T].[UserId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Users] ON [#Users]([Id])
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[SessionId]
                      ,[IsConfirmed]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [Session].* FROM [#Sessions] AS [Session] FOR JSON PATH), '[]') AS [Session]
              ,ISNULL((SELECT [System].* FROM [#Systems] AS [System] FOR JSON PATH), '[]') AS [System]
              ,ISNULL((SELECT [User].* FROM [#Users] AS [User] FOR JSON PATH), '[]') AS [User]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[OperationValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[OperationValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[OperationValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[OperationValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id bigint

        IF @Action = 'delete' BEGIN
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

        END ELSE BEGIN
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        END
        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS bigint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[Operations] WHERE [Id] = @W_Id) AND @Action = 'create'
            THROW 51000, 'Chave-primária já existe em Operations', 1
        ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Operations'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND                                           CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create' AND NOT EXISTS(SELECT 1 FROM [dbo].[Operations] WHERE [Id] = @W_Id)
            THROW 51000, 'Chave-primária não existe em Operations', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [TransactionId] = JSON_VALUE(@LastRecord, '$.TransactionId')
                                  AND [TableName] = JSON_VALUE(@LastRecord, '$.TableName')
                                  AND [Action] = JSON_VALUE(@LastRecord, '$.Action')
                                  AND [dbo].[IS_EQUAL]([LastRecord], JSON_VALUE(@LastRecord, '$.LastRecord'), 'nvarchar(max)') = 1
                                  AND [ActualRecord] = JSON_VALUE(@LastRecord, '$.ActualRecord')
                                  AND [dbo].[IS_EQUAL]([IsConfirmed], JSON_VALUE(@LastRecord, '$.IsConfirmed'), 'bit') = 1)
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Operations'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.TransactionId') = JSON_VALUE(@LastRecord, '$.TransactionId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.TableName') = JSON_VALUE(@LastRecord, '$.TableName')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Action') = JSON_VALUE(@LastRecord, '$.Action')
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.LastRecord'), JSON_VALUE(@LastRecord, '$.LastRecord'), 'nvarchar(max)') = 1
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ActualRecord') = JSON_VALUE(@LastRecord, '$.ActualRecord')
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsConfirmed'), JSON_VALUE(@LastRecord, '$.IsConfirmed'), 'bit') = 1)
                THROW 51000, 'Registro de Operations alterado por outro usuário', 1
        END

        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_TransactionId bigint = CAST(JSON_VALUE(@ActualRecord, '$.TransactionId') AS bigint)
                   ,@W_TableName nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.TableName') AS nvarchar(25))
                   ,@W_Action nvarchar(15) = CAST(JSON_VALUE(@ActualRecord, '$.Action') AS nvarchar(15))
                   ,@W_LastRecord nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.LastRecord') AS nvarchar(max))
                   ,@W_ActualRecord nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.ActualRecord') AS nvarchar(max))
                   ,@W_IsConfirmed bit = CAST(JSON_VALUE(@ActualRecord, '$.IsConfirmed') AS bit)

            IF @W_TransactionId IS NULL
                THROW 51000, 'Valor de TransactionId em @ActualRecord é requerido.', 1
            IF @W_TransactionId < CAST('1' AS bigint)
                THROW 51000, 'Valor de TransactionId em @ActualRecord deve ser maior que ou igual a 1', 1
            IF @W_TableName IS NULL
                THROW 51000, 'Valor de TableName em @ActualRecord é requerido.', 1
            IF @W_Action IS NULL
                THROW 51000, 'Valor de Action em @ActualRecord é requerido.', 1
            IF @W_ActualRecord IS NULL
                THROW 51000, 'Valor de ActualRecord em @ActualRecord é requerido.', 1
            IF (@W_TransactionId IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @W_TransactionId)
                THROW 51000, 'Valor de FK em @ActualRecord inexiste em Transactions', 1
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[OperationPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[OperationPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[OperationPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[OperationPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
               ,@W_Id bigint

    IF @Action = 'delete' BEGIN
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

    END ELSE BEGIN
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    END
    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS bigint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Operations'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Operations', @NewId OUT
            SET @W_Id = CAST(@NewId AS bigint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[OperationValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Operations'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            SET IDENTITY_INSERT [dbo].[Operations] ON
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Operations'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
            SET IDENTITY_INSERT [dbo].[Operations] OFF
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create'
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[OperationValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @ActionAux = 'create'
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[OperationCreate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[OperationCreate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[OperationCreate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[OperationCreate](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'Operations'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'create'
            THROW 51000, 'Ação da operação é inválida para Create', 1
        EXEC @TransactionIdAux = [dbo].[OperationValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id bigint = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        DECLARE @W_TransactionId bigint = CAST(JSON_VALUE(@ActualRecord, '$.TransactionId') AS bigint)
               ,@W_TableName nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.TableName') AS nvarchar(25))
               ,@W_Action nvarchar(15) = CAST(JSON_VALUE(@ActualRecord, '$.Action') AS nvarchar(15))
               ,@W_LastRecord nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.LastRecord') AS nvarchar(max))
               ,@W_ActualRecord nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.ActualRecord') AS nvarchar(max))
               ,@W_IsConfirmed bit = CAST(JSON_VALUE(@ActualRecord, '$.IsConfirmed') AS bit)

        SET IDENTITY_INSERT [dbo].[Operations] ON
        INSERT INTO [dbo].[Operations] ([Id]
                                            ,[TransactionId]
                                            ,[TableName]
                                            ,[Action]
                                            ,[LastRecord]
                                            ,[ActualRecord]
                                            ,[IsConfirmed]
                                            ,[CreatedAt]
                                            ,[CreatedBy])
                                      VALUES (@W_Id
                                             ,@W_TransactionId
                                             ,@W_TableName
                                             ,@W_Action
                                             ,@W_LastRecord
                                             ,@W_ActualRecord
                                             ,@W_IsConfirmed
                                             ,GETDATE()
                                             ,@UserName)
        SET IDENTITY_INSERT [dbo].[Operations] OFF
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

