/**********************************************************************************
Criar stored procedure [dbo].[UnicitiesRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[UnicitiesRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[UnicitiesRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[UnicitiesRead](@Login NVARCHAR(MAX)
                                          ,@Filter NVARCHAR(MAX)
                                          ,@Search NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

        IF @Filter IS NULL
            SET @Filter = '{}'
        ELSE IF ISJSON(@Filter) = 0
            THROW 51000, 'Valor de @Filter não está no formato JSON', 1
        IF @Search IS NULL
            SET @Search = '{}'
        ELSE IF ISJSON(@Search) = 0
            THROW 51000, 'Valor de @Search não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Unicities') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @SessionId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ColumnId1') AS bigint) AS [ColumnId1]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ColumnId2') AS bigint) AS [ColumnId2]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsBidirectional') AS bit) AS [IsBidirectional]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Unicities'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@Filter, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@ComparatorPredicate NVARCHAR(MAX)
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id bigint = CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)
               ,@WT_ColumnId1 bigint = CAST(JSON_VALUE(@Filter, '$.ColumnId1') AS bigint)
               ,@WT_ColumnId2 bigint = CAST(JSON_VALUE(@Filter, '$.ColumnId2') AS bigint)
               ,@WT_IsBidirectional bit = CAST(JSON_VALUE(@Filter, '$.IsBidirectional') AS bit)

        IF @WT_Id IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Id] = @T_Id'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'ColumnId1' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[ColumnId1] IS NULL'
        ELSE IF @WT_ColumnId1 IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[ColumnId1] = @T_ColumnId1'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'ColumnId2' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[ColumnId2] IS NULL'
        ELSE IF @WT_ColumnId2 IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[ColumnId2] = @T_ColumnId2'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'IsBidirectional' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[IsBidirectional] IS NULL'
        ELSE IF @WT_IsBidirectional IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[IsBidirectional] = @T_IsBidirectional'
        END
        IF @_ IS NULL BEGIN
            DECLARE @G_Id_comparator TINYINT
                   ,@G_Id_v bigint
                   ,@G_Id_vals NVARCHAR(MAX)
                   ,@G_Id_v1 bigint
                   ,@G_Id_v2 bigint
                   ,@G_ColumnId1_comparator TINYINT
                   ,@G_ColumnId1_v bigint
                   ,@G_ColumnId1_vals NVARCHAR(MAX)
                   ,@G_ColumnId1_v1 bigint
                   ,@G_ColumnId1_v2 bigint
                   ,@G_ColumnId2_comparator TINYINT
                   ,@G_ColumnId2_v bigint
                   ,@G_ColumnId2_vals NVARCHAR(MAX)
                   ,@G_ColumnId2_v1 bigint
                   ,@G_ColumnId2_v2 bigint
                   ,@G_IsBidirectional_comparator TINYINT
                   ,@G_IsBidirectional_v bit
                   ,@G_IsBidirectional_vals NVARCHAR(MAX)
                   ,@G_IsBidirectional_v1 bit
                   ,@G_IsBidirectional_v2 bit

            SELECT @G_Id_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Id') IS NOT NULL AND JSON_QUERY(@Filter, '$.Id') IS NULL THEN 3 END
            )
                  ,@G_Id_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.value') AS bigint),
                TRY_CAST(JSON_VALUE(@Filter, '$.Id') AS bigint)
            )
                  ,@G_Id_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Id.value'),
                JSON_QUERY(@Filter, '$.Id')
            )
            SELECT @G_Id_v1 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[0]') AS bigint)
                  ,@G_Id_v2 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[1]') AS bigint)
            SELECT @G_ColumnId1_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.ColumnId1.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.ColumnId1') IS NOT NULL AND JSON_QUERY(@Filter, '$.ColumnId1') IS NULL THEN 3 END
            )
                  ,@G_ColumnId1_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.ColumnId1.value') AS bigint),
                TRY_CAST(JSON_VALUE(@Filter, '$.ColumnId1') AS bigint)
            )
                  ,@G_ColumnId1_vals = COALESCE(
                JSON_QUERY(@Filter, '$.ColumnId1.value'),
                JSON_QUERY(@Filter, '$.ColumnId1')
            )
            SELECT @G_ColumnId1_v1 = TRY_CAST(JSON_VALUE(@G_ColumnId1_vals, '$[0]') AS bigint)
                  ,@G_ColumnId1_v2 = TRY_CAST(JSON_VALUE(@G_ColumnId1_vals, '$[1]') AS bigint)
            SELECT @G_ColumnId2_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.ColumnId2.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.ColumnId2') IS NOT NULL AND JSON_QUERY(@Filter, '$.ColumnId2') IS NULL THEN 3 END
            )
                  ,@G_ColumnId2_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.ColumnId2.value') AS bigint),
                TRY_CAST(JSON_VALUE(@Filter, '$.ColumnId2') AS bigint)
            )
                  ,@G_ColumnId2_vals = COALESCE(
                JSON_QUERY(@Filter, '$.ColumnId2.value'),
                JSON_QUERY(@Filter, '$.ColumnId2')
            )
            SELECT @G_ColumnId2_v1 = TRY_CAST(JSON_VALUE(@G_ColumnId2_vals, '$[0]') AS bigint)
                  ,@G_ColumnId2_v2 = TRY_CAST(JSON_VALUE(@G_ColumnId2_vals, '$[1]') AS bigint)
            SELECT @G_IsBidirectional_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.IsBidirectional.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.IsBidirectional') IS NOT NULL AND JSON_QUERY(@Filter, '$.IsBidirectional') IS NULL THEN 3 END
            )
                  ,@G_IsBidirectional_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.IsBidirectional.value') AS bit),
                TRY_CAST(JSON_VALUE(@Filter, '$.IsBidirectional') AS bit)
            )
                  ,@G_IsBidirectional_vals = COALESCE(
                JSON_QUERY(@Filter, '$.IsBidirectional.value'),
                JSON_QUERY(@Filter, '$.IsBidirectional')
            )
            SELECT @G_IsBidirectional_v1 = TRY_CAST(JSON_VALUE(@G_IsBidirectional_vals, '$[0]') AS bit)
                  ,@G_IsBidirectional_v2 = TRY_CAST(JSON_VALUE(@G_IsBidirectional_vals, '$[1]') AS bit)

            IF @G_Id_comparator IS NOT NULL BEGIN
                IF (@G_Id_comparator = 1 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 2 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 3 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 4 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 5 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 6 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 7 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 8 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 9 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 10 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 11 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 12 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 13)
               OR (@G_Id_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_Id_comparator
        WHEN 1 THEN N'[T].[Id] < @Id'
        WHEN 2 THEN N'[T].[Id] <= @Id'
        WHEN 3 THEN N'[T].[Id] = @Id'
        WHEN 4 THEN N'[T].[Id] <> @Id'
        WHEN 5 THEN N'[T].[Id] >= @Id'
        WHEN 6 THEN N'[T].[Id] > @Id'
        WHEN 7 THEN N'[T].[Id] IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 8 THEN N'[T].[Id] NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@Id_vals))'
        WHEN 9 THEN N'[T].[Id] LIKE @Id'
        WHEN 10 THEN N'[T].[Id] NOT LIKE @Id'
        WHEN 11 THEN N'[T].[Id] BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'[T].[Id] NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'[T].[Id] IS NULL'
        WHEN 14 THEN N'[T].[Id] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'ColumnId1' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[ColumnId1] IS NULL'
            ELSE
            IF @G_ColumnId1_comparator IS NOT NULL BEGIN
                IF (@G_ColumnId1_comparator = 1 AND @G_ColumnId1_v IS NOT NULL)
               OR (@G_ColumnId1_comparator = 2 AND @G_ColumnId1_v IS NOT NULL)
               OR (@G_ColumnId1_comparator = 3 AND @G_ColumnId1_v IS NOT NULL)
               OR (@G_ColumnId1_comparator = 4 AND @G_ColumnId1_v IS NOT NULL)
               OR (@G_ColumnId1_comparator = 5 AND @G_ColumnId1_v IS NOT NULL)
               OR (@G_ColumnId1_comparator = 6 AND @G_ColumnId1_v IS NOT NULL)
               OR (@G_ColumnId1_comparator = 7 AND @G_ColumnId1_vals IS NOT NULL)
               OR (@G_ColumnId1_comparator = 8 AND @G_ColumnId1_vals IS NOT NULL)
               OR (@G_ColumnId1_comparator = 9 AND @G_ColumnId1_v IS NOT NULL)
               OR (@G_ColumnId1_comparator = 10 AND @G_ColumnId1_v IS NOT NULL)
               OR (@G_ColumnId1_comparator = 11 AND @G_ColumnId1_v1 IS NOT NULL AND @G_ColumnId1_v2 IS NOT NULL)
               OR (@G_ColumnId1_comparator = 12 AND @G_ColumnId1_v1 IS NOT NULL AND @G_ColumnId1_v2 IS NOT NULL)
               OR (@G_ColumnId1_comparator = 13)
               OR (@G_ColumnId1_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_ColumnId1_comparator
        WHEN 1 THEN N'[T].[ColumnId1] < @ColumnId1'
        WHEN 2 THEN N'[T].[ColumnId1] <= @ColumnId1'
        WHEN 3 THEN N'[T].[ColumnId1] = @ColumnId1'
        WHEN 4 THEN N'[T].[ColumnId1] <> @ColumnId1'
        WHEN 5 THEN N'[T].[ColumnId1] >= @ColumnId1'
        WHEN 6 THEN N'[T].[ColumnId1] > @ColumnId1'
        WHEN 7 THEN N'[T].[ColumnId1] IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@ColumnId1_vals))'
        WHEN 8 THEN N'[T].[ColumnId1] NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@ColumnId1_vals))'
        WHEN 9 THEN N'[T].[ColumnId1] LIKE @ColumnId1'
        WHEN 10 THEN N'[T].[ColumnId1] NOT LIKE @ColumnId1'
        WHEN 11 THEN N'[T].[ColumnId1] BETWEEN @ColumnId1_v1 AND @ColumnId1_v2'
        WHEN 12 THEN N'[T].[ColumnId1] NOT BETWEEN @ColumnId1_v1 AND @ColumnId1_v2'
        WHEN 13 THEN N'[T].[ColumnId1] IS NULL'
        WHEN 14 THEN N'[T].[ColumnId1] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'ColumnId2' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[ColumnId2] IS NULL'
            ELSE
            IF @G_ColumnId2_comparator IS NOT NULL BEGIN
