        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] bigint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[U].[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                              ,[T].[Id]
                                    FROM [dbo].[Unicities] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [T].[Id] = [#].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                              ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @_ IS NULL BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id bigint,@T_ColumnId1 bigint,@T_ColumnId2 bigint,@T_IsBidirectional bit,@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@ColumnId1 bigint,@ColumnId1_v1 bigint,@ColumnId1_v2 bigint,@ColumnId1_vals NVARCHAR(MAX),@ColumnId2 bigint,@ColumnId2_v1 bigint,@ColumnId2_v2 bigint,@ColumnId2_vals NVARCHAR(MAX),@IsBidirectional bit,@IsBidirectional_v1 bit,@IsBidirectional_v2 bit,@IsBidirectional_vals NVARCHAR(MAX)'
                               ,@T_Id = @WT_Id
                               ,@T_ColumnId1 = @WT_ColumnId1
                               ,@T_ColumnId2 = @WT_ColumnId2
                               ,@T_IsBidirectional = @WT_IsBidirectional
                               ,@Id = @G_Id_v
                               ,@Id_v1 = @G_Id_v1
                               ,@Id_v2 = @G_Id_v2
                               ,@Id_vals = @G_Id_vals
                               ,@ColumnId1 = @G_ColumnId1_v
                               ,@ColumnId1_v1 = @G_ColumnId1_v1
                               ,@ColumnId1_v2 = @G_ColumnId1_v2
                               ,@ColumnId1_vals = @G_ColumnId1_vals
                               ,@ColumnId2 = @G_ColumnId2_v
                               ,@ColumnId2_v1 = @G_ColumnId2_v1
                               ,@ColumnId2_v2 = @G_ColumnId2_v2
                               ,@ColumnId2_vals = @G_ColumnId2_vals
                               ,@IsBidirectional = @G_IsBidirectional_v
                               ,@IsBidirectional_v1 = @G_IsBidirectional_v1
                               ,@IsBidirectional_v2 = @G_IsBidirectional_v2
                               ,@IsBidirectional_vals = @G_IsBidirectional_vals
        END ELSE BEGIN
