               OR (@S_IsBidirectional_comparator = 10 AND @S_IsBidirectional_v IS NOT NULL)
               OR (@S_IsBidirectional_comparator = 11 AND @S_IsBidirectional_v1 IS NOT NULL AND @S_IsBidirectional_v2 IS NOT NULL)
               OR (@S_IsBidirectional_comparator = 12 AND @S_IsBidirectional_v1 IS NOT NULL AND @S_IsBidirectional_v2 IS NOT NULL)
               OR (@S_IsBidirectional_comparator = 13)
               OR (@S_IsBidirectional_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_IsBidirectional_comparator
        WHEN 1 THEN N'COALESCE([D].[IsBidirectional], [O].[IsBidirectional]) < @IsBidirectional'
        WHEN 2 THEN N'COALESCE([D].[IsBidirectional], [O].[IsBidirectional]) <= @IsBidirectional'
        WHEN 3 THEN N'COALESCE([D].[IsBidirectional], [O].[IsBidirectional]) = @IsBidirectional'
        WHEN 4 THEN N'COALESCE([D].[IsBidirectional], [O].[IsBidirectional]) <> @IsBidirectional'
        WHEN 5 THEN N'COALESCE([D].[IsBidirectional], [O].[IsBidirectional]) >= @IsBidirectional'
        WHEN 6 THEN N'COALESCE([D].[IsBidirectional], [O].[IsBidirectional]) > @IsBidirectional'
        WHEN 7 THEN N'COALESCE([D].[IsBidirectional], [O].[IsBidirectional]) IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsBidirectional_vals))'
        WHEN 8 THEN N'COALESCE([D].[IsBidirectional], [O].[IsBidirectional]) NOT IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsBidirectional_vals))'
        WHEN 9 THEN N'COALESCE([D].[IsBidirectional], [O].[IsBidirectional]) LIKE @IsBidirectional'
        WHEN 10 THEN N'COALESCE([D].[IsBidirectional], [O].[IsBidirectional]) NOT LIKE @IsBidirectional'
        WHEN 11 THEN N'COALESCE([D].[IsBidirectional], [O].[IsBidirectional]) BETWEEN @IsBidirectional_v1 AND @IsBidirectional_v2'
        WHEN 12 THEN N'COALESCE([D].[IsBidirectional], [O].[IsBidirectional]) NOT BETWEEN @IsBidirectional_v1 AND @IsBidirectional_v2'
        WHEN 13 THEN N'COALESCE([D].[IsBidirectional], [O].[IsBidirectional]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[IsBidirectional], [O].[IsBidirectional]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[Unicities] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@ColumnId1 bigint,@ColumnId1_v1 bigint,@ColumnId1_v2 bigint,@ColumnId1_vals NVARCHAR(MAX),@ColumnId2 bigint,@ColumnId2_v1 bigint,@ColumnId2_v2 bigint,@ColumnId2_vals NVARCHAR(MAX),@IsBidirectional bit,@IsBidirectional_v1 bit,@IsBidirectional_v2 bit,@IsBidirectional_vals NVARCHAR(MAX), @r BIGINT OUTPUT'
                                       ,@Id = @S_Id_v
                                       ,@Id_v1 = @S_Id_v1
                                       ,@Id_v2 = @S_Id_v2
                                       ,@Id_vals = @S_Id_vals
                                       ,@ColumnId1 = @S_ColumnId1_v
                                       ,@ColumnId1_v1 = @S_ColumnId1_v1
                                       ,@ColumnId1_v2 = @S_ColumnId1_v2
                                       ,@ColumnId1_vals = @S_ColumnId1_vals
                                       ,@ColumnId2 = @S_ColumnId2_v
                                       ,@ColumnId2_v1 = @S_ColumnId2_v1
                                       ,@ColumnId2_v2 = @S_ColumnId2_v2
                                       ,@ColumnId2_vals = @S_ColumnId2_vals
                                       ,@IsBidirectional = @S_IsBidirectional_v
                                       ,@IsBidirectional_v1 = @S_IsBidirectional_v1
                                       ,@IsBidirectional_v2 = @S_IsBidirectional_v2
                                       ,@IsBidirectional_vals = @S_IsBidirectional_vals
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS bigint) AS [ColumnId1]
                    ,CAST(NULL AS bigint) AS [ColumnId2]
                    ,CAST(NULL AS bit) AS [IsBidirectional]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''Unicity'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[ColumnId1]
                              ,[T].[ColumnId2]
                              ,[T].[IsBidirectional]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Unicities] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Unicity'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[ColumnId1]
                                  ,[O].[ColumnId2]
                                  ,[O].[IsBidirectional]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'Column' AS [Kind]
              ,[R].[Id]
              ,[R].[TableId]
              ,[R].[Sequence]
              ,[R].[DomainId]
              ,[R].[Name]
              ,[R].[Alias]
              ,[R].[Description]
              ,[R].[Title]
              ,[R].[Caption]
              ,[R].[Default]
              ,[R].[Minimum]
              ,[R].[Maximum]
              ,[R].[IsPrimarykey]
              ,[R].[IsAutoIncrement]
              ,[R].[IsRequired]
              ,[R].[IsListable]
              ,[R].[IsFilterable]
              ,[R].[IsEditable]
              ,[R].[IsGridable]
              ,[R].[IsEncrypted]
              ,[R].[IsInWords]
              ,[R].[IsVirtual]
            INTO [#Columns]
            FROM [#result] [T]
                INNER JOIN [dbo].[Columns] [R] ON [R].[Id] = [T].[ColumnId1]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Columns] ON [#Columns]([Id])
        SELECT DISTINCT 'Table' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Alias]
              ,[R].[Description]
              ,[R].[CurrentId]
            INTO [#Tables]
            FROM [#Columns] [T]
                INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[TableId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Tables] ON [#Tables]([Id])
        SELECT DISTINCT 'Domain' AS [Kind]
              ,[R].[Id]
              ,[R].[TypeId]
              ,[R].[MaskId]
              ,[R].[Name]
              ,[R].[Length]
              ,[R].[Decimals]
              ,[R].[ValidValues]
              ,[R].[Default]
              ,[R].[Minimum]
              ,[R].[Maximum]
              ,[R].[Codification]
            INTO [#Domains]
            FROM [#Columns] [T]
                INNER JOIN [dbo].[Domains] [R] ON [R].[Id] = [T].[DomainId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Domains] ON [#Domains]([Id])
        SELECT DISTINCT 'Type' AS [Kind]
              ,[R].[Id]
              ,[R].[CategoryId]
              ,[R].[Name]
              ,[R].[MaxLength]
              ,[R].[Minimum]
              ,[R].[Maximum]
              ,[R].[AskLength]
              ,[R].[AskDecimals]
              ,[R].[AskPrimarykey]
              ,[R].[AskAutoincrement]
              ,[R].[AskFilterable]
              ,[R].[AskGridable]
              ,[R].[AskCodification]
              ,[R].[IsLikeable]
              ,[R].[IsActive]
            INTO [#Types]
            FROM [#Domains] [T]
                INNER JOIN [dbo].[Types] [R] ON [R].[Id] = [T].[TypeId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Types] ON [#Types]([Id])
        SELECT DISTINCT 'Category' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[HtmlInputType]
              ,[R].[HtmlInputAlign]
              ,[R].[AskEncrypted]
              ,[R].[AskMask]
              ,[R].[AskListable]
              ,[R].[AskDefault]
              ,[R].[AskMinimum]
              ,[R].[AskMaximum]
              ,[R].[AskInWords]
            INTO [#Categories]
            FROM [#Types] [T]
                INNER JOIN [dbo].[Categories] [R] ON [R].[Id] = [T].[CategoryId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Categories] ON [#Categories]([Id])
        SELECT DISTINCT 'Mask' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[Mask]
            INTO [#Masks]
            FROM [#Domains] [T]
                INNER JOIN [dbo].[Masks] [R] ON [R].[Id] = [T].[MaskId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Masks] ON [#Masks]([Id])
        INSERT INTO [#Columns]
            SELECT DISTINCT 'Column' AS [Kind]
                  ,[R].[Id]
                  ,[R].[TableId]
                  ,[R].[Sequence]
                  ,[R].[DomainId]
                  ,[R].[Name]
                  ,[R].[Alias]
                  ,[R].[Description]
                  ,[R].[Title]
                  ,[R].[Caption]
                  ,[R].[Default]
                  ,[R].[Minimum]
                  ,[R].[Maximum]
                  ,[R].[IsPrimarykey]
                  ,[R].[IsAutoIncrement]
                  ,[R].[IsRequired]
                  ,[R].[IsListable]
                  ,[R].[IsFilterable]
                  ,[R].[IsEditable]
                  ,[R].[IsGridable]
                  ,[R].[IsEncrypted]
                  ,[R].[IsInWords]
                  ,[R].[IsVirtual]
                FROM [#result] [T]
                    INNER JOIN [dbo].[Columns] [R] ON [R].[Id] = [T].[ColumnId2]
                WHERE NOT EXISTS(SELECT 1 FROM [#Columns] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        INSERT INTO [#Tables]
            SELECT DISTINCT 'Table' AS [Kind]
                  ,[R].[Id]
                  ,[R].[Name]
                  ,[R].[Alias]
                  ,[R].[Description]
                  ,[R].[CurrentId]
                FROM [#Columns] [T]
                    INNER JOIN [dbo].[Tables] [R] ON [R].[Id] = [T].[TableId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Tables] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        INSERT INTO [#Domains]
            SELECT DISTINCT 'Domain' AS [Kind]
                  ,[R].[Id]
                  ,[R].[TypeId]
                  ,[R].[MaskId]
                  ,[R].[Name]
                  ,[R].[Length]
                  ,[R].[Decimals]
                  ,[R].[ValidValues]
                  ,[R].[Default]
                  ,[R].[Minimum]
                  ,[R].[Maximum]
                  ,[R].[Codification]
                FROM [#Columns] [T]
                    INNER JOIN [dbo].[Domains] [R] ON [R].[Id] = [T].[DomainId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Domains] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        INSERT INTO [#Types]
            SELECT DISTINCT 'Type' AS [Kind]
                  ,[R].[Id]
                  ,[R].[CategoryId]
                  ,[R].[Name]
                  ,[R].[MaxLength]
                  ,[R].[Minimum]
                  ,[R].[Maximum]
                  ,[R].[AskLength]
                  ,[R].[AskDecimals]
                  ,[R].[AskPrimarykey]
                  ,[R].[AskAutoincrement]
                  ,[R].[AskFilterable]
                  ,[R].[AskGridable]
                  ,[R].[AskCodification]
                  ,[R].[IsLikeable]
                  ,[R].[IsActive]
                FROM [#Domains] [T]
                    INNER JOIN [dbo].[Types] [R] ON [R].[Id] = [T].[TypeId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Types] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        INSERT INTO [#Categories]
            SELECT DISTINCT 'Category' AS [Kind]
                  ,[R].[Id]
                  ,[R].[Name]
                  ,[R].[HtmlInputType]
                  ,[R].[HtmlInputAlign]
                  ,[R].[AskEncrypted]
                  ,[R].[AskMask]
                  ,[R].[AskListable]
                  ,[R].[AskDefault]
                  ,[R].[AskMinimum]
                  ,[R].[AskMaximum]
                  ,[R].[AskInWords]
                FROM [#Types] [T]
                    INNER JOIN [dbo].[Categories] [R] ON [R].[Id] = [T].[CategoryId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Categories] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        INSERT INTO [#Masks]
            SELECT DISTINCT 'Mask' AS [Kind]
                  ,[R].[Id]
                  ,[R].[Name]
                  ,[R].[Mask]
                FROM [#Domains] [T]
                    INNER JOIN [dbo].[Masks] [R] ON [R].[Id] = [T].[MaskId]
                WHERE NOT EXISTS(SELECT 1 FROM [#Masks] WHERE [Id] = [R].[Id])
                ORDER BY [R].[Id]
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[ColumnId1]
                      ,[ColumnId2]
                      ,[IsBidirectional]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [Column].* FROM [#Columns] AS [Column] FOR JSON PATH), '[]') AS [Column]
              ,ISNULL((SELECT [Table].* FROM [#Tables] AS [Table] FOR JSON PATH), '[]') AS [Table]
              ,ISNULL((SELECT [Domain].* FROM [#Domains] AS [Domain] FOR JSON PATH), '[]') AS [Domain]
              ,ISNULL((SELECT [Type].* FROM [#Types] AS [Type] FOR JSON PATH), '[]') AS [Type]
              ,ISNULL((SELECT [Category].* FROM [#Categories] AS [Category] FOR JSON PATH), '[]') AS [Category]
              ,ISNULL((SELECT [Mask].* FROM [#Masks] AS [Mask] FOR JSON PATH), '[]') AS [Mask]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[ComparatorValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[ComparatorValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[ComparatorValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[ComparatorValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id tinyint

        IF @Action = 'delete' BEGIN
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS tinyint)

        END ELSE BEGIN
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS tinyint)

        END
        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS tinyint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[Comparators] WHERE [Id] = @W_Id) AND @Action = 'create'
            THROW 51000, 'Chave-primária já existe em Comparators', 1
        ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Comparators'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND                                           CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS tinyint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create' AND NOT EXISTS(SELECT 1 FROM [dbo].[Comparators] WHERE [Id] = @W_Id)
            THROW 51000, 'Chave-primária não existe em Comparators', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Comparators]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [Symbol] = JSON_VALUE(@LastRecord, '$.Symbol')
                                  AND [Description] = JSON_VALUE(@LastRecord, '$.Description')
                                  AND [dbo].[IS_EQUAL]([Arity], JSON_VALUE(@LastRecord, '$.Arity'), 'tinyint') = 1)
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Comparators'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Symbol') = JSON_VALUE(@LastRecord, '$.Symbol')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Description') = JSON_VALUE(@LastRecord, '$.Description')
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Arity'), JSON_VALUE(@LastRecord, '$.Arity'), 'tinyint') = 1)
                THROW 51000, 'Registro de Comparators alterado por outro usuário', 1
        END

        IF @Action = 'delete' BEGIN
            IF EXISTS(SELECT 1 FROM [dbo].[Rules] WHERE [ComparatorId] = @W_Id)
                THROW 51000, 'Chave-primária referenciada em Rules', 1
        END
        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_Symbol nchar(1) = CAST(JSON_VALUE(@ActualRecord, '$.Symbol') AS nchar(1))
                   ,@W_Description nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Description') AS nvarchar(50))
                   ,@W_Arity tinyint = CAST(JSON_VALUE(@ActualRecord, '$.Arity') AS tinyint)

            IF @W_Symbol IS NULL
                THROW 51000, 'Valor de Symbol em @ActualRecord é requerido.', 1
            IF @W_Description IS NULL
                THROW 51000, 'Valor de Description em @ActualRecord é requerido.', 1
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[ComparatorPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[ComparatorPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[ComparatorPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[ComparatorPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
               ,@W_Id tinyint

    IF @Action = 'delete' BEGIN
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS tinyint)

    END ELSE BEGIN
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS tinyint)

    END
    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS tinyint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Comparators'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Comparators', @NewId OUT
            SET @W_Id = CAST(@NewId AS tinyint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[ComparatorValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Comparators'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS tinyint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            SET IDENTITY_INSERT [dbo].[Operations] ON
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Comparators'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
            SET IDENTITY_INSERT [dbo].[Operations] OFF
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create'
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[ComparatorValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @ActionAux = 'create'
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[ComparatorCreate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[ComparatorCreate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[ComparatorCreate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[ComparatorCreate](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'Comparators'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'create'
            THROW 51000, 'Ação da operação é inválida para Create', 1
        EXEC @TransactionIdAux = [dbo].[ComparatorValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id tinyint = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS tinyint)

        DECLARE @W_Symbol nchar(1) = CAST(JSON_VALUE(@ActualRecord, '$.Symbol') AS nchar(1))
               ,@W_Description nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Description') AS nvarchar(50))
               ,@W_Arity tinyint = CAST(JSON_VALUE(@ActualRecord, '$.Arity') AS tinyint)

        SET IDENTITY_INSERT [dbo].[Comparators] ON
        INSERT INTO [dbo].[Comparators] ([Id]
                                            ,[Symbol]
                                            ,[Description]
                                            ,[Arity]
                                            ,[CreatedAt]
                                            ,[CreatedBy])
                                      VALUES (@W_Id
                                             ,@W_Symbol
                                             ,@W_Description
                                             ,@W_Arity
                                             ,GETDATE()
                                             ,@UserName)
        SET IDENTITY_INSERT [dbo].[Comparators] OFF
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

