ALTER PROCEDURE [dbo].[ComparatorsRead](@Login NVARCHAR(MAX)
                                          ,@Filter NVARCHAR(MAX)
                                          ,@Search NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

        IF @Filter IS NULL
            SET @Filter = '{}'
        ELSE IF ISJSON(@Filter) = 0
            THROW 51000, 'Valor de @Filter não está no formato JSON', 1
        IF @Search IS NULL
            SET @Search = '{}'
        ELSE IF ISJSON(@Search) = 0
            THROW 51000, 'Valor de @Search não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Comparators') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END
        IF @IsActionList = 1
            SET @OrderBy = '[T].[Symbol] ASC, [T].[Id] ASC'
        DECLARE @PickerValue nchar(1) = NULL

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @SessionId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS tinyint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Symbol') AS nchar(1)) AS [Symbol]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Description') AS nvarchar(50)) AS [Description]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Arity') AS tinyint) AS [Arity]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Comparators'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@Filter, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@ComparatorPredicate NVARCHAR(MAX)
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id tinyint = CAST(JSON_VALUE(@Filter, '$.Id') AS tinyint)
               ,@WT_Symbol nchar(1) = CAST(JSON_VALUE(@Filter, '$.Symbol') AS nchar(1))
               ,@WT_Description nvarchar(50) = CAST(JSON_VALUE(@Filter, '$.Description') AS nvarchar(50))
               ,@WT_Arity tinyint = CAST(JSON_VALUE(@Filter, '$.Arity') AS tinyint)

        IF @WT_Id IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Id] = @T_Id'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'Symbol' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Symbol] IS NULL'
        ELSE IF @WT_Symbol IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Symbol] = @T_Symbol'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'Description' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Description] IS NULL'
        ELSE IF @WT_Description IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Description] = @T_Description'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'Arity' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[Arity] IS NULL'
        ELSE IF @WT_Arity IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Arity] = @T_Arity'
        END
        IF @IsActionList = 1 BEGIN
            SET @PickerValue = CAST(JSON_VALUE(@Filter, '$.Picker.Value') AS nchar(1))
            IF @PickerValue IS NULL
                SET @PickerValue = ''
            SET @Where = @Where + ' AND [T].[Symbol] LIKE ''%'' + @PickerValue + ''%'''
        END ELSE IF @_ IS NULL BEGIN
            DECLARE @G_Id_comparator TINYINT
                   ,@G_Id_v tinyint
                   ,@G_Id_vals NVARCHAR(MAX)
                   ,@G_Id_v1 tinyint
                   ,@G_Id_v2 tinyint
                   ,@G_Symbol_comparator TINYINT
                   ,@G_Symbol_v nchar(1)
                   ,@G_Symbol_vals NVARCHAR(MAX)
                   ,@G_Symbol_v1 nchar(1)
                   ,@G_Symbol_v2 nchar(1)
                   ,@G_Description_comparator TINYINT
                   ,@G_Description_v nvarchar(50)
                   ,@G_Description_vals NVARCHAR(MAX)
                   ,@G_Description_v1 nvarchar(50)
                   ,@G_Description_v2 nvarchar(50)
                   ,@G_Arity_comparator TINYINT
                   ,@G_Arity_v tinyint
                   ,@G_Arity_vals NVARCHAR(MAX)
                   ,@G_Arity_v1 tinyint
                   ,@G_Arity_v2 tinyint

            SELECT @G_Id_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Id') IS NOT NULL AND JSON_QUERY(@Filter, '$.Id') IS NULL THEN 3 END
            )
                  ,@G_Id_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.value') AS tinyint),
                TRY_CAST(JSON_VALUE(@Filter, '$.Id') AS tinyint)
            )
                  ,@G_Id_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Id.value'),
                JSON_QUERY(@Filter, '$.Id')
            )
            SELECT @G_Id_v1 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[0]') AS tinyint)
                  ,@G_Id_v2 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[1]') AS tinyint)
            SELECT @G_Symbol_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Symbol.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Symbol') IS NOT NULL AND JSON_QUERY(@Filter, '$.Symbol') IS NULL THEN 3 END
            )
                  ,@G_Symbol_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Symbol.value') AS nchar(1)),
                TRY_CAST(JSON_VALUE(@Filter, '$.Symbol') AS nchar(1))
            )
                  ,@G_Symbol_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Symbol.value'),
                JSON_QUERY(@Filter, '$.Symbol')
            )
            SELECT @G_Symbol_v1 = TRY_CAST(JSON_VALUE(@G_Symbol_vals, '$[0]') AS nchar(1))
                  ,@G_Symbol_v2 = TRY_CAST(JSON_VALUE(@G_Symbol_vals, '$[1]') AS nchar(1))
            SELECT @G_Description_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Description.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Description') IS NOT NULL AND JSON_QUERY(@Filter, '$.Description') IS NULL THEN 3 END
            )
                  ,@G_Description_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Description.value') AS nvarchar(50)),
                TRY_CAST(JSON_VALUE(@Filter, '$.Description') AS nvarchar(50))
            )
                  ,@G_Description_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Description.value'),
                JSON_QUERY(@Filter, '$.Description')
            )
            SELECT @G_Description_v1 = TRY_CAST(JSON_VALUE(@G_Description_vals, '$[0]') AS nvarchar(50))
                  ,@G_Description_v2 = TRY_CAST(JSON_VALUE(@G_Description_vals, '$[1]') AS nvarchar(50))
            SELECT @G_Arity_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Arity.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Arity') IS NOT NULL AND JSON_QUERY(@Filter, '$.Arity') IS NULL THEN 3 END
            )
                  ,@G_Arity_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Arity.value') AS tinyint),
                TRY_CAST(JSON_VALUE(@Filter, '$.Arity') AS tinyint)
            )
                  ,@G_Arity_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Arity.value'),
                JSON_QUERY(@Filter, '$.Arity')
            )
            SELECT @G_Arity_v1 = TRY_CAST(JSON_VALUE(@G_Arity_vals, '$[0]') AS tinyint)
                  ,@G_Arity_v2 = TRY_CAST(JSON_VALUE(@G_Arity_vals, '$[1]') AS tinyint)

            IF @G_Id_comparator IS NOT NULL BEGIN
                IF (@G_Id_comparator = 1 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 2 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 3 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 4 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 5 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 6 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 7 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 8 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 9 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 10 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 11 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 12 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 13)
               OR (@G_Id_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_Id_comparator
        WHEN 1 THEN N'[T].[Id] < @Id'
        WHEN 2 THEN N'[T].[Id] <= @Id'
        WHEN 3 THEN N'[T].[Id] = @Id'
        WHEN 4 THEN N'[T].[Id] <> @Id'
        WHEN 5 THEN N'[T].[Id] >= @Id'
        WHEN 6 THEN N'[T].[Id] > @Id'
        WHEN 7 THEN N'[T].[Id] IN (SELECT CAST([value] AS tinyint) FROM OPENJSON(@Id_vals))'
        WHEN 8 THEN N'[T].[Id] NOT IN (SELECT CAST([value] AS tinyint) FROM OPENJSON(@Id_vals))'
        WHEN 9 THEN N'[T].[Id] LIKE @Id'
        WHEN 10 THEN N'[T].[Id] NOT LIKE @Id'
        WHEN 11 THEN N'[T].[Id] BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'[T].[Id] NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'[T].[Id] IS NULL'
        WHEN 14 THEN N'[T].[Id] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'Symbol' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[Symbol] IS NULL'
            ELSE
            IF @G_Symbol_comparator IS NOT NULL BEGIN
                IF (@G_Symbol_comparator = 1 AND @G_Symbol_v IS NOT NULL)
               OR (@G_Symbol_comparator = 2 AND @G_Symbol_v IS NOT NULL)
               OR (@G_Symbol_comparator = 3 AND @G_Symbol_v IS NOT NULL)
               OR (@G_Symbol_comparator = 4 AND @G_Symbol_v IS NOT NULL)
               OR (@G_Symbol_comparator = 5 AND @G_Symbol_v IS NOT NULL)
               OR (@G_Symbol_comparator = 6 AND @G_Symbol_v IS NOT NULL)
               OR (@G_Symbol_comparator = 7 AND @G_Symbol_vals IS NOT NULL)
               OR (@G_Symbol_comparator = 8 AND @G_Symbol_vals IS NOT NULL)
               OR (@G_Symbol_comparator = 9 AND @G_Symbol_v IS NOT NULL)
               OR (@G_Symbol_comparator = 10 AND @G_Symbol_v IS NOT NULL)
               OR (@G_Symbol_comparator = 11 AND @G_Symbol_v1 IS NOT NULL AND @G_Symbol_v2 IS NOT NULL)
               OR (@G_Symbol_comparator = 12 AND @G_Symbol_v1 IS NOT NULL AND @G_Symbol_v2 IS NOT NULL)
               OR (@G_Symbol_comparator = 13)
               OR (@G_Symbol_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_Symbol_comparator
        WHEN 1 THEN N'[T].[Symbol] < @Symbol'
        WHEN 2 THEN N'[T].[Symbol] <= @Symbol'
        WHEN 3 THEN N'[T].[Symbol] = @Symbol'
        WHEN 4 THEN N'[T].[Symbol] <> @Symbol'
        WHEN 5 THEN N'[T].[Symbol] >= @Symbol'
        WHEN 6 THEN N'[T].[Symbol] > @Symbol'
        WHEN 7 THEN N'[T].[Symbol] IN (SELECT CAST([value] AS nchar(1)) FROM OPENJSON(@Symbol_vals))'
        WHEN 8 THEN N'[T].[Symbol] NOT IN (SELECT CAST([value] AS nchar(1)) FROM OPENJSON(@Symbol_vals))'
        WHEN 9 THEN N'[T].[Symbol] LIKE @Symbol'
        WHEN 10 THEN N'[T].[Symbol] NOT LIKE @Symbol'
        WHEN 11 THEN N'[T].[Symbol] BETWEEN @Symbol_v1 AND @Symbol_v2'
        WHEN 12 THEN N'[T].[Symbol] NOT BETWEEN @Symbol_v1 AND @Symbol_v2'
        WHEN 13 THEN N'[T].[Symbol] IS NULL'
        WHEN 14 THEN N'[T].[Symbol] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'Description' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[Description] IS NULL'
            ELSE
            IF @G_Description_comparator IS NOT NULL BEGIN
                IF (@G_Description_comparator = 1 AND @G_Description_v IS NOT NULL)
               OR (@G_Description_comparator = 2 AND @G_Description_v IS NOT NULL)
               OR (@G_Description_comparator = 3 AND @G_Description_v IS NOT NULL)
               OR (@G_Description_comparator = 4 AND @G_Description_v IS NOT NULL)
               OR (@G_Description_comparator = 5 AND @G_Description_v IS NOT NULL)
               OR (@G_Description_comparator = 6 AND @G_Description_v IS NOT NULL)
               OR (@G_Description_comparator = 7 AND @G_Description_vals IS NOT NULL)
               OR (@G_Description_comparator = 8 AND @G_Description_vals IS NOT NULL)
