                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id tinyint,@Id_v1 tinyint,@Id_v2 tinyint,@Id_vals NVARCHAR(MAX),@Symbol nchar(1),@Symbol_v1 nchar(1),@Symbol_v2 nchar(1),@Symbol_vals NVARCHAR(MAX),@Description nvarchar(50),@Description_v1 nvarchar(50),@Description_v2 nvarchar(50),@Description_vals NVARCHAR(MAX),@Arity tinyint,@Arity_v1 tinyint,@Arity_v2 tinyint,@Arity_vals NVARCHAR(MAX), @r BIGINT OUTPUT'
                                       ,@Id = @S_Id_v
                                       ,@Id_v1 = @S_Id_v1
                                       ,@Id_v2 = @S_Id_v2
                                       ,@Id_vals = @S_Id_vals
                                       ,@Symbol = @S_Symbol_v
                                       ,@Symbol_v1 = @S_Symbol_v1
                                       ,@Symbol_v2 = @S_Symbol_v2
                                       ,@Symbol_vals = @S_Symbol_vals
                                       ,@Description = @S_Description_v
                                       ,@Description_v1 = @S_Description_v1
                                       ,@Description_v2 = @S_Description_v2
                                       ,@Description_vals = @S_Description_vals
                                       ,@Arity = @S_Arity_v
                                       ,@Arity_v1 = @S_Arity_v1
                                       ,@Arity_v2 = @S_Arity_v2
                                       ,@Arity_vals = @S_Arity_vals
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS tinyint) AS [Id]
                    ,CAST(NULL AS nchar(1)) AS [Symbol]
                    ,CAST(NULL AS nvarchar(50)) AS [Description]
                    ,CAST(NULL AS tinyint) AS [Arity]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''Comparator'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[Symbol]
                              ,[T].[Description]
                              ,[T].[Arity]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Comparators] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Comparator'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[Symbol]
                                  ,[O].[Description]
                                  ,[O].[Arity]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[Symbol]
                      ,[Symbol] AS [ListItemValue]
                      ,[Description]
                      ,[Arity]
                    FROM [#result] FOR JSON PATH) AS [result]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[RuleValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[RuleValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[RuleValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[RuleValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id tinyint

        IF @Action = 'delete' BEGIN
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS tinyint)

        END ELSE BEGIN
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS tinyint)

        END
        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS tinyint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[Rules] WHERE [Id] = @W_Id) AND @Action = 'create'
            THROW 51000, 'Chave-primária já existe em Rules', 1
        ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Rules'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND                                           CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS tinyint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create' AND NOT EXISTS(SELECT 1 FROM [dbo].[Rules] WHERE [Id] = @W_Id)
            THROW 51000, 'Chave-primária não existe em Rules', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Rules]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [CategoryId] = JSON_VALUE(@LastRecord, '$.CategoryId')
                                  AND [ComparatorId] = JSON_VALUE(@LastRecord, '$.ComparatorId'))
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Rules'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.CategoryId') = JSON_VALUE(@LastRecord, '$.CategoryId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ComparatorId') = JSON_VALUE(@LastRecord, '$.ComparatorId'))
                THROW 51000, 'Registro de Rules alterado por outro usuário', 1
        END

        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_CategoryId tinyint = CAST(JSON_VALUE(@ActualRecord, '$.CategoryId') AS tinyint)
                   ,@W_ComparatorId tinyint = CAST(JSON_VALUE(@ActualRecord, '$.ComparatorId') AS tinyint)

            IF @W_CategoryId IS NULL
                THROW 51000, 'Valor de CategoryId em @ActualRecord é requerido.', 1
            IF @W_ComparatorId IS NULL
                THROW 51000, 'Valor de ComparatorId em @ActualRecord é requerido.', 1
            IF (@W_CategoryId IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM [dbo].[Categories] WHERE [Id] = @W_CategoryId)
                THROW 51000, 'Valor de FK em @ActualRecord inexiste em Categories', 1
            IF (@W_ComparatorId IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM [dbo].[Comparators] WHERE [Id] = @W_ComparatorId)
                THROW 51000, 'Valor de FK em @ActualRecord inexiste em Comparators', 1
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[RulePersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[RulePersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[RulePersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[RulePersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
               ,@W_Id tinyint

    IF @Action = 'delete' BEGIN
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS tinyint)

    END ELSE BEGIN
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS tinyint)

    END
    IF @Action = 'create' AND @W_Id IS NULL BEGIN
        SELECT @W_Id = CAST(JSON_VALUE([ActualRecord], '$.Id') AS tinyint)
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Rules'
                  AND [Action] = 'create'
                  AND [IsConfirmed] IS NULL
        IF @W_Id IS NULL BEGIN
            DECLARE @NewId BIGINT
    EXEC [dbo].[NewId] 'crudex', 'crudex', 'Rules', @NewId OUT
            SET @W_Id = CAST(@NewId AS tinyint)
        END
        SET @ActualRecord = JSON_MODIFY(@ActualRecord, '$.Id', @W_Id)
    END

    EXEC @TransactionId = [dbo].[RuleValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Rules'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS tinyint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            SET IDENTITY_INSERT [dbo].[Operations] ON
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Rules'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
            SET IDENTITY_INSERT [dbo].[Operations] OFF
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create'
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[RuleValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @ActionAux = 'create'
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId

    RETURN CAST(@OperationId AS BIGINT)
END
GO

