/**********************************************************************************
Criar stored procedure [dbo].[RulesRead]
**********************************************************************************/
IF(SELECT object_id('[dbo].[RulesRead]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[RulesRead] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[RulesRead](@Login NVARCHAR(MAX)
                                          ,@Filter NVARCHAR(MAX)
                                          ,@Search NVARCHAR(MAX)
                                          ,@OrderBy NVARCHAR(MAX)
                                          ,@PaddingGridLastPage BIT
                                          ,@IsActionList BIT
                                          ,@PageNumber INT OUT
                                          ,@LimitRows INT OUT
                                          ,@MaxPage INT OUT
                                          ,@ReturnValue BIGINT OUT) AS BEGIN

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

        IF @Filter IS NULL
            SET @Filter = '{}'
        ELSE IF ISJSON(@Filter) = 0
            THROW 51000, 'Valor de @Filter não está no formato JSON', 1
        IF @Search IS NULL
            SET @Search = '{}'
        ELSE IF ISJSON(@Search) = 0
            THROW 51000, 'Valor de @Search não está no formato JSON', 1
        SET @OrderBy = TRIM(ISNULL(@OrderBy, ''))
        IF @OrderBy = ''
            SET @OrderBy = '[T].[Id] ASC'
        ELSE BEGIN
            SET @OrderBy = REPLACE(REPLACE(@OrderBy, '[', ''), ']', '')
            IF EXISTS(SELECT 1 
                         FROM (SELECT CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                           WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                           ELSE TRIM([value])
                                      END AS [ColumnName]
                                  FROM STRING_SPLIT(@OrderBy, ',')) AS [O]
                                      LEFT JOIN (SELECT [#1].[name] AS ColumnName
                                                    FROM [sys].[columns] [#1]
                                                        INNER JOIN [sys].[tables] [#2] ON [#1].[object_id] = [#2].[object_id]
                                                    WHERE [#2].[name] = 'Rules') AS [T] ON [T].[ColumnName] = [O].[ColumnName]
                         WHERE [T].[ColumnName] IS NULL)
                THROW 51000, 'Nome de coluna em @OrderBy é inválido', 1
            SELECT @OrderBy = STRING_AGG('[T].[' + TRIM(CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 4)
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN LEFT(TRIM([value]), LEN(TRIM([value])) - 3)
                                                         ELSE TRIM([value])
                                                    END) + '] ' + 
                                                    CASE WHEN TRIM(RIGHT([value], 4)) = 'DESC' THEN 'DESC'
                                                         WHEN TRIM(RIGHT([value], 3)) = 'ASC' THEN 'ASC'
                                                         ELSE 'ASC'
                                                    END, ', ')
                FROM STRING_SPLIT(@OrderBy, ',')
        END

        DECLARE @TransactionId BIGINT = (SELECT MAX([Id]) FROM [dbo].[Transactions] WHERE [SessionId] = @SessionId)

        IF NOT EXISTS(SELECT 1 FROM [dbo].[Transactions] WHERE [Id] = @TransactionId AND [IsConfirmed] IS NULL)
            SET @TransactionId = NULL
        SELECT [Action] AS [_]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS tinyint) AS [Id]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.CategoryId') AS tinyint) AS [CategoryId]
              ,CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ComparatorId') AS tinyint) AS [ComparatorId]
            INTO [#tmpOperations]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Rules'
                  AND [IsConfirmed] IS NULL
        CREATE UNIQUE INDEX [#tmpOperations] ON [#tmpOperations]([Id])

        DECLARE @_ NVARCHAR(MAX) = (SELECT STRING_AGG(value, ',') FROM OPENJSON(@Filter, '$._'))
               ,@Where NVARCHAR(MAX) = ''
               ,@ComparatorPredicate NVARCHAR(MAX)
               ,@sql NVARCHAR(MAX)

        DECLARE @WT_Id tinyint = CAST(JSON_VALUE(@Filter, '$.Id') AS tinyint)
               ,@WT_CategoryId tinyint = CAST(JSON_VALUE(@Filter, '$.CategoryId') AS tinyint)
               ,@WT_ComparatorId tinyint = CAST(JSON_VALUE(@Filter, '$.ComparatorId') AS tinyint)

        IF @WT_Id IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[Id] = @T_Id'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'CategoryId' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[CategoryId] IS NULL'
        ELSE IF @WT_CategoryId IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[CategoryId] = @T_CategoryId'
        END
        IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'ComparatorId' AND [type] = 0)
            SET @Where = @Where + ' AND [T].[ComparatorId] IS NULL'
        ELSE IF @WT_ComparatorId IS NOT NULL BEGIN
            SET @Where = @Where + ' AND [T].[ComparatorId] = @T_ComparatorId'
        END
        IF @_ IS NULL BEGIN
            DECLARE @G_Id_comparator TINYINT
                   ,@G_Id_v tinyint
                   ,@G_Id_vals NVARCHAR(MAX)
                   ,@G_Id_v1 tinyint
                   ,@G_Id_v2 tinyint
                   ,@G_CategoryId_comparator TINYINT
                   ,@G_CategoryId_v tinyint
                   ,@G_CategoryId_vals NVARCHAR(MAX)
                   ,@G_CategoryId_v1 tinyint
                   ,@G_CategoryId_v2 tinyint
                   ,@G_ComparatorId_comparator TINYINT
                   ,@G_ComparatorId_v tinyint
                   ,@G_ComparatorId_vals NVARCHAR(MAX)
                   ,@G_ComparatorId_v1 tinyint
                   ,@G_ComparatorId_v2 tinyint

            SELECT @G_Id_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.Id') IS NOT NULL AND JSON_QUERY(@Filter, '$.Id') IS NULL THEN 3 END
            )
                  ,@G_Id_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.Id.value') AS tinyint),
                TRY_CAST(JSON_VALUE(@Filter, '$.Id') AS tinyint)
            )
                  ,@G_Id_vals = COALESCE(
                JSON_QUERY(@Filter, '$.Id.value'),
                JSON_QUERY(@Filter, '$.Id')
            )
            SELECT @G_Id_v1 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[0]') AS tinyint)
                  ,@G_Id_v2 = TRY_CAST(JSON_VALUE(@G_Id_vals, '$[1]') AS tinyint)
            SELECT @G_CategoryId_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.CategoryId.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.CategoryId') IS NOT NULL AND JSON_QUERY(@Filter, '$.CategoryId') IS NULL THEN 3 END
            )
                  ,@G_CategoryId_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.CategoryId.value') AS tinyint),
                TRY_CAST(JSON_VALUE(@Filter, '$.CategoryId') AS tinyint)
            )
                  ,@G_CategoryId_vals = COALESCE(
                JSON_QUERY(@Filter, '$.CategoryId.value'),
                JSON_QUERY(@Filter, '$.CategoryId')
            )
            SELECT @G_CategoryId_v1 = TRY_CAST(JSON_VALUE(@G_CategoryId_vals, '$[0]') AS tinyint)
                  ,@G_CategoryId_v2 = TRY_CAST(JSON_VALUE(@G_CategoryId_vals, '$[1]') AS tinyint)
            SELECT @G_ComparatorId_comparator = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.ComparatorId.comparator') AS TINYINT),
                CASE WHEN JSON_VALUE(@Filter, '$.ComparatorId') IS NOT NULL AND JSON_QUERY(@Filter, '$.ComparatorId') IS NULL THEN 3 END
            )
                  ,@G_ComparatorId_v = COALESCE(
                TRY_CAST(JSON_VALUE(@Filter, '$.ComparatorId.value') AS tinyint),
                TRY_CAST(JSON_VALUE(@Filter, '$.ComparatorId') AS tinyint)
            )
                  ,@G_ComparatorId_vals = COALESCE(
                JSON_QUERY(@Filter, '$.ComparatorId.value'),
                JSON_QUERY(@Filter, '$.ComparatorId')
            )
            SELECT @G_ComparatorId_v1 = TRY_CAST(JSON_VALUE(@G_ComparatorId_vals, '$[0]') AS tinyint)
                  ,@G_ComparatorId_v2 = TRY_CAST(JSON_VALUE(@G_ComparatorId_vals, '$[1]') AS tinyint)

            IF @G_Id_comparator IS NOT NULL BEGIN
                IF (@G_Id_comparator = 1 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 2 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 3 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 4 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 5 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 6 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 7 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 8 AND @G_Id_vals IS NOT NULL)
               OR (@G_Id_comparator = 9 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 10 AND @G_Id_v IS NOT NULL)
               OR (@G_Id_comparator = 11 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 12 AND @G_Id_v1 IS NOT NULL AND @G_Id_v2 IS NOT NULL)
               OR (@G_Id_comparator = 13)
               OR (@G_Id_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_Id_comparator
        WHEN 1 THEN N'[T].[Id] < @Id'
        WHEN 2 THEN N'[T].[Id] <= @Id'
        WHEN 3 THEN N'[T].[Id] = @Id'
        WHEN 4 THEN N'[T].[Id] <> @Id'
        WHEN 5 THEN N'[T].[Id] >= @Id'
        WHEN 6 THEN N'[T].[Id] > @Id'
        WHEN 7 THEN N'[T].[Id] IN (SELECT CAST([value] AS tinyint) FROM OPENJSON(@Id_vals))'
        WHEN 8 THEN N'[T].[Id] NOT IN (SELECT CAST([value] AS tinyint) FROM OPENJSON(@Id_vals))'
        WHEN 9 THEN N'[T].[Id] LIKE @Id'
        WHEN 10 THEN N'[T].[Id] NOT LIKE @Id'
        WHEN 11 THEN N'[T].[Id] BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'[T].[Id] NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'[T].[Id] IS NULL'
        WHEN 14 THEN N'[T].[Id] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'CategoryId' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[CategoryId] IS NULL'
            ELSE
            IF @G_CategoryId_comparator IS NOT NULL BEGIN
                IF (@G_CategoryId_comparator = 1 AND @G_CategoryId_v IS NOT NULL)
               OR (@G_CategoryId_comparator = 2 AND @G_CategoryId_v IS NOT NULL)
               OR (@G_CategoryId_comparator = 3 AND @G_CategoryId_v IS NOT NULL)
               OR (@G_CategoryId_comparator = 4 AND @G_CategoryId_v IS NOT NULL)
               OR (@G_CategoryId_comparator = 5 AND @G_CategoryId_v IS NOT NULL)
               OR (@G_CategoryId_comparator = 6 AND @G_CategoryId_v IS NOT NULL)
               OR (@G_CategoryId_comparator = 7 AND @G_CategoryId_vals IS NOT NULL)
               OR (@G_CategoryId_comparator = 8 AND @G_CategoryId_vals IS NOT NULL)
               OR (@G_CategoryId_comparator = 9 AND @G_CategoryId_v IS NOT NULL)
               OR (@G_CategoryId_comparator = 10 AND @G_CategoryId_v IS NOT NULL)
               OR (@G_CategoryId_comparator = 11 AND @G_CategoryId_v1 IS NOT NULL AND @G_CategoryId_v2 IS NOT NULL)
               OR (@G_CategoryId_comparator = 12 AND @G_CategoryId_v1 IS NOT NULL AND @G_CategoryId_v2 IS NOT NULL)
               OR (@G_CategoryId_comparator = 13)
               OR (@G_CategoryId_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_CategoryId_comparator
        WHEN 1 THEN N'[T].[CategoryId] < @CategoryId'
        WHEN 2 THEN N'[T].[CategoryId] <= @CategoryId'
        WHEN 3 THEN N'[T].[CategoryId] = @CategoryId'
        WHEN 4 THEN N'[T].[CategoryId] <> @CategoryId'
        WHEN 5 THEN N'[T].[CategoryId] >= @CategoryId'
        WHEN 6 THEN N'[T].[CategoryId] > @CategoryId'
        WHEN 7 THEN N'[T].[CategoryId] IN (SELECT CAST([value] AS tinyint) FROM OPENJSON(@CategoryId_vals))'
        WHEN 8 THEN N'[T].[CategoryId] NOT IN (SELECT CAST([value] AS tinyint) FROM OPENJSON(@CategoryId_vals))'
        WHEN 9 THEN N'[T].[CategoryId] LIKE @CategoryId'
        WHEN 10 THEN N'[T].[CategoryId] NOT LIKE @CategoryId'
        WHEN 11 THEN N'[T].[CategoryId] BETWEEN @CategoryId_v1 AND @CategoryId_v2'
        WHEN 12 THEN N'[T].[CategoryId] NOT BETWEEN @CategoryId_v1 AND @CategoryId_v2'
        WHEN 13 THEN N'[T].[CategoryId] IS NULL'
        WHEN 14 THEN N'[T].[CategoryId] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
            IF EXISTS(SELECT 1 FROM OPENJSON(@Filter) WHERE [key] = 'ComparatorId' AND [type] = 0)
                SET @Where = @Where + ' AND [T].[ComparatorId] IS NULL'
            ELSE
            IF @G_ComparatorId_comparator IS NOT NULL BEGIN
                IF (@G_ComparatorId_comparator = 1 AND @G_ComparatorId_v IS NOT NULL)
               OR (@G_ComparatorId_comparator = 2 AND @G_ComparatorId_v IS NOT NULL)
               OR (@G_ComparatorId_comparator = 3 AND @G_ComparatorId_v IS NOT NULL)
               OR (@G_ComparatorId_comparator = 4 AND @G_ComparatorId_v IS NOT NULL)
               OR (@G_ComparatorId_comparator = 5 AND @G_ComparatorId_v IS NOT NULL)
               OR (@G_ComparatorId_comparator = 6 AND @G_ComparatorId_v IS NOT NULL)
               OR (@G_ComparatorId_comparator = 7 AND @G_ComparatorId_vals IS NOT NULL)
               OR (@G_ComparatorId_comparator = 8 AND @G_ComparatorId_vals IS NOT NULL)
               OR (@G_ComparatorId_comparator = 9 AND @G_ComparatorId_v IS NOT NULL)
               OR (@G_ComparatorId_comparator = 10 AND @G_ComparatorId_v IS NOT NULL)
               OR (@G_ComparatorId_comparator = 11 AND @G_ComparatorId_v1 IS NOT NULL AND @G_ComparatorId_v2 IS NOT NULL)
               OR (@G_ComparatorId_comparator = 12 AND @G_ComparatorId_v1 IS NOT NULL AND @G_ComparatorId_v2 IS NOT NULL)
               OR (@G_ComparatorId_comparator = 13)
               OR (@G_ComparatorId_comparator = 14) BEGIN
                    SET @ComparatorPredicate = CASE @G_ComparatorId_comparator
        WHEN 1 THEN N'[T].[ComparatorId] < @ComparatorId'
        WHEN 2 THEN N'[T].[ComparatorId] <= @ComparatorId'
        WHEN 3 THEN N'[T].[ComparatorId] = @ComparatorId'
        WHEN 4 THEN N'[T].[ComparatorId] <> @ComparatorId'
        WHEN 5 THEN N'[T].[ComparatorId] >= @ComparatorId'
        WHEN 6 THEN N'[T].[ComparatorId] > @ComparatorId'
        WHEN 7 THEN N'[T].[ComparatorId] IN (SELECT CAST([value] AS tinyint) FROM OPENJSON(@ComparatorId_vals))'
        WHEN 8 THEN N'[T].[ComparatorId] NOT IN (SELECT CAST([value] AS tinyint) FROM OPENJSON(@ComparatorId_vals))'
        WHEN 9 THEN N'[T].[ComparatorId] LIKE @ComparatorId'
        WHEN 10 THEN N'[T].[ComparatorId] NOT LIKE @ComparatorId'
        WHEN 11 THEN N'[T].[ComparatorId] BETWEEN @ComparatorId_v1 AND @ComparatorId_v2'
        WHEN 12 THEN N'[T].[ComparatorId] NOT BETWEEN @ComparatorId_v1 AND @ComparatorId_v2'
        WHEN 13 THEN N'[T].[ComparatorId] IS NULL'
        WHEN 14 THEN N'[T].[ComparatorId] IS NOT NULL'
    END
                    IF @ComparatorPredicate IS NOT NULL SET @Where = @Where + ' AND ' + @ComparatorPredicate
                END
            END
        END ELSE
            SET @Where = @Where + ' AND [T].[Id] IN (' + @_ + ')'

        CREATE TABLE [#tmpTable]([_] CHAR(1), [Recno] BIGINT, [Id] tinyint)
        SET @sql = 'INSERT [#tmpTable]([_], [Recno], [Id])
                        SELECT [_]
                              ,[Recno]
                              ,[U].[Id]
                            FROM (SELECT ''T'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') AS [Recno]
                              ,[T].[Id]
                                    FROM [dbo].[Rules] [T]
                                        LEFT JOIN [#tmpOperations] [#] ON [T].[Id] = [#].[Id]
                                    WHERE [#].[Id] IS NULL' + @Where + '
                                  UNION ALL
                                  SELECT ''O'' AS [_]
                                        ,ROW_NUMBER() OVER (ORDER BY ' + @OrderBy + ') + (SELECT COUNT(*) FROM [#tmpTable] [#] WHERE [#].[_] = ''T'') AS [Recno]
                              ,[T].[Id]
                                    FROM [#tmpOperations] [T]
                                    WHERE [T].[_] <> ''delete''' + @Where + ') AS [U]
                            ORDER BY [Recno]'
        IF @_ IS NULL BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id tinyint,@T_CategoryId tinyint,@T_ComparatorId tinyint,@Id tinyint,@Id_v1 tinyint,@Id_v2 tinyint,@Id_vals NVARCHAR(MAX),@CategoryId tinyint,@CategoryId_v1 tinyint,@CategoryId_v2 tinyint,@CategoryId_vals NVARCHAR(MAX),@ComparatorId tinyint,@ComparatorId_v1 tinyint,@ComparatorId_v2 tinyint,@ComparatorId_vals NVARCHAR(MAX)'
                               ,@T_Id = @WT_Id
                               ,@T_CategoryId = @WT_CategoryId
                               ,@T_ComparatorId = @WT_ComparatorId
                               ,@Id = @G_Id_v
                               ,@Id_v1 = @G_Id_v1
                               ,@Id_v2 = @G_Id_v2
                               ,@Id_vals = @G_Id_vals
                               ,@CategoryId = @G_CategoryId_v
                               ,@CategoryId_v1 = @G_CategoryId_v1
                               ,@CategoryId_v2 = @G_CategoryId_v2
                               ,@CategoryId_vals = @G_CategoryId_vals
                               ,@ComparatorId = @G_ComparatorId_v
                               ,@ComparatorId_v1 = @G_ComparatorId_v1
                               ,@ComparatorId_v2 = @G_ComparatorId_v2
                               ,@ComparatorId_vals = @G_ComparatorId_vals
        END ELSE BEGIN
            EXEC sp_executesql @sql
                               ,N'@T_Id tinyint,@T_CategoryId tinyint,@T_ComparatorId tinyint'
                               ,@T_Id = @WT_Id
                               ,@T_CategoryId = @WT_CategoryId
                               ,@T_ComparatorId = @WT_ComparatorId
        END

        DECLARE @RowCount INT = @@ROWCOUNT
               ,@OffSet INT

        CREATE UNIQUE INDEX [#tmpTable] ON [#tmpTable]([Id])
        IF @RowCount = 0 OR ISNULL(@PageNumber, 0) = 0 OR ISNULL(@LimitRows, 0) <= 0 BEGIN
            SET @OffSet = 0
            SET @LimitRows = CASE WHEN @RowCount = 0 THEN 1 ELSE @RowCount END
            SET @PageNumber = 1
            SET @MaxPage = 1
        END ELSE BEGIN
            SET @MaxPage = @RowCount / @LimitRows + CASE WHEN @RowCount % @LimitRows = 0 THEN 0 ELSE 1 END
            DECLARE @SearchRecno BIGINT = NULL
            IF EXISTS(SELECT 1 FROM OPENJSON(@Search)) BEGIN
                DECLARE @Recno BIGINT
                   ,@S_Id_comparator TINYINT
                   ,@S_Id_v tinyint
                   ,@S_Id_vals NVARCHAR(MAX)
                   ,@S_Id_v1 tinyint
                   ,@S_Id_v2 tinyint
                   ,@S_CategoryId_comparator TINYINT
                   ,@S_CategoryId_v tinyint
                   ,@S_CategoryId_vals NVARCHAR(MAX)
                   ,@S_CategoryId_v1 tinyint
                   ,@S_CategoryId_v2 tinyint
                   ,@S_ComparatorId_comparator TINYINT
                   ,@S_ComparatorId_v tinyint
                   ,@S_ComparatorId_vals NVARCHAR(MAX)
                   ,@S_ComparatorId_v1 tinyint
                   ,@S_ComparatorId_v2 tinyint

                SELECT @S_Id_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Id.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.Id') IS NOT NULL AND JSON_QUERY(@Search, '$.Id') IS NULL THEN 3 END
                )
                      ,@S_Id_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Id.value') AS tinyint),
                    TRY_CAST(JSON_VALUE(@Search, '$.Id') AS tinyint)
                )
                      ,@S_Id_vals = COALESCE(
                    JSON_QUERY(@Search, '$.Id.value'),
                    JSON_QUERY(@Search, '$.Id')
                )
                SELECT @S_Id_v1 = TRY_CAST(JSON_VALUE(@S_Id_vals, '$[0]') AS tinyint)
                      ,@S_Id_v2 = TRY_CAST(JSON_VALUE(@S_Id_vals, '$[1]') AS tinyint)
                SELECT @S_CategoryId_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.CategoryId.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.CategoryId') IS NOT NULL AND JSON_QUERY(@Search, '$.CategoryId') IS NULL THEN 3 END
                )
                      ,@S_CategoryId_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.CategoryId.value') AS tinyint),
                    TRY_CAST(JSON_VALUE(@Search, '$.CategoryId') AS tinyint)
                )
                      ,@S_CategoryId_vals = COALESCE(
                    JSON_QUERY(@Search, '$.CategoryId.value'),
                    JSON_QUERY(@Search, '$.CategoryId')
                )
                SELECT @S_CategoryId_v1 = TRY_CAST(JSON_VALUE(@S_CategoryId_vals, '$[0]') AS tinyint)
                      ,@S_CategoryId_v2 = TRY_CAST(JSON_VALUE(@S_CategoryId_vals, '$[1]') AS tinyint)
                SELECT @S_ComparatorId_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.ComparatorId.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.ComparatorId') IS NOT NULL AND JSON_QUERY(@Search, '$.ComparatorId') IS NULL THEN 3 END
                )
                      ,@S_ComparatorId_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.ComparatorId.value') AS tinyint),
                    TRY_CAST(JSON_VALUE(@Search, '$.ComparatorId') AS tinyint)
                )
                      ,@S_ComparatorId_vals = COALESCE(
                    JSON_QUERY(@Search, '$.ComparatorId.value'),
                    JSON_QUERY(@Search, '$.ComparatorId')
                )
                SELECT @S_ComparatorId_v1 = TRY_CAST(JSON_VALUE(@S_ComparatorId_vals, '$[0]') AS tinyint)
                      ,@S_ComparatorId_v2 = TRY_CAST(JSON_VALUE(@S_ComparatorId_vals, '$[1]') AS tinyint)

                SET @Where = ''
                IF @S_Id_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_Id_comparator = 1 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 2 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 3 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 4 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 5 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 6 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 7 AND @S_Id_vals IS NOT NULL)
               OR (@S_Id_comparator = 8 AND @S_Id_vals IS NOT NULL)
               OR (@S_Id_comparator = 9 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 10 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 11 AND @S_Id_v1 IS NOT NULL AND @S_Id_v2 IS NOT NULL)
               OR (@S_Id_comparator = 12 AND @S_Id_v1 IS NOT NULL AND @S_Id_v2 IS NOT NULL)
               OR (@S_Id_comparator = 13)
               OR (@S_Id_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_Id_comparator
        WHEN 1 THEN N'COALESCE([D].[Id], [O].[Id]) < @Id'
        WHEN 2 THEN N'COALESCE([D].[Id], [O].[Id]) <= @Id'
        WHEN 3 THEN N'COALESCE([D].[Id], [O].[Id]) = @Id'
        WHEN 4 THEN N'COALESCE([D].[Id], [O].[Id]) <> @Id'
        WHEN 5 THEN N'COALESCE([D].[Id], [O].[Id]) >= @Id'
        WHEN 6 THEN N'COALESCE([D].[Id], [O].[Id]) > @Id'
        WHEN 7 THEN N'COALESCE([D].[Id], [O].[Id]) IN (SELECT CAST([value] AS tinyint) FROM OPENJSON(@Id_vals))'
        WHEN 8 THEN N'COALESCE([D].[Id], [O].[Id]) NOT IN (SELECT CAST([value] AS tinyint) FROM OPENJSON(@Id_vals))'
        WHEN 9 THEN N'COALESCE([D].[Id], [O].[Id]) LIKE @Id'
        WHEN 10 THEN N'COALESCE([D].[Id], [O].[Id]) NOT LIKE @Id'
        WHEN 11 THEN N'COALESCE([D].[Id], [O].[Id]) BETWEEN @Id_v1 AND @Id_v2'
        WHEN 12 THEN N'COALESCE([D].[Id], [O].[Id]) NOT BETWEEN @Id_v1 AND @Id_v2'
        WHEN 13 THEN N'COALESCE([D].[Id], [O].[Id]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[Id], [O].[Id]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'CategoryId' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[CategoryId], [O].[CategoryId]) IS NULL'
                END ELSE
                IF @S_CategoryId_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_CategoryId_comparator = 1 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 2 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 3 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 4 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 5 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 6 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 7 AND @S_CategoryId_vals IS NOT NULL)
               OR (@S_CategoryId_comparator = 8 AND @S_CategoryId_vals IS NOT NULL)
               OR (@S_CategoryId_comparator = 9 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 10 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 11 AND @S_CategoryId_v1 IS NOT NULL AND @S_CategoryId_v2 IS NOT NULL)
               OR (@S_CategoryId_comparator = 12 AND @S_CategoryId_v1 IS NOT NULL AND @S_CategoryId_v2 IS NOT NULL)
               OR (@S_CategoryId_comparator = 13)
               OR (@S_CategoryId_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_CategoryId_comparator
        WHEN 1 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) < @CategoryId'
        WHEN 2 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) <= @CategoryId'
        WHEN 3 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) = @CategoryId'
        WHEN 4 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) <> @CategoryId'
        WHEN 5 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) >= @CategoryId'
        WHEN 6 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) > @CategoryId'
        WHEN 7 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) IN (SELECT CAST([value] AS tinyint) FROM OPENJSON(@CategoryId_vals))'
        WHEN 8 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) NOT IN (SELECT CAST([value] AS tinyint) FROM OPENJSON(@CategoryId_vals))'
        WHEN 9 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) LIKE @CategoryId'
        WHEN 10 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) NOT LIKE @CategoryId'
        WHEN 11 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) BETWEEN @CategoryId_v1 AND @CategoryId_v2'
        WHEN 12 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) NOT BETWEEN @CategoryId_v1 AND @CategoryId_v2'
        WHEN 13 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'ComparatorId' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[ComparatorId], [O].[ComparatorId]) IS NULL'
                END ELSE
                IF @S_ComparatorId_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_ComparatorId_comparator = 1 AND @S_ComparatorId_v IS NOT NULL)
               OR (@S_ComparatorId_comparator = 2 AND @S_ComparatorId_v IS NOT NULL)
               OR (@S_ComparatorId_comparator = 3 AND @S_ComparatorId_v IS NOT NULL)
               OR (@S_ComparatorId_comparator = 4 AND @S_ComparatorId_v IS NOT NULL)
               OR (@S_ComparatorId_comparator = 5 AND @S_ComparatorId_v IS NOT NULL)
               OR (@S_ComparatorId_comparator = 6 AND @S_ComparatorId_v IS NOT NULL)
               OR (@S_ComparatorId_comparator = 7 AND @S_ComparatorId_vals IS NOT NULL)
               OR (@S_ComparatorId_comparator = 8 AND @S_ComparatorId_vals IS NOT NULL)
               OR (@S_ComparatorId_comparator = 9 AND @S_ComparatorId_v IS NOT NULL)
               OR (@S_ComparatorId_comparator = 10 AND @S_ComparatorId_v IS NOT NULL)
               OR (@S_ComparatorId_comparator = 11 AND @S_ComparatorId_v1 IS NOT NULL AND @S_ComparatorId_v2 IS NOT NULL)
               OR (@S_ComparatorId_comparator = 12 AND @S_ComparatorId_v1 IS NOT NULL AND @S_ComparatorId_v2 IS NOT NULL)
               OR (@S_ComparatorId_comparator = 13)
               OR (@S_ComparatorId_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_ComparatorId_comparator
        WHEN 1 THEN N'COALESCE([D].[ComparatorId], [O].[ComparatorId]) < @ComparatorId'
        WHEN 2 THEN N'COALESCE([D].[ComparatorId], [O].[ComparatorId]) <= @ComparatorId'
        WHEN 3 THEN N'COALESCE([D].[ComparatorId], [O].[ComparatorId]) = @ComparatorId'
        WHEN 4 THEN N'COALESCE([D].[ComparatorId], [O].[ComparatorId]) <> @ComparatorId'
        WHEN 5 THEN N'COALESCE([D].[ComparatorId], [O].[ComparatorId]) >= @ComparatorId'
        WHEN 6 THEN N'COALESCE([D].[ComparatorId], [O].[ComparatorId]) > @ComparatorId'
        WHEN 7 THEN N'COALESCE([D].[ComparatorId], [O].[ComparatorId]) IN (SELECT CAST([value] AS tinyint) FROM OPENJSON(@ComparatorId_vals))'
        WHEN 8 THEN N'COALESCE([D].[ComparatorId], [O].[ComparatorId]) NOT IN (SELECT CAST([value] AS tinyint) FROM OPENJSON(@ComparatorId_vals))'
        WHEN 9 THEN N'COALESCE([D].[ComparatorId], [O].[ComparatorId]) LIKE @ComparatorId'
        WHEN 10 THEN N'COALESCE([D].[ComparatorId], [O].[ComparatorId]) NOT LIKE @ComparatorId'
        WHEN 11 THEN N'COALESCE([D].[ComparatorId], [O].[ComparatorId]) BETWEEN @ComparatorId_v1 AND @ComparatorId_v2'
        WHEN 12 THEN N'COALESCE([D].[ComparatorId], [O].[ComparatorId]) NOT BETWEEN @ComparatorId_v1 AND @ComparatorId_v2'
        WHEN 13 THEN N'COALESCE([D].[ComparatorId], [O].[ComparatorId]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[ComparatorId], [O].[ComparatorId]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[Rules] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id tinyint,@Id_v1 tinyint,@Id_v2 tinyint,@Id_vals NVARCHAR(MAX),@CategoryId tinyint,@CategoryId_v1 tinyint,@CategoryId_v2 tinyint,@CategoryId_vals NVARCHAR(MAX),@ComparatorId tinyint,@ComparatorId_v1 tinyint,@ComparatorId_v2 tinyint,@ComparatorId_vals NVARCHAR(MAX), @r BIGINT OUTPUT'
                                       ,@Id = @S_Id_v
                                       ,@Id_v1 = @S_Id_v1
                                       ,@Id_v2 = @S_Id_v2
                                       ,@Id_vals = @S_Id_vals
                                       ,@CategoryId = @S_CategoryId_v
                                       ,@CategoryId_v1 = @S_CategoryId_v1
                                       ,@CategoryId_v2 = @S_CategoryId_v2
                                       ,@CategoryId_vals = @S_CategoryId_vals
                                       ,@ComparatorId = @S_ComparatorId_v
                                       ,@ComparatorId_v1 = @S_ComparatorId_v1
                                       ,@ComparatorId_v2 = @S_ComparatorId_v2
                                       ,@ComparatorId_vals = @S_ComparatorId_vals
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS tinyint) AS [Id]
                    ,CAST(NULL AS tinyint) AS [CategoryId]
                    ,CAST(NULL AS tinyint) AS [ComparatorId]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''Rule'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[CategoryId]
                              ,[T].[ComparatorId]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Rules] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Rule'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[CategoryId]
                                  ,[O].[ComparatorId]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT DISTINCT 'Category' AS [Kind]
              ,[R].[Id]
              ,[R].[Name]
              ,[R].[HtmlInputType]
              ,[R].[HtmlInputAlign]
              ,[R].[AskEncrypted]
              ,[R].[AskMask]
              ,[R].[AskListable]
              ,[R].[AskDefault]
              ,[R].[AskMinimum]
              ,[R].[AskMaximum]
              ,[R].[AskInWords]
            INTO [#Categories]
            FROM [#result] [T]
                INNER JOIN [dbo].[Categories] [R] ON [R].[Id] = [T].[CategoryId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Categories] ON [#Categories]([Id])
        SELECT DISTINCT 'Comparator' AS [Kind]
              ,[R].[Id]
              ,[R].[Symbol]
              ,[R].[Description]
              ,[R].[Arity]
            INTO [#Comparators]
            FROM [#result] [T]
                INNER JOIN [dbo].[Comparators] [R] ON [R].[Id] = [T].[ComparatorId]
            ORDER BY [R].[Id]
        CREATE UNIQUE INDEX [#Comparators] ON [#Comparators]([Id])
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[CategoryId]
                      ,[ComparatorId]
                    FROM [#result] FOR JSON PATH) AS [result]
              ,ISNULL((SELECT [Category].* FROM [#Categories] AS [Category] FOR JSON PATH), '[]') AS [Category]
              ,ISNULL((SELECT [Comparator].* FROM [#Comparators] AS [Comparator] FOR JSON PATH), '[]') AS [Comparator]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[testeValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[testeValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[testeValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[testeValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_pk1 tinyint
               ,@W_pk2 tinyint
               ,@W_pk3 tinyint

        IF @Action = 'delete' BEGIN
            SET @W_pk1 = CAST(JSON_VALUE(@LastRecord, '$.pk1') AS tinyint)
            SET @W_pk2 = CAST(JSON_VALUE(@LastRecord, '$.pk2') AS tinyint)
            SET @W_pk3 = CAST(JSON_VALUE(@LastRecord, '$.pk3') AS tinyint)

        END ELSE BEGIN
            SET @W_pk1 = CAST(JSON_VALUE(@ActualRecord, '$.pk1') AS tinyint)
            SET @W_pk2 = CAST(JSON_VALUE(@ActualRecord, '$.pk2') AS tinyint)
            SET @W_pk3 = CAST(JSON_VALUE(@ActualRecord, '$.pk3') AS tinyint)

        END
        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_pk1 IS NULL BEGIN
            SET @ErrorMessage = 'Valor de pk1 em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_pk1 < CAST('1' AS tinyint)
            THROW 51000, 'Valor de pk1 em @ActualRecord deve ser maior que ou igual a 1', 1
        IF @W_pk2 IS NULL BEGIN
            SET @ErrorMessage = 'Valor de pk2 em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_pk3 IS NULL BEGIN
            SET @ErrorMessage = 'Valor de pk3 em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF EXISTS(SELECT 1 FROM [dbo].[testes] WHERE [pk1] = @W_pk1      AND [pk2] = @W_pk2      AND [pk3] = @W_pk3) AND @Action = 'create'
            THROW 51000, 'Chave-primária já existe em testes', 1
        ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'testes'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND                                           CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.pk1') AS tinyint) = @W_pk1                                                AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.pk2') AS tinyint) = @W_pk2                                                AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.pk3') AS tinyint) = @W_pk3)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create' AND NOT EXISTS(SELECT 1 FROM [dbo].[testes] WHERE [pk1] = @W_pk1      AND [pk2] = @W_pk2      AND [pk3] = @W_pk3)
            THROW 51000, 'Chave-primária não existe em testes', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[testes]
                            WHERE [pk1] = JSON_VALUE(@LastRecord, '$.pk1')
                                  AND [pk2] = JSON_VALUE(@LastRecord, '$.pk2')
                                  AND [pk3] = JSON_VALUE(@LastRecord, '$.pk3')
                                  AND [dbo].[IS_EQUAL]([cpo1], JSON_VALUE(@LastRecord, '$.cpo1'), 'nvarchar') = 1
                                  AND [dbo].[IS_EQUAL]([cpo2], JSON_VALUE(@LastRecord, '$.cpo2'), 'nvarchar') = 1
                                  AND [dbo].[IS_EQUAL]([cpo3], JSON_VALUE(@LastRecord, '$.cpo3'), 'nvarchar') = 1
                                  AND [dbo].[IS_EQUAL]([cpo4], JSON_VALUE(@LastRecord, '$.cpo4'), 'tinyint') = 1)
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'testes'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.pk1') = JSON_VALUE(@LastRecord, '$.pk1')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.pk2') = JSON_VALUE(@LastRecord, '$.pk2')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.pk3') = JSON_VALUE(@LastRecord, '$.pk3')
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.cpo1'), JSON_VALUE(@LastRecord, '$.cpo1'), 'nvarchar') = 1
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.cpo2'), JSON_VALUE(@LastRecord, '$.cpo2'), 'nvarchar') = 1
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.cpo3'), JSON_VALUE(@LastRecord, '$.cpo3'), 'nvarchar') = 1
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.cpo4'), JSON_VALUE(@LastRecord, '$.cpo4'), 'tinyint') = 1)
                THROW 51000, 'Registro de testes alterado por outro usuário', 1
        END

        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_cpo1 nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.cpo1') AS nvarchar(25))
                   ,@W_cpo2 nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.cpo2') AS nvarchar(25))
                   ,@W_cpo3 nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.cpo3') AS nvarchar(25))
                   ,@W_cpo4 tinyint = CAST(JSON_VALUE(@ActualRecord, '$.cpo4') AS tinyint)

        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[testePersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[testePersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[testePersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[testePersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
               ,@W_pk1 tinyint
               ,@W_pk2 tinyint
               ,@W_pk3 tinyint

    IF @Action = 'delete' BEGIN
        SET @W_pk1 = CAST(JSON_VALUE(@LastRecord, '$.pk1') AS tinyint)
        SET @W_pk2 = CAST(JSON_VALUE(@LastRecord, '$.pk2') AS tinyint)
        SET @W_pk3 = CAST(JSON_VALUE(@LastRecord, '$.pk3') AS tinyint)

    END ELSE BEGIN
        SET @W_pk1 = CAST(JSON_VALUE(@ActualRecord, '$.pk1') AS tinyint)
        SET @W_pk2 = CAST(JSON_VALUE(@ActualRecord, '$.pk2') AS tinyint)
        SET @W_pk3 = CAST(JSON_VALUE(@ActualRecord, '$.pk3') AS tinyint)

    END
    EXEC @TransactionId = [dbo].[testeValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'testes'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.pk1') AS tinyint) = @W_pk1      AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.pk2') AS tinyint) = @W_pk2      AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.pk3') AS tinyint) = @W_pk3
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            SET IDENTITY_INSERT [dbo].[Operations] ON
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'testes'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
            SET IDENTITY_INSERT [dbo].[Operations] OFF
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create'
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[testeValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @ActionAux = 'create'
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[testeCreate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[testeCreate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[testeCreate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[testeCreate](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'testes'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'create'
            THROW 51000, 'Ação da operação é inválida para Create', 1
        EXEC @TransactionIdAux = [dbo].[testeValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_pk1 tinyint = CAST(JSON_VALUE(@ActualRecord, '$.pk1') AS tinyint)
               ,@W_pk2 tinyint = CAST(JSON_VALUE(@ActualRecord, '$.pk2') AS tinyint)
               ,@W_pk3 tinyint = CAST(JSON_VALUE(@ActualRecord, '$.pk3') AS tinyint)

        DECLARE @W_cpo1 nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.cpo1') AS nvarchar(25))
               ,@W_cpo2 nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.cpo2') AS nvarchar(25))
               ,@W_cpo3 nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.cpo3') AS nvarchar(25))
               ,@W_cpo4 tinyint = CAST(JSON_VALUE(@ActualRecord, '$.cpo4') AS tinyint)

        INSERT INTO [dbo].[testes] ([pk1]
                                            ,[pk2]
                                            ,[pk3]
                                            ,[cpo1]
                                            ,[cpo2]
                                            ,[cpo3]
                                            ,[cpo4]
                                            ,[CreatedAt]
                                            ,[CreatedBy])
                                      VALUES (@W_pk1
                                             ,@W_pk2
                                             ,@W_pk3
                                             ,@W_cpo1
                                             ,@W_cpo2
                                             ,@W_cpo3
                                             ,@W_cpo4
                                             ,GETDATE()
                                             ,@UserName)
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[testeUpdate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[testeUpdate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[testeUpdate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[testeUpdate](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'testes'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'update'
            THROW 51000, 'Ação da operação é inválida para Update', 1
        EXEC @TransactionIdAux = [dbo].[testeValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_pk1 tinyint = CAST(JSON_VALUE(@ActualRecord, '$.pk1') AS tinyint)
               ,@W_pk2 tinyint = CAST(JSON_VALUE(@ActualRecord, '$.pk2') AS tinyint)
               ,@W_pk3 tinyint = CAST(JSON_VALUE(@ActualRecord, '$.pk3') AS tinyint)

        DECLARE @W_cpo1 nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.cpo1') AS nvarchar(25))
               ,@W_cpo2 nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.cpo2') AS nvarchar(25))
               ,@W_cpo3 nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.cpo3') AS nvarchar(25))
               ,@W_cpo4 tinyint = CAST(JSON_VALUE(@ActualRecord, '$.cpo4') AS tinyint)

        UPDATE [dbo].[testes] SET [pk1] = @W_pk1
                                          ,[pk2] = @W_pk2
                                          ,[pk3] = @W_pk3
                                          ,[cpo1] = @W_cpo1
                                          ,[cpo2] = @W_cpo2
                                          ,[cpo3] = @W_cpo3
                                          ,[cpo4] = @W_cpo4
                                          ,[UpdatedAt] = GETDATE()
                                          ,[UpdatedBy] = @UserName
            WHERE [pk1] = @W_pk1      AND [pk2] = @W_pk2      AND [pk3] = @W_pk3
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

