                               ,@pk3_v2 = @G_pk3_v2
                               ,@pk3_vals = @G_pk3_vals
                               ,@cpo1 = @G_cpo1_v
                               ,@cpo1_v1 = @G_cpo1_v1
                               ,@cpo1_v2 = @G_cpo1_v2
                               ,@cpo1_vals = @G_cpo1_vals
                               ,@cpo2 = @G_cpo2_v
                               ,@cpo2_v1 = @G_cpo2_v1
                               ,@cpo2_v2 = @G_cpo2_v2
                               ,@cpo2_vals = @G_cpo2_vals
                               ,@cpo3 = @G_cpo3_v
                               ,@cpo3_v1 = @G_cpo3_v1
                               ,@cpo3_v2 = @G_cpo3_v2
                               ,@cpo3_vals = @G_cpo3_vals
                               ,@cpo4 = @G_cpo4_v
                               ,@cpo4_v1 = @G_cpo4_v1
