                               ,N'@T_pk1 tinyint,@T_pk2 tinyint,@T_pk3 tinyint,@T_cpo1 nvarchar(25),@T_cpo2 nvarchar(25),@T_cpo3 nvarchar(25),@T_cpo4 tinyint'
                               ,@T_pk1 = @WT_pk1
                               ,@T_pk2 = @WT_pk2
