                IF @S_CategoryId_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_CategoryId_comparator = 1 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 2 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 3 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 4 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 5 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 6 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 7 AND @S_CategoryId_vals IS NOT NULL)
               OR (@S_CategoryId_comparator = 8 AND @S_CategoryId_vals IS NOT NULL)
               OR (@S_CategoryId_comparator = 9 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 10 AND @S_CategoryId_v IS NOT NULL)
               OR (@S_CategoryId_comparator = 11 AND @S_CategoryId_v1 IS NOT NULL AND @S_CategoryId_v2 IS NOT NULL)
               OR (@S_CategoryId_comparator = 12 AND @S_CategoryId_v1 IS NOT NULL AND @S_CategoryId_v2 IS NOT NULL)
               OR (@S_CategoryId_comparator = 13)
               OR (@S_CategoryId_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_CategoryId_comparator
        WHEN 1 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) < @CategoryId'
        WHEN 2 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) <= @CategoryId'
        WHEN 3 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) = @CategoryId'
        WHEN 4 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) <> @CategoryId'
        WHEN 5 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) >= @CategoryId'
        WHEN 6 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) > @CategoryId'
        WHEN 7 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@CategoryId_vals))'
        WHEN 8 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@CategoryId_vals))'
        WHEN 9 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) LIKE @CategoryId'
        WHEN 10 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) NOT LIKE @CategoryId'
        WHEN 11 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) BETWEEN @CategoryId_v1 AND @CategoryId_v2'
        WHEN 12 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) NOT BETWEEN @CategoryId_v1 AND @CategoryId_v2'
        WHEN 13 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[CategoryId], [O].[CategoryId]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'Description' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[Description], [O].[Description]) IS NULL'
                END ELSE
                IF @S_Description_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_Description_comparator = 1 AND @S_Description_v IS NOT NULL)
               OR (@S_Description_comparator = 2 AND @S_Description_v IS NOT NULL)
               OR (@S_Description_comparator = 3 AND @S_Description_v IS NOT NULL)
               OR (@S_Description_comparator = 4 AND @S_Description_v IS NOT NULL)
               OR (@S_Description_comparator = 5 AND @S_Description_v IS NOT NULL)
               OR (@S_Description_comparator = 6 AND @S_Description_v IS NOT NULL)
               OR (@S_Description_comparator = 7 AND @S_Description_vals IS NOT NULL)
               OR (@S_Description_comparator = 8 AND @S_Description_vals IS NOT NULL)
               OR (@S_Description_comparator = 9 AND @S_Description_v IS NOT NULL)
               OR (@S_Description_comparator = 10 AND @S_Description_v IS NOT NULL)
               OR (@S_Description_comparator = 11 AND @S_Description_v1 IS NOT NULL AND @S_Description_v2 IS NOT NULL)
               OR (@S_Description_comparator = 12 AND @S_Description_v1 IS NOT NULL AND @S_Description_v2 IS NOT NULL)
               OR (@S_Description_comparator = 13)
               OR (@S_Description_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_Description_comparator
        WHEN 1 THEN N'COALESCE([D].[Description], [O].[Description]) < @Description'
        WHEN 2 THEN N'COALESCE([D].[Description], [O].[Description]) <= @Description'
        WHEN 3 THEN N'COALESCE([D].[Description], [O].[Description]) = @Description'
        WHEN 4 THEN N'COALESCE([D].[Description], [O].[Description]) <> @Description'
        WHEN 5 THEN N'COALESCE([D].[Description], [O].[Description]) >= @Description'
        WHEN 6 THEN N'COALESCE([D].[Description], [O].[Description]) > @Description'
        WHEN 7 THEN N'COALESCE([D].[Description], [O].[Description]) IN (SELECT CAST([value] AS nvarchar(50)) FROM OPENJSON(@Description_vals))'
        WHEN 8 THEN N'COALESCE([D].[Description], [O].[Description]) NOT IN (SELECT CAST([value] AS nvarchar(50)) FROM OPENJSON(@Description_vals))'
        WHEN 9 THEN N'COALESCE([D].[Description], [O].[Description]) LIKE @Description'
        WHEN 10 THEN N'COALESCE([D].[Description], [O].[Description]) NOT LIKE @Description'
        WHEN 11 THEN N'COALESCE([D].[Description], [O].[Description]) BETWEEN @Description_v1 AND @Description_v2'
        WHEN 12 THEN N'COALESCE([D].[Description], [O].[Description]) NOT BETWEEN @Description_v1 AND @Description_v2'
        WHEN 13 THEN N'COALESCE([D].[Description], [O].[Description]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[Description], [O].[Description]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'IsActive' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[IsActive], [O].[IsActive]) IS NULL'
                END ELSE
                IF @S_IsActive_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_IsActive_comparator = 1 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 2 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 3 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 4 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 5 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 6 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 7 AND @S_IsActive_vals IS NOT NULL)
               OR (@S_IsActive_comparator = 8 AND @S_IsActive_vals IS NOT NULL)
               OR (@S_IsActive_comparator = 9 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 10 AND @S_IsActive_v IS NOT NULL)
               OR (@S_IsActive_comparator = 11 AND @S_IsActive_v1 IS NOT NULL AND @S_IsActive_v2 IS NOT NULL)
               OR (@S_IsActive_comparator = 12 AND @S_IsActive_v1 IS NOT NULL AND @S_IsActive_v2 IS NOT NULL)
               OR (@S_IsActive_comparator = 13)
               OR (@S_IsActive_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_IsActive_comparator
        WHEN 1 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) < @IsActive'
        WHEN 2 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) <= @IsActive'
        WHEN 3 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) = @IsActive'
        WHEN 4 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) <> @IsActive'
        WHEN 5 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) >= @IsActive'
        WHEN 6 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) > @IsActive'
        WHEN 7 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsActive_vals))'
        WHEN 8 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) NOT IN (SELECT CAST([value] AS bit) FROM OPENJSON(@IsActive_vals))'
        WHEN 9 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) LIKE @IsActive'
        WHEN 10 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) NOT LIKE @IsActive'
        WHEN 11 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) BETWEEN @IsActive_v1 AND @IsActive_v2'
        WHEN 12 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) NOT BETWEEN @IsActive_v1 AND @IsActive_v2'
        WHEN 13 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[IsActive], [O].[IsActive]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[Properties] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@Name nvarchar(25),@Name_v1 nvarchar(25),@Name_v2 nvarchar(25),@Name_vals NVARCHAR(MAX),@CategoryId bigint,@CategoryId_v1 bigint,@CategoryId_v2 bigint,@CategoryId_vals NVARCHAR(MAX),@Description nvarchar(50),@Description_v1 nvarchar(50),@Description_v2 nvarchar(50),@Description_vals NVARCHAR(MAX),@IsActive bit,@IsActive_v1 bit,@IsActive_v2 bit,@IsActive_vals NVARCHAR(MAX), @r BIGINT OUTPUT'
                                       ,@Id = @S_Id_v
                                       ,@Id_v1 = @S_Id_v1
                                       ,@Id_v2 = @S_Id_v2
                                       ,@Id_vals = @S_Id_vals
                                       ,@Name = @S_Name_v
                                       ,@Name_v1 = @S_Name_v1
                                       ,@Name_v2 = @S_Name_v2
                                       ,@Name_vals = @S_Name_vals
                                       ,@CategoryId = @S_CategoryId_v
                                       ,@CategoryId_v1 = @S_CategoryId_v1
                                       ,@CategoryId_v2 = @S_CategoryId_v2
                                       ,@CategoryId_vals = @S_CategoryId_vals
                                       ,@Description = @S_Description_v
                                       ,@Description_v1 = @S_Description_v1
                                       ,@Description_v2 = @S_Description_v2
                                       ,@Description_vals = @S_Description_vals
                                       ,@IsActive = @S_IsActive_v
                                       ,@IsActive_v1 = @S_IsActive_v1
                                       ,@IsActive_v2 = @S_IsActive_v2
                                       ,@IsActive_vals = @S_IsActive_vals
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS nvarchar(25)) AS [Name]
                    ,CAST(NULL AS bigint) AS [CategoryId]
                    ,CAST(NULL AS nvarchar(50)) AS [Description]
                    ,CAST(NULL AS bit) AS [IsActive]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''Property'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[Name]
                              ,[T].[CategoryId]
                              ,[T].[Description]
                              ,[T].[IsActive]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Properties] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Property'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[Name]
                                  ,[O].[CategoryId]
                                  ,[O].[Description]
                                  ,[O].[IsActive]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[Name]
                      ,[CategoryId]
                      ,[Description]
                      ,[IsActive]
                    FROM [#result] FOR JSON PATH) AS [result]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[BehaviorValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[BehaviorValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[BehaviorValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[BehaviorValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id bigint

        IF @Action = 'delete' BEGIN
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

        END ELSE BEGIN
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        END
        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF EXISTS(SELECT 1 FROM [dbo].[Behaviors] WHERE [Id] = @W_Id) AND @Action = 'create'
            THROW 51000, 'Chave-primária já existe em Behaviors', 1
        ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'Behaviors'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND                                           CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create' AND NOT EXISTS(SELECT 1 FROM [dbo].[Behaviors] WHERE [Id] = @W_Id)
            THROW 51000, 'Chave-primária não existe em Behaviors', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[Behaviors]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [ColumnId] = JSON_VALUE(@LastRecord, '$.ColumnId')
                                  AND [ExpressionId] = JSON_VALUE(@LastRecord, '$.ExpressionId')
                                  AND [PropertyId] = JSON_VALUE(@LastRecord, '$.PropertyId')
                                  AND [dbo].[IS_EQUAL]([Value], JSON_VALUE(@LastRecord, '$.Value'), 'nvarchar(max)') = 1
                                  AND [dbo].[IS_EQUAL]([ElseValue], JSON_VALUE(@LastRecord, '$.ElseValue'), 'nvarchar(max)') = 1)
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'Behaviors'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ColumnId') = JSON_VALUE(@LastRecord, '$.ColumnId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ExpressionId') = JSON_VALUE(@LastRecord, '$.ExpressionId')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.PropertyId') = JSON_VALUE(@LastRecord, '$.PropertyId')
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Value'), JSON_VALUE(@LastRecord, '$.Value'), 'nvarchar(max)') = 1
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.ElseValue'), JSON_VALUE(@LastRecord, '$.ElseValue'), 'nvarchar(max)') = 1)
                THROW 51000, 'Registro de Behaviors alterado por outro usuário', 1
        END

        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_ColumnId bigint = CAST(JSON_VALUE(@ActualRecord, '$.ColumnId') AS bigint)
                   ,@W_ExpressionId bigint = CAST(JSON_VALUE(@ActualRecord, '$.ExpressionId') AS bigint)
                   ,@W_PropertyId bigint = CAST(JSON_VALUE(@ActualRecord, '$.PropertyId') AS bigint)
                   ,@W_Value nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.Value') AS nvarchar(max))
                   ,@W_ElseValue nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.ElseValue') AS nvarchar(max))

            IF @W_ColumnId IS NULL
                THROW 51000, 'Valor de ColumnId em @ActualRecord é requerido.', 1
            IF @W_ExpressionId IS NULL
                THROW 51000, 'Valor de ExpressionId em @ActualRecord é requerido.', 1
            IF @W_PropertyId IS NULL
                THROW 51000, 'Valor de PropertyId em @ActualRecord é requerido.', 1
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[BehaviorPersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[BehaviorPersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[BehaviorPersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[BehaviorPersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
               ,@W_Id bigint

    IF @Action = 'delete' BEGIN
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

    END ELSE BEGIN
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    END
    EXEC @TransactionId = [dbo].[BehaviorValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'Behaviors'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            SET IDENTITY_INSERT [dbo].[Operations] ON
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'Behaviors'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
            SET IDENTITY_INSERT [dbo].[Operations] OFF
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create'
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[BehaviorValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @ActionAux = 'create'
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[BehaviorCreate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[BehaviorCreate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[BehaviorCreate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[BehaviorCreate](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'Behaviors'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'create'
            THROW 51000, 'Ação da operação é inválida para Create', 1
        EXEC @TransactionIdAux = [dbo].[BehaviorValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id bigint = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        DECLARE @W_ColumnId bigint = CAST(JSON_VALUE(@ActualRecord, '$.ColumnId') AS bigint)
               ,@W_ExpressionId bigint = CAST(JSON_VALUE(@ActualRecord, '$.ExpressionId') AS bigint)
               ,@W_PropertyId bigint = CAST(JSON_VALUE(@ActualRecord, '$.PropertyId') AS bigint)
               ,@W_Value nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.Value') AS nvarchar(max))
               ,@W_ElseValue nvarchar(max) = CAST(JSON_VALUE(@ActualRecord, '$.ElseValue') AS nvarchar(max))

        INSERT INTO [dbo].[Behaviors] ([Id]
                                            ,[ColumnId]
                                            ,[ExpressionId]
                                            ,[PropertyId]
                                            ,[Value]
                                            ,[ElseValue]
                                            ,[CreatedAt]
                                            ,[CreatedBy])
                                      VALUES (@W_Id
                                             ,@W_ColumnId
                                             ,@W_ExpressionId
                                             ,@W_PropertyId
                                             ,@W_Value
                                             ,@W_ElseValue
                                             ,GETDATE()
                                             ,@UserName)
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

