                )
                      ,@S_PropertyId_vals = COALESCE(
                    JSON_QUERY(@Search, '$.PropertyId.value'),
                    JSON_QUERY(@Search, '$.PropertyId')
                )
                SELECT @S_PropertyId_v1 = TRY_CAST(JSON_VALUE(@S_PropertyId_vals, '$[0]') AS bigint)
                      ,@S_PropertyId_v2 = TRY_CAST(JSON_VALUE(@S_PropertyId_vals, '$[1]') AS bigint)
                SELECT @S_Value_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Value.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.Value') IS NOT NULL AND JSON_QUERY(@Search, '$.Value') IS NULL THEN 9 END
                )
                      ,@S_Value_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.Value.value') AS nvarchar(max)),
                    TRY_CAST(JSON_VALUE(@Search, '$.Value') AS nvarchar(max))
                )
                      ,@S_Value_vals = COALESCE(
                    JSON_QUERY(@Search, '$.Value.value'),
                    JSON_QUERY(@Search, '$.Value')
                )
                SELECT @S_ElseValue_comparator = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.ElseValue.comparator') AS TINYINT),
                    CASE WHEN JSON_VALUE(@Search, '$.ElseValue') IS NOT NULL AND JSON_QUERY(@Search, '$.ElseValue') IS NULL THEN 9 END
                )
                      ,@S_ElseValue_v = COALESCE(
                    TRY_CAST(JSON_VALUE(@Search, '$.ElseValue.value') AS nvarchar(max)),
                    TRY_CAST(JSON_VALUE(@Search, '$.ElseValue') AS nvarchar(max))
                )
                      ,@S_ElseValue_vals = COALESCE(
                    JSON_QUERY(@Search, '$.ElseValue.value'),
                    JSON_QUERY(@Search, '$.ElseValue')
                )

                SET @Where = ''
                IF @S_Id_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_Id_comparator = 1 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 2 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 3 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 4 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 5 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 6 AND @S_Id_v IS NOT NULL)
               OR (@S_Id_comparator = 7 AND @S_Id_vals IS NOT NULL)
               OR (@S_Id_comparator = 8 AND @S_Id_vals IS NOT NULL)
               OR (@S_Id_comparator = 9 AND @S_Id_v IS NOT NULL)
