        WHEN 11 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) BETWEEN @ColumnId_v1 AND @ColumnId_v2'
        WHEN 12 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) NOT BETWEEN @ColumnId_v1 AND @ColumnId_v2'
        WHEN 13 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[ColumnId], [O].[ColumnId]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'ExpressionId' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[ExpressionId], [O].[ExpressionId]) IS NULL'
                END ELSE
                IF @S_ExpressionId_comparator IS NOT NULL BEGIN
