                        SET @ComparatorPredicate = CASE @S_ExpressionId_comparator
        WHEN 1 THEN N'COALESCE([D].[ExpressionId], [O].[ExpressionId]) < @ExpressionId'
        WHEN 2 THEN N'COALESCE([D].[ExpressionId], [O].[ExpressionId]) <= @ExpressionId'
        WHEN 3 THEN N'COALESCE([D].[ExpressionId], [O].[ExpressionId]) = @ExpressionId'
        WHEN 4 THEN N'COALESCE([D].[ExpressionId], [O].[ExpressionId]) <> @ExpressionId'
        WHEN 5 THEN N'COALESCE([D].[ExpressionId], [O].[ExpressionId]) >= @ExpressionId'
        WHEN 6 THEN N'COALESCE([D].[ExpressionId], [O].[ExpressionId]) > @ExpressionId'
        WHEN 7 THEN N'COALESCE([D].[ExpressionId], [O].[ExpressionId]) IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@ExpressionId_vals))'
        WHEN 8 THEN N'COALESCE([D].[ExpressionId], [O].[ExpressionId]) NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@ExpressionId_vals))'
        WHEN 9 THEN N'COALESCE([D].[ExpressionId], [O].[ExpressionId]) LIKE @ExpressionId'
