        WHEN 11 THEN N'COALESCE([D].[ExpressionId], [O].[ExpressionId]) BETWEEN @ExpressionId_v1 AND @ExpressionId_v2'
        WHEN 12 THEN N'COALESCE([D].[ExpressionId], [O].[ExpressionId]) NOT BETWEEN @ExpressionId_v1 AND @ExpressionId_v2'
        WHEN 13 THEN N'COALESCE([D].[ExpressionId], [O].[ExpressionId]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[ExpressionId], [O].[ExpressionId]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'PropertyId' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[PropertyId], [O].[PropertyId]) IS NULL'
                END ELSE
                IF @S_PropertyId_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_PropertyId_comparator = 1 AND @S_PropertyId_v IS NOT NULL)
               OR (@S_PropertyId_comparator = 2 AND @S_PropertyId_v IS NOT NULL)
               OR (@S_PropertyId_comparator = 3 AND @S_PropertyId_v IS NOT NULL)
               OR (@S_PropertyId_comparator = 4 AND @S_PropertyId_v IS NOT NULL)
               OR (@S_PropertyId_comparator = 5 AND @S_PropertyId_v IS NOT NULL)
               OR (@S_PropertyId_comparator = 6 AND @S_PropertyId_v IS NOT NULL)
               OR (@S_PropertyId_comparator = 7 AND @S_PropertyId_vals IS NOT NULL)
               OR (@S_PropertyId_comparator = 8 AND @S_PropertyId_vals IS NOT NULL)
               OR (@S_PropertyId_comparator = 9 AND @S_PropertyId_v IS NOT NULL)
               OR (@S_PropertyId_comparator = 10 AND @S_PropertyId_v IS NOT NULL)
               OR (@S_PropertyId_comparator = 11 AND @S_PropertyId_v1 IS NOT NULL AND @S_PropertyId_v2 IS NOT NULL)
               OR (@S_PropertyId_comparator = 12 AND @S_PropertyId_v1 IS NOT NULL AND @S_PropertyId_v2 IS NOT NULL)
               OR (@S_PropertyId_comparator = 13)
               OR (@S_PropertyId_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_PropertyId_comparator
        WHEN 1 THEN N'COALESCE([D].[PropertyId], [O].[PropertyId]) < @PropertyId'
        WHEN 2 THEN N'COALESCE([D].[PropertyId], [O].[PropertyId]) <= @PropertyId'
        WHEN 3 THEN N'COALESCE([D].[PropertyId], [O].[PropertyId]) = @PropertyId'
        WHEN 4 THEN N'COALESCE([D].[PropertyId], [O].[PropertyId]) <> @PropertyId'
        WHEN 5 THEN N'COALESCE([D].[PropertyId], [O].[PropertyId]) >= @PropertyId'
        WHEN 6 THEN N'COALESCE([D].[PropertyId], [O].[PropertyId]) > @PropertyId'
        WHEN 7 THEN N'COALESCE([D].[PropertyId], [O].[PropertyId]) IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@PropertyId_vals))'
        WHEN 8 THEN N'COALESCE([D].[PropertyId], [O].[PropertyId]) NOT IN (SELECT CAST([value] AS bigint) FROM OPENJSON(@PropertyId_vals))'
        WHEN 9 THEN N'COALESCE([D].[PropertyId], [O].[PropertyId]) LIKE @PropertyId'
        WHEN 10 THEN N'COALESCE([D].[PropertyId], [O].[PropertyId]) NOT LIKE @PropertyId'
        WHEN 11 THEN N'COALESCE([D].[PropertyId], [O].[PropertyId]) BETWEEN @PropertyId_v1 AND @PropertyId_v2'
        WHEN 12 THEN N'COALESCE([D].[PropertyId], [O].[PropertyId]) NOT BETWEEN @PropertyId_v1 AND @PropertyId_v2'
        WHEN 13 THEN N'COALESCE([D].[PropertyId], [O].[PropertyId]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[PropertyId], [O].[PropertyId]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
