                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'Value' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[Value], [O].[Value]) IS NULL'
                END ELSE
                IF @S_Value_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_Value_comparator = 1 AND @S_Value_v IS NOT NULL)
               OR (@S_Value_comparator = 2 AND @S_Value_v IS NOT NULL)
               OR (@S_Value_comparator = 3 AND @S_Value_v IS NOT NULL)
               OR (@S_Value_comparator = 4 AND @S_Value_v IS NOT NULL)
               OR (@S_Value_comparator = 5 AND @S_Value_v IS NOT NULL)
               OR (@S_Value_comparator = 6 AND @S_Value_v IS NOT NULL)
               OR (@S_Value_comparator = 7 AND @S_Value_vals IS NOT NULL)
               OR (@S_Value_comparator = 8 AND @S_Value_vals IS NOT NULL)
               OR (@S_Value_comparator = 9 AND @S_Value_v IS NOT NULL)
               OR (@S_Value_comparator = 10 AND @S_Value_v IS NOT NULL)
               OR (@S_Value_comparator = 13)
               OR (@S_Value_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_Value_comparator
        WHEN 1 THEN N'COALESCE([D].[Value], [O].[Value]) < @Value'
        WHEN 2 THEN N'COALESCE([D].[Value], [O].[Value]) <= @Value'
        WHEN 3 THEN N'COALESCE([D].[Value], [O].[Value]) = @Value'
        WHEN 4 THEN N'COALESCE([D].[Value], [O].[Value]) <> @Value'
        WHEN 5 THEN N'COALESCE([D].[Value], [O].[Value]) >= @Value'
        WHEN 6 THEN N'COALESCE([D].[Value], [O].[Value]) > @Value'
        WHEN 7 THEN N'COALESCE([D].[Value], [O].[Value]) IN (SELECT CAST([value] AS nvarchar(max)) FROM OPENJSON(@Value_vals))'
        WHEN 8 THEN N'COALESCE([D].[Value], [O].[Value]) NOT IN (SELECT CAST([value] AS nvarchar(max)) FROM OPENJSON(@Value_vals))'
        WHEN 9 THEN N'COALESCE([D].[Value], [O].[Value]) LIKE @Value'
        WHEN 10 THEN N'COALESCE([D].[Value], [O].[Value]) NOT LIKE @Value'
        WHEN 11 THEN N'COALESCE([D].[Value], [O].[Value]) BETWEEN @Value_v1 AND @Value_v2'
        WHEN 12 THEN N'COALESCE([D].[Value], [O].[Value]) NOT BETWEEN @Value_v1 AND @Value_v2'
        WHEN 13 THEN N'COALESCE([D].[Value], [O].[Value]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[Value], [O].[Value]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF EXISTS(SELECT 1 FROM OPENJSON(@Search) WHERE [key] = 'ElseValue' AND [type] = 0) BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    SET @Where = @Where + 'COALESCE([D].[ElseValue], [O].[ElseValue]) IS NULL'
                END ELSE
                IF @S_ElseValue_comparator IS NOT NULL BEGIN
                    IF @Where <> '' SET @Where = @Where + ' AND '
                    IF (@S_ElseValue_comparator = 1 AND @S_ElseValue_v IS NOT NULL)
               OR (@S_ElseValue_comparator = 2 AND @S_ElseValue_v IS NOT NULL)
               OR (@S_ElseValue_comparator = 3 AND @S_ElseValue_v IS NOT NULL)
               OR (@S_ElseValue_comparator = 4 AND @S_ElseValue_v IS NOT NULL)
               OR (@S_ElseValue_comparator = 5 AND @S_ElseValue_v IS NOT NULL)
               OR (@S_ElseValue_comparator = 6 AND @S_ElseValue_v IS NOT NULL)
               OR (@S_ElseValue_comparator = 7 AND @S_ElseValue_vals IS NOT NULL)
               OR (@S_ElseValue_comparator = 8 AND @S_ElseValue_vals IS NOT NULL)
               OR (@S_ElseValue_comparator = 9 AND @S_ElseValue_v IS NOT NULL)
               OR (@S_ElseValue_comparator = 10 AND @S_ElseValue_v IS NOT NULL)
               OR (@S_ElseValue_comparator = 13)
               OR (@S_ElseValue_comparator = 14) BEGIN
                        SET @ComparatorPredicate = CASE @S_ElseValue_comparator
        WHEN 1 THEN N'COALESCE([D].[ElseValue], [O].[ElseValue]) < @ElseValue'
        WHEN 2 THEN N'COALESCE([D].[ElseValue], [O].[ElseValue]) <= @ElseValue'
        WHEN 3 THEN N'COALESCE([D].[ElseValue], [O].[ElseValue]) = @ElseValue'
        WHEN 4 THEN N'COALESCE([D].[ElseValue], [O].[ElseValue]) <> @ElseValue'
        WHEN 5 THEN N'COALESCE([D].[ElseValue], [O].[ElseValue]) >= @ElseValue'
        WHEN 6 THEN N'COALESCE([D].[ElseValue], [O].[ElseValue]) > @ElseValue'
        WHEN 7 THEN N'COALESCE([D].[ElseValue], [O].[ElseValue]) IN (SELECT CAST([value] AS nvarchar(max)) FROM OPENJSON(@ElseValue_vals))'
        WHEN 8 THEN N'COALESCE([D].[ElseValue], [O].[ElseValue]) NOT IN (SELECT CAST([value] AS nvarchar(max)) FROM OPENJSON(@ElseValue_vals))'
        WHEN 9 THEN N'COALESCE([D].[ElseValue], [O].[ElseValue]) LIKE @ElseValue'
        WHEN 10 THEN N'COALESCE([D].[ElseValue], [O].[ElseValue]) NOT LIKE @ElseValue'
        WHEN 11 THEN N'COALESCE([D].[ElseValue], [O].[ElseValue]) BETWEEN @ElseValue_v1 AND @ElseValue_v2'
        WHEN 12 THEN N'COALESCE([D].[ElseValue], [O].[ElseValue]) NOT BETWEEN @ElseValue_v1 AND @ElseValue_v2'
        WHEN 13 THEN N'COALESCE([D].[ElseValue], [O].[ElseValue]) IS NULL'
        WHEN 14 THEN N'COALESCE([D].[ElseValue], [O].[ElseValue]) IS NOT NULL'
    END
                        SET @Where = @Where + ISNULL(@ComparatorPredicate, '')
                    END
                END
                IF @Where <> '' BEGIN
                    SET @sql = N'SELECT TOP 1 @r = [#].[Recno]
                                    FROM [#tmpTable] [#]
                                        LEFT JOIN [dbo].[Behaviors] [D] ON [D].[Id] = [#].[Id] AND [#].[_] = ''T''
                                        LEFT JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id] AND [#].[_] = ''O''
                                    WHERE ' + @Where
                    EXEC sp_executesql @sql
                                       ,N'@Id bigint,@Id_v1 bigint,@Id_v2 bigint,@Id_vals NVARCHAR(MAX),@ColumnId bigint,@ColumnId_v1 bigint,@ColumnId_v2 bigint,@ColumnId_vals NVARCHAR(MAX),@ExpressionId bigint,@ExpressionId_v1 bigint,@ExpressionId_v2 bigint,@ExpressionId_vals NVARCHAR(MAX),@PropertyId bigint,@PropertyId_v1 bigint,@PropertyId_v2 bigint,@PropertyId_vals NVARCHAR(MAX),@Value nvarchar(max),@Value_vals NVARCHAR(MAX),@ElseValue nvarchar(max),@ElseValue_vals NVARCHAR(MAX), @r BIGINT OUTPUT'
                                       ,@Id = @S_Id_v
                                       ,@Id_v1 = @S_Id_v1
                                       ,@Id_v2 = @S_Id_v2
                                       ,@Id_vals = @S_Id_vals
                                       ,@ColumnId = @S_ColumnId_v
                                       ,@ColumnId_v1 = @S_ColumnId_v1
                                       ,@ColumnId_v2 = @S_ColumnId_v2
                                       ,@ColumnId_vals = @S_ColumnId_vals
                                       ,@ExpressionId = @S_ExpressionId_v
                                       ,@ExpressionId_v1 = @S_ExpressionId_v1
                                       ,@ExpressionId_v2 = @S_ExpressionId_v2
                                       ,@ExpressionId_vals = @S_ExpressionId_vals
                                       ,@PropertyId = @S_PropertyId_v
                                       ,@PropertyId_v1 = @S_PropertyId_v1
                                       ,@PropertyId_v2 = @S_PropertyId_v2
                                       ,@PropertyId_vals = @S_PropertyId_vals
                                       ,@Value = @S_Value_v
                                       ,@Value_vals = @S_Value_vals
                                       ,@ElseValue = @S_ElseValue_v
                                       ,@ElseValue_vals = @S_ElseValue_vals
                                       ,@r = @Recno OUTPUT
                    SET @PageNumber = CASE WHEN ISNULL(@Recno, 0) > 0 THEN ((@Recno - 1) / @LimitRows) + 1 ELSE @MaxPage END
                    IF ISNULL(@Recno, 0) > 0 SET @SearchRecno = @Recno
                END
            END
            IF ABS(@PageNumber) > @MaxPage
                SET @PageNumber = CASE WHEN @PageNumber < 0 THEN -@MaxPage ELSE @MaxPage END
            ELSE IF @PageNumber < 0
                SET @PageNumber = @MaxPage - ABS(@PageNumber) + 1
            SET @OffSet = (@PageNumber - 1) * @LimitRows
            IF @PaddingGridLastPage = 1 AND @SearchRecno IS NULL AND @OffSet + @LimitRows > @RowCount
                SET @OffSet = CASE WHEN @RowCount > @LimitRows THEN @RowCount - @LimitRows ELSE 0 END
        END
        SELECT TOP 0 CAST(NULL AS NVARCHAR(50)) AS [Kind]
                    ,CAST(NULL AS BIGINT) AS [Recno]
                    ,CAST(NULL AS bigint) AS [Id]
                    ,CAST(NULL AS bigint) AS [ColumnId]
                    ,CAST(NULL AS bigint) AS [ExpressionId]
                    ,CAST(NULL AS bigint) AS [PropertyId]
                    ,CAST(NULL AS nvarchar(max)) AS [Value]
                    ,CAST(NULL AS nvarchar(max)) AS [ElseValue]
            INTO [#result]
        SET @sql = 'INSERT [#result]
                        SELECT ''Behavior'' AS [Kind]
                              ,[#].[Recno]
                              ,[T].[Id]
                              ,[T].[ColumnId]
                              ,[T].[ExpressionId]
                              ,[T].[PropertyId]
                              ,[T].[Value]
                              ,[T].[ElseValue]
                            FROM [#tmpTable] [#]
                                INNER JOIN [dbo].[Behaviors] [T] ON [T].[Id] = [#].[Id]
                            WHERE [#].[_] = ''T''
                        UNION ALL
                            SELECT ''Behavior'' AS [Kind]
                                  ,[#].[Recno]
                                  ,[O].[Id]
                                  ,[O].[ColumnId]
                                  ,[O].[ExpressionId]
                                  ,[O].[PropertyId]
                                  ,[O].[Value]
                                  ,[O].[ElseValue]
                                FROM [#tmpTable] [#]
                                    INNER JOIN [#tmpOperations] [O] ON [O].[Id] = [#].[Id]
                                WHERE [#].[_] = ''O''
                        ORDER BY [Recno]
                        OFFSET ' + CAST(@OffSet AS NVARCHAR(20)) + ' ROWS
                        FETCH NEXT ' + CAST(@LimitRows AS NVARCHAR(20)) + ' ROWS ONLY'
        EXEC sp_executesql @sql
        SELECT (SELECT [Kind]
                      ,[Id]
                      ,[ColumnId]
                      ,[ExpressionId]
                      ,[PropertyId]
                      ,[Value]
                      ,[ElseValue]
                    FROM [#result] FOR JSON PATH) AS [result]
        SET @ReturnValue = @RowCount

    RETURN 0
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[ReferenceValidate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[ReferenceValidate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[ReferenceValidate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[ReferenceValidate](@SessionId BIGINT
                                               ,@TransactionId BIGINT
                                               ,@UserName NVARCHAR(25)
                                               ,@Action NVARCHAR(15)
                                               ,@LastRecord NVARCHAR(max)
                                               ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED
    IF @SessionId IS NULL
            THROW 51000, 'Valor de @SessionId é requerido', 1
        IF @UserName IS NULL
            THROW 51000, 'Valor de @UserName é requerido', 1
        IF @Action IS NULL
            THROW 51000, 'Valor de @Action é requerido', 1
        IF @Action NOT IN ('create', 'update', 'delete')
            THROW 51000, 'Valor de @Action é inválido', 1
        IF @Action = 'delete' BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
        END ELSE BEGIN
            IF @ActualRecord IS NULL
                THROW 51000, 'Valor de @ActualRecord é requerido', 1
            IF ISJSON(@ActualRecord) = 0
                THROW 51000, 'Valor de @ActualRecord não está no formato JSON', 1
        END
        IF @TransactionId IS NULL
            THROW 51000, 'Valor de @TransactionId é requerido', 1
        DECLARE @IsConfirmed BIT
               ,@CreatedBy NVARCHAR(25)
               ,@IsPendingCreate BIT = 0
               ,@W_Id bigint

        IF @Action = 'delete' BEGIN
            SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

        END ELSE BEGIN
            SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        END
        SELECT @IsConfirmed = [IsConfirmed]
              ,@CreatedBy = [CreatedBy]
            FROM [dbo].[Transactions]
            WHERE [Id] = @TransactionId
                  AND [SessionId] = @SessionId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Transação inexistente', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Transação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1;
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @W_Id IS NULL BEGIN
            SET @ErrorMessage = 'Valor de Id em @ActualRecord é requerido.';
            THROW 51000, @ErrorMessage, 1
        END
        IF @W_Id < CAST('1' AS bigint)
            THROW 51000, 'Valor de Id em @ActualRecord deve ser maior que ou igual a 1', 1
        IF EXISTS(SELECT 1 FROM [dbo].[References] WHERE [Id] = @W_Id) AND @Action = 'create'
            THROW 51000, 'Chave-primária já existe em References', 1
        ELSE IF @Action = 'delete' AND EXISTS(SELECT 1
                                    FROM [dbo].[Operations]
                                    WHERE [TransactionId] = @TransactionId
                                          AND [TableName] = 'References'
                                          AND [IsConfirmed] IS NULL
                                          AND [Action] = 'create'
                                          AND                                           CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id)
            SET @IsPendingCreate = 1
        ELSE IF @Action <> 'create' AND NOT EXISTS(SELECT 1 FROM [dbo].[References] WHERE [Id] = @W_Id)
            THROW 51000, 'Chave-primária não existe em References', 1
        IF @Action <> 'create' AND @IsPendingCreate = 0 BEGIN
            IF @LastRecord IS NULL
                THROW 51000, 'Valor de @LastRecord é requerido', 1
            IF ISJSON(@LastRecord) = 0
                THROW 51000, 'Valor de @LastRecord não está no formato JSON', 1
            IF NOT EXISTS(SELECT 1
                            FROM [dbo].[References]
                            WHERE [Id] = JSON_VALUE(@LastRecord, '$.Id')
                                  AND [FkTableId] = JSON_VALUE(@LastRecord, '$.FkTableId')
                                  AND [dbo].[IS_EQUAL]([PkTableId], JSON_VALUE(@LastRecord, '$.PkTableId'), 'bigint') = 1
                                  AND [dbo].[IS_EQUAL]([Name], JSON_VALUE(@LastRecord, '$.Name'), 'nvarchar') = 1
                                  AND [dbo].[IS_EQUAL]([IsParentChildren], JSON_VALUE(@LastRecord, '$.IsParentChildren'), 'bit') = 1)
            AND NOT EXISTS(SELECT 1
                            FROM [dbo].[Operations]
                            WHERE [TransactionId] = @TransactionId
                                  AND [TableName] = 'References'
                                  AND [IsConfirmed] IS NULL
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') = JSON_VALUE(@LastRecord, '$.Id')
                                  AND JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.FkTableId') = JSON_VALUE(@LastRecord, '$.FkTableId')
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.PkTableId'), JSON_VALUE(@LastRecord, '$.PkTableId'), 'bigint') = 1
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Name'), JSON_VALUE(@LastRecord, '$.Name'), 'nvarchar') = 1
                                  AND [dbo].[IS_EQUAL](JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.IsParentChildren'), JSON_VALUE(@LastRecord, '$.IsParentChildren'), 'bit') = 1)
                THROW 51000, 'Registro de References alterado por outro usuário', 1
        END

        IF @Action IN ('create', 'update') BEGIN

            DECLARE @W_FkTableId nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.FkTableId') AS nvarchar(25))
                   ,@W_PkTableId bigint = CAST(JSON_VALUE(@ActualRecord, '$.PkTableId') AS bigint)
                   ,@W_Name nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(50))
                   ,@W_IsParentChildren bit = CAST(JSON_VALUE(@ActualRecord, '$.IsParentChildren') AS bit)

            IF @W_FkTableId IS NULL
                THROW 51000, 'Valor de FkTableId em @ActualRecord é requerido.', 1
        END

    RETURN @TransactionId
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[ReferencePersist]
**********************************************************************************/
IF(SELECT object_id('[dbo].[ReferencePersist]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[ReferencePersist] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[ReferencePersist](@Login NVARCHAR(MAX)
                                              ,@TransactionId BIGINT
                                              ,@Action NVARCHAR(15)
                                              ,@LastRecord NVARCHAR(max)
                                              ,@ActualRecord NVARCHAR(max)) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(255)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @OperationId BIGINT
               ,@CreatedBy NVARCHAR(25)
               ,@ActionAux NVARCHAR(15)
               ,@IsConfirmed BIT
               ,@W_Id bigint

    IF @Action = 'delete' BEGIN
        SET @W_Id = CAST(JSON_VALUE(@LastRecord, '$.Id') AS bigint)

    END ELSE BEGIN
        SET @W_Id = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

    END
    EXEC @TransactionId = [dbo].[ReferenceValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        SELECT @OperationId = [Id]
              ,@CreatedBy = [CreatedBy]
              ,@ActionAux = [Action]
              ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [TransactionId] = @TransactionId
                  AND [TableName] = 'References'
                  AND [IsConfirmed] IS NULL
                  AND CAST(JSON_VALUE(ISNULL([ActualRecord], [LastRecord]), '$.Id') AS bigint) = @W_Id
        IF @@ROWCOUNT = 0 BEGIN
            EXEC [dbo].[NewOperationId] 'crudex', 'crudex', @OperationId OUT
            SET IDENTITY_INSERT [dbo].[Operations] ON
            INSERT INTO [dbo].[Operations] ([Id]
                                             ,[TransactionId]
                                             ,[TableName]
                                             ,[Action]
                                             ,[LastRecord]
                                             ,[ActualRecord]
                                             ,[IsConfirmed]
                                             ,[CreatedAt]
                                             ,[CreatedBy])
                                       VALUES(@OperationId
                                             ,@TransactionId
                                             ,'References'
                                             ,@Action
                                             ,@LastRecord
                                             ,@ActualRecord
                                             ,NULL
                                             ,GETDATE()
                                             ,@UserName)
            SET IDENTITY_INSERT [dbo].[Operations] OFF
        END ELSE IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        ELSE IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        ELSE IF @ActionAux = 'delete'
            THROW 51000, 'Registro excluído nesta transação', 1
        ELSE IF @Action = 'create'
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE IF @Action = 'update' BEGIN
            IF @ActionAux = 'create'
                EXEC [dbo].[ReferenceValidate] @SessionId, @TransactionId, @UserName, 'create', NULL, @ActualRecord
            UPDATE [dbo].[Operations]
                SET [ActualRecord] = @ActualRecord
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        END
        ELSE IF @ActionAux = 'create'
            UPDATE [dbo].[Operations] 
                SET [IsConfirmed] = 0
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId
        ELSE
            UPDATE [dbo].[Operations]
                SET [Action] = 'delete'
                   ,[LastRecord] = @LastRecord
                   ,[ActualRecord] = NULL
                   ,[UpdatedAt] = GETDATE()
                   ,[UpdatedBy] = @UserName
                WHERE [Id] = @OperationId

    RETURN CAST(@OperationId AS BIGINT)
END
GO

/**********************************************************************************
Criar stored procedure [dbo].[ReferenceCreate]
**********************************************************************************/
IF(SELECT object_id('[dbo].[ReferenceCreate]', 'P')) IS NULL
    EXEC('CREATE PROCEDURE [dbo].[ReferenceCreate] AS PRINT 1')
GO
ALTER PROCEDURE [dbo].[ReferenceCreate](@Login NVARCHAR(MAX)
                                             ,@OperationId BIGINT) AS BEGIN
    DECLARE @ErrorMessage NVARCHAR(MAX)

    SET NOCOUNT ON
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED

    DECLARE @SessionId BIGINT
           ,@UserName NVARCHAR(25) = CAST(JSON_VALUE(@Login, '$.UserName') AS NVARCHAR(25))
    DECLARE @LoginReturn BIGINT

    EXEC [dbo].[Login] @Parameters = @Login, @ReturnValue = @LoginReturn OUTPUT
    SET @SessionId = CAST(JSON_VALUE(@Login, '$.LoginId') AS BIGINT)
    IF @SessionId IS NULL
        THROW 51000, 'SessionId é requerido', 1

    DECLARE @TransactionId BIGINT
               ,@TransactionIdAux BIGINT
               ,@TableName NVARCHAR(25)
               ,@Action NVARCHAR(15)
               ,@CreatedBy NVARCHAR(25)
               ,@LastRecord NVARCHAR(max)
               ,@ActualRecord NVARCHAR(max)
               ,@IsConfirmed BIT

    IF @OperationId IS NULL
            THROW 51000, 'Valor de @OperationId requerido', 1
        SELECT @TransactionId = [TransactionId]
               ,@TableName = [TableName]
               ,@Action = [Action]
               ,@CreatedBy = [CreatedBy]
               ,@LastRecord = [LastRecord]
               ,@ActualRecord = [ActualRecord]
               ,@IsConfirmed = [IsConfirmed]
            FROM [dbo].[Operations]
            WHERE [Id] = @OperationId
        IF @@ROWCOUNT = 0
            THROW 51000, 'Operação inexistente', 1
        IF @TableName <> 'References'
            THROW 51000, 'Tabela da operação é inválida', 1
        IF @IsConfirmed IS NOT NULL BEGIN
            SET @ErrorMessage = 'Operação já ' + CASE WHEN @IsConfirmed = 0 THEN 'cancelada' ELSE 'concluída' END;
            THROW 51000, @ErrorMessage, 1
        END
        IF @UserName <> @CreatedBy
            THROW 51000, 'Erro grave de segurança', 1
        IF @Action <> 'create'
            THROW 51000, 'Ação da operação é inválida para Create', 1
        EXEC @TransactionIdAux = [dbo].[ReferenceValidate] @SessionId, @TransactionId, @UserName, @Action, @LastRecord, @ActualRecord
        IF @TransactionId <> @TransactionIdAux
            THROW 51000, 'Transação da operação é inválida', 1
        DECLARE @W_Id bigint = CAST(JSON_VALUE(@ActualRecord, '$.Id') AS bigint)

        DECLARE @W_FkTableId nvarchar(25) = CAST(JSON_VALUE(@ActualRecord, '$.FkTableId') AS nvarchar(25))
               ,@W_PkTableId bigint = CAST(JSON_VALUE(@ActualRecord, '$.PkTableId') AS bigint)
               ,@W_Name nvarchar(50) = CAST(JSON_VALUE(@ActualRecord, '$.Name') AS nvarchar(50))
               ,@W_IsParentChildren bit = CAST(JSON_VALUE(@ActualRecord, '$.IsParentChildren') AS bit)

        INSERT INTO [dbo].[References] ([Id]
                                            ,[FkTableId]
                                            ,[PkTableId]
                                            ,[Name]
                                            ,[IsParentChildren]
                                            ,[CreatedAt]
                                            ,[CreatedBy])
                                      VALUES (@W_Id
                                             ,@W_FkTableId
                                             ,@W_PkTableId
                                             ,@W_Name
                                             ,@W_IsParentChildren
                                             ,GETDATE()
                                             ,@UserName)
        UPDATE [dbo].[Operations]
            SET [IsConfirmed] = 1
                ,[UpdatedAt] = GETDATE()
                ,[UpdatedBy] = @UserName
            WHERE [Id] = @OperationId

    RETURN @TransactionId
END
GO

